void publish_peer_state_snapshot(const coop::StatePacket& packet) {
    AcquireSRWLockExclusive(&g_state_net.peer_state_lock);
    if (g_state_net.has_peer_state.load(std::memory_order_relaxed) &&
        static_cast<std::int32_t>(packet.sequence -
                                  g_state_net.peer_state_sequence) <= 0) {
        ReleaseSRWLockExclusive(&g_state_net.peer_state_lock);
        return;
    }
    coop::StatePacket sanitized = packet;
    sanitized.input_buttons =
        remote_puppet_actions_from_peer(packet.input_buttons);
    sanitized.buttons_pressed =
        remote_puppet_actions_from_peer(packet.buttons_pressed);
    sanitized.buttons_released =
        remote_puppet_actions_from_peer(packet.buttons_released);
    const bool previous_melee_held =
        g_state_net.has_peer_state.load(std::memory_order_relaxed) &&
        (g_state_net.peer_state.input_buttons &
         kJoypadMeleeTriangleButtonMask) != 0;
    const bool incoming_melee_held =
        (sanitized.input_buttons & kJoypadMeleeTriangleButtonMask) != 0;
    const bool incoming_melee_press =
        (sanitized.buttons_pressed & kJoypadMeleeTriangleButtonMask) != 0 ||
        (incoming_melee_held && !previous_melee_held);
    const bool previous_evade_start_held =
        g_state_net.has_peer_state.load(std::memory_order_relaxed) &&
        (g_state_net.peer_state.input_buttons &
         kJoypadEvadeStartIntentMask) != 0;
    const bool incoming_evade_start_held =
        (sanitized.input_buttons & kJoypadEvadeStartIntentMask) != 0;
    const bool incoming_evade_start_press =
        (sanitized.buttons_pressed & kJoypadEvadeStartIntentMask) != 0 ||
        (incoming_evade_start_held && !previous_evade_start_held);
    g_state_net.peer_state = sanitized;
    g_state_net.peer_state_sequence = packet.sequence;
    if (g_enable_puppet_melee_callsite_relay && incoming_melee_press) {
        std::uint32_t pending =
            g_state_net.pending_puppet_melee_presses.load(
                std::memory_order_relaxed);
        while (pending < 4 &&
               !g_state_net.pending_puppet_melee_presses.compare_exchange_weak(
                   pending, pending + 1, std::memory_order_release,
                   std::memory_order_relaxed)) {
        }
    }
    g_state_net.pending_button_presses.fetch_or(
        sanitized.buttons_pressed, std::memory_order_release);
    const std::uint64_t incoming_traversal =
        sanitized.input_buttons | sanitized.buttons_pressed;
    if ((incoming_traversal & kJoypadEvadeStartIntentMask) != 0) {
        constexpr ULONGLONG kEvadeStartForceWindowMs = 400;
        const ULONGLONG now = GetTickCount64();
        const ULONGLONG previous_until =
            g_state_net.puppet_evade_start_force_until_ms.exchange(
                now + kEvadeStartForceWindowMs, std::memory_order_acq_rel);
        if (incoming_evade_start_press || previous_until <= now) {
            g_state_net.puppet_evade_start_event_sequence.store(
                packet.sequence, std::memory_order_release);
            static std::atomic<unsigned> evade_start_latch_logs{0};
            const unsigned log_index = evade_start_latch_logs.fetch_add(
                1, std::memory_order_relaxed);
            if (log_index < 24) {
                std::ostringstream line;
                line << "TRAVERSAL-EVADE-START-LATCH seq=" << packet.sequence
                     << " held=" << incoming_evade_start_held
                     << " pressed=" << incoming_evade_start_press;
                boot_log_line(line.str().c_str());
            }
        }
    }
    if ((incoming_traversal & kJoypadEdgeDropIntentMask) != 0) {
        constexpr ULONGLONG kEdgeDropForceWindowMs = 400;
        const ULONGLONG now = GetTickCount64();
        const ULONGLONG previous_until =
            g_state_net.puppet_edge_drop_force_until_ms.exchange(
                now + kEdgeDropForceWindowMs, std::memory_order_acq_rel);
        const bool incoming_press =
            (sanitized.buttons_pressed & kJoypadEdgeDropIntentMask) != 0;
        if (incoming_press || previous_until <= now) {
            g_state_net.puppet_edge_drop_event_sequence.store(
                packet.sequence, std::memory_order_release);
            static std::atomic<unsigned> edge_drop_latch_logs{0};
            const unsigned log_index = edge_drop_latch_logs.fetch_add(
                1, std::memory_order_relaxed);
            if (log_index < 12) {
                std::ostringstream line;
                line << "TRAVERSAL-EDGE-DROP-LATCH seq=" << packet.sequence
                     << " held="
                     << ((sanitized.input_buttons &
                          kJoypadEdgeDropIntentMask) != 0)
                     << " pressed="
                     << ((sanitized.buttons_pressed &
                          kJoypadEdgeDropIntentMask) != 0);
                boot_log_line(line.str().c_str());
            }
        }
    }
    g_state_net.puppet_traversal_force.store(
        incoming_traversal & kJoypadTraversalRelayMask,
        std::memory_order_release);
    if ((packet.flags & 16) != 0) {
        g_state_net.pending_authoritative_teleport.store(
            true, std::memory_order_release);
    }
    ReleaseSRWLockExclusive(&g_state_net.peer_state_lock);
    g_state_net.peer_state_received_ms.store(GetTickCount64(), std::memory_order_release);
    g_state_net.has_peer_state.store(true, std::memory_order_release);
}

bool copy_peer_state_snapshot(coop::StatePacket& out) {
    if (!g_state_net.has_peer_state.load(std::memory_order_acquire)) {
        return false;
    }
    const ULONGLONG received =
        g_state_net.peer_state_received_ms.load(std::memory_order_acquire);
    if (received == 0 || GetTickCount64() - received > 1500) {
        return false;
    }
    AcquireSRWLockShared(&g_state_net.peer_state_lock);
    out = g_state_net.peer_state;
    ReleaseSRWLockShared(&g_state_net.peer_state_lock);
    return true;
}

// Input and transform require a fresh packet. The last confirmed health remains
// authoritative while an alt-tabbed instance is suspended and stops sending.
