// =====  INPUT HOOKS: KEYBOARD / JOYPAD-3 ISOLATION & ANALOG ROUTE
// ============================================================================
bool __fastcall hooked_gameinfo_keyboard_mode(void* game_info) {
    if (g_force_joypad3_analog_thread.load(std::memory_order_acquire) ==
        GetCurrentThreadId()) {
        g_force_joypad3_analog_hits.fetch_add(1, std::memory_order_relaxed);
        return false;
    }
    return g_original_gameinfo_keyboard_mode(game_info);
}

char __fastcall hooked_evaluate_keyboard_button_binding(
    void* joypad, void* descriptor, std::uint32_t command_hash) {
    // Keyboard masks are global to the process, so without this filter a local
    // jump/crouch/etc. is accepted for both Player Joypads. Joypad 3 already
    // receives its peer's normalized per-Joypad masks through source+0x518.
    if (g_state_net.enabled && joypad != nullptr) {
        void* const frame_state =
            *reinterpret_cast<void**>(g_module + 0x3FE1088);
        if (frame_state != nullptr) {
            void* const remote_joypad = static_cast<std::byte*>(frame_state) +
                                        0xDB0 + 0xBF0 * 3;
            if (joypad == remote_joypad) {
                return 0;
            }
        }
    }
    return g_original_evaluate_keyboard_button_binding(
        joypad, descriptor, command_hash);
}

bool install_joypad3_keyboard_isolation() {
    auto* const target = reinterpret_cast<std::uint8_t*>(
        g_module + 0x1838740);
    constexpr std::array<std::uint8_t, 15> expected{
        0x48, 0x8B, 0xC4, 0x48, 0x89, 0x58, 0x20, 0x55,
        0x57, 0x41, 0x54, 0x41, 0x55, 0x41, 0x57,
    };
    if (std::memcmp(target, expected.data(), expected.size()) != 0) {
        log_line("Joypad3 keyboard isolation skipped: unexpected prologue");
        return false;
    }

    constexpr std::size_t kPatchSize = expected.size();
    constexpr std::size_t kEntryJumpSize = 12;
    constexpr std::size_t kReturnJumpSize = 14;
    auto* const trampoline = static_cast<std::uint8_t*>(VirtualAlloc(
        nullptr, kPatchSize + kReturnJumpSize, MEM_COMMIT | MEM_RESERVE,
        PAGE_EXECUTE_READWRITE));
    if (trampoline == nullptr) {
        log_line("Joypad3 keyboard isolation skipped: trampoline allocation failed");
        return false;
    }
    std::memcpy(trampoline, target, kPatchSize);
    auto* const jump_back = trampoline + kPatchSize;
    // The copied prologue sets RAX=entry RSP and the original body still uses it
    // at 0x14183875D. A mov-rax/jmp-rax return corrupts that live value. Use a
    // RIP-indirect absolute jump, which preserves every register.
    jump_back[0] = 0xFF;
    jump_back[1] = 0x25;
    *reinterpret_cast<std::uint32_t*>(jump_back + 2) = 0;
    *reinterpret_cast<std::uintptr_t*>(jump_back + 6) =
        reinterpret_cast<std::uintptr_t>(target + kPatchSize);
    FlushInstructionCache(
        GetCurrentProcess(), trampoline, kPatchSize + kReturnJumpSize);
    g_original_evaluate_keyboard_button_binding =
        reinterpret_cast<EvaluateKeyboardButtonBindingFunction>(trampoline);

    DWORD old_protection = 0;
    if (!VirtualProtect(target, kPatchSize, PAGE_EXECUTE_READWRITE,
                        &old_protection)) {
        VirtualFree(trampoline, 0, MEM_RELEASE);
        g_original_evaluate_keyboard_button_binding = nullptr;
        log_line("Joypad3 keyboard isolation skipped: VirtualProtect failed");
        return false;
    }
    target[0] = 0x48;
    target[1] = 0xB8;
    *reinterpret_cast<std::uintptr_t*>(target + 2) =
        reinterpret_cast<std::uintptr_t>(&hooked_evaluate_keyboard_button_binding);
    target[10] = 0xFF;
    target[11] = 0xE0;
    std::memset(
        target + kEntryJumpSize, 0x90, kPatchSize - kEntryJumpSize);
    FlushInstructionCache(GetCurrentProcess(), target, kPatchSize);
    DWORD ignored = 0;
    VirtualProtect(target, kPatchSize, old_protection, &ignored);
    force_log_line("Joypad3 isolated from process-global keyboard command masks");
    return true;
}

// Force named traversal commands active on Joypad 3 while peer intent is latched.
// PC jump/evade often bind keyboard-only; our keyboard isolation returns 0 for
// Joypad 3, so EvaluateGamepadButtonBinding never sees a match even when face
// pads are present. IsCommandActive is the engine's authoritative gate for
// PlayerMoveStick jump/roll consumers — short-circuit it for the puppet only.
void* player_joypad_object(void* player) {
    if (player == nullptr || g_module == 0 ||
        readable_bytes(static_cast<std::byte*>(player) +
                       kPlayerJoypadIndexOffset) < sizeof(std::int32_t)) {
        return nullptr;
    }
    const auto joypad_index = *reinterpret_cast<const std::int32_t*>(
        static_cast<const std::byte*>(player) + kPlayerJoypadIndexOffset);
    if (joypad_index < 0 || joypad_index >= 6) {
        return nullptr;
    }
    void* const frame_state =
        *reinterpret_cast<void**>(g_module + kFrameStateGlobalRva);
    if (frame_state == nullptr) {
        return nullptr;
    }
    return static_cast<std::byte*>(frame_state) +
           kFrameStateScreenBlockBaseOffset +
           kFrameStateScreenBlockStride *
               static_cast<std::uintptr_t>(joypad_index);
}

void latch_local_player_edge_drop(const char* source) {
    constexpr ULONGLONG kLocalEdgeDropSendWindowMs = 250;
    const ULONGLONG now = GetTickCount64();
    const ULONGLONG previous_until =
        g_local_edge_drop_send_until_ms.exchange(
            now + kLocalEdgeDropSendWindowMs, std::memory_order_acq_rel);
    if (previous_until <= now) {
        std::ostringstream line;
        line << "TRAVERSAL-EDGE-DROP-LOCAL-CAPTURE source=" << source;
        boot_log_line(line.str().c_str());
    }
}

void latch_local_player_evade_start() {
    constexpr ULONGLONG kLocalEvadeStartSendWindowMs = 250;
    const ULONGLONG now = GetTickCount64();
    const ULONGLONG previous_until =
        g_local_evade_start_send_until_ms.exchange(
            now + kLocalEvadeStartSendWindowMs, std::memory_order_acq_rel);
    if (previous_until <= now) {
        boot_log_line(
            "TRAVERSAL-EVADE-START-LOCAL-CAPTURE source=PlayerEvade.slot16");
    }
}

void* player_evade_controller_owner(void* controller) {
    if (controller == nullptr ||
        readable_bytes(static_cast<const std::byte*>(controller) + 0x108) <
            sizeof(void*)) {
        return nullptr;
    }
    return *reinterpret_cast<void**>(
        static_cast<std::byte*>(controller) + 0x108);
}

char __fastcall hooked_player_evade_start_query(void* controller) {
    const std::uintptr_t return_address =
        reinterpret_cast<std::uintptr_t>(_ReturnAddress());
    const std::uintptr_t return_rva =
        return_address >= g_module ? return_address - g_module : 0;
    const char original = g_original_player_evade_start_query != nullptr
                              ? g_original_player_evade_start_query(controller)
                              : 0;
    if (!g_state_net.enabled ||
        return_rva != kPlayerMoveStickEvadeStartReturnRva ||
        player_evade_controller_owner(controller) != retained_player_object(1)) {
        return original;
    }
    const ULONGLONG now = GetTickCount64();
    const ULONGLONG force_until =
        g_state_net.puppet_evade_start_force_until_ms.load(
            std::memory_order_acquire);
    const std::uint32_t sequence =
        g_state_net.puppet_evade_start_event_sequence.load(
            std::memory_order_acquire);
    const std::uint32_t consumed_sequence =
        g_state_net.puppet_evade_start_consumed_sequence.load(
            std::memory_order_acquire);
    if (sequence == 0 || sequence == consumed_sequence || now >= force_until) {
        return original;
    }
    const std::uint32_t logged_sequence =
        g_state_net.puppet_evade_start_force_logged_sequence.exchange(
            sequence, std::memory_order_acq_rel);
    if (logged_sequence != sequence) {
        std::ostringstream line;
        line << "TRAVERSAL-EVADE-START-FORCE seq=" << sequence
             << " callsite=0x140F06408 original="
             << static_cast<unsigned>(original != 0)
             << " remainingMs=" << (force_until - now);
        boot_log_line(line.str().c_str());
    }
    return 1;
}

std::int64_t __fastcall hooked_player_evade_start_action(
    void* controller, void* move_basis, std::int64_t context, double scalar) {
    void* const owner = player_evade_controller_owner(controller);
    const std::int64_t result =
        g_original_player_evade_start_action != nullptr
            ? g_original_player_evade_start_action(
                  controller, move_basis, context, scalar)
            : 0;
    if (!g_state_net.enabled || owner == nullptr) {
        return result;
    }
    if (owner == retained_player_object(0)) {
        // Slot 16 is reached only after PlayerMoveStick accepted evade-start,
        // passed the contextual/vehicle gates and committed the native action.
        latch_local_player_evade_start();
        return result;
    }
    if (owner != retained_player_object(1)) {
        return result;
    }
    const ULONGLONG now = GetTickCount64();
    const ULONGLONG force_until =
        g_state_net.puppet_evade_start_force_until_ms.load(
            std::memory_order_acquire);
    const std::uint32_t sequence =
        g_state_net.puppet_evade_start_event_sequence.load(
            std::memory_order_acquire);
    if (sequence == 0 || now >= force_until) {
        return result;
    }
    const std::uint32_t previous_consumed =
        g_state_net.puppet_evade_start_consumed_sequence.exchange(
            sequence, std::memory_order_acq_rel);
    if (previous_consumed != sequence) {
        std::ostringstream line;
        line << "TRAVERSAL-EVADE-START-REMOTE-START seq=" << sequence
             << " remainingMs=" << (force_until - now);
        boot_log_line(line.str().c_str());
    }
    return result;
}

bool install_player_evade_start_action_relay() {
    auto* const vtable = reinterpret_cast<std::uintptr_t*>(
        g_module + kPlayerEvadeControllerVtableRva);
    auto* const query_slot = &vtable[kPlayerEvadeStartQueryVtableSlot];
    auto* const action_slot = &vtable[kPlayerEvadeStartActionVtableSlot];
    const std::uintptr_t expected_query =
        g_module + kPlayerEvadeStartQueryRva;
    const std::uintptr_t expected_action =
        g_module + kPlayerEvadeStartActionRva;
    if (*query_slot != expected_query || *action_slot != expected_action) {
        std::ostringstream line;
        line << "PlayerEvade relay SKIPPED: query=0x" << std::hex
             << *query_slot << "/0x" << expected_query << " action=0x"
             << *action_slot << "/0x" << expected_action << std::dec;
        boot_log_line(line.str().c_str());
        return false;
    }
    auto* const first_slot = query_slot;
    constexpr std::size_t kSlotSpan =
        (kPlayerEvadeStartActionVtableSlot -
         kPlayerEvadeStartQueryVtableSlot + 1) *
        sizeof(std::uintptr_t);
    DWORD old_protection = 0;
    if (!VirtualProtect(
            first_slot, kSlotSpan, PAGE_READWRITE, &old_protection)) {
        boot_log_line(
            "PlayerEvade relay SKIPPED: VirtualProtect failed");
        return false;
    }
    g_original_player_evade_start_query =
        reinterpret_cast<PlayerEvadeStartQueryFunction>(*query_slot);
    g_original_player_evade_start_action =
        reinterpret_cast<PlayerEvadeStartActionFunction>(*action_slot);
    *query_slot = reinterpret_cast<std::uintptr_t>(
        &hooked_player_evade_start_query);
    *action_slot = reinterpret_cast<std::uintptr_t>(
        &hooked_player_evade_start_action);
    FlushInstructionCache(GetCurrentProcess(), first_slot, kSlotSpan);
    DWORD ignored = 0;
    VirtualProtect(first_slot, kSlotSpan, old_protection, &ignored);
    boot_log_line(
        "PlayerEvade exact start relay installed "
        "(query 0x140F06408, action slot16 0x140DC67D0)");
    return true;
}

bool safe_query_local_grenade_arc(void* joypad) {
    if (joypad == nullptr || g_original_joypad_is_command_active == nullptr) {
        return false;
    }
    __try {
        return g_original_joypad_is_command_active(
                   joypad, kGrenadeArcCommandHash, 0) != 0;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

char __fastcall hooked_joypad_is_command_active(
    void* joypad, std::uint32_t hash, std::uint8_t edge) {
    if (g_state_net.enabled && joypad != nullptr && g_module != 0 &&
        g_original_joypad_is_command_active != nullptr) {
        void* const frame_state =
            *reinterpret_cast<void**>(g_module + 0x3FE1088);
        if (frame_state != nullptr) {
            void* const remote_joypad = static_cast<std::byte*>(frame_state) +
                                        0xDB0 + 0xBF0 * 3;
            if (joypad == remote_joypad) {
                // Grenade intent is deliberately NOT forced at this generic
                // Joypad boundary. FastGrenadeController +0xA0 independently
                // queries grenade-arc here and treats true as an inhibit/cancel
                // condition by setting controller+0x1A0 bit2. Build he forced
                // that path and could make its own later CanStart fail. The
                // exact scheduler/state E8 callsites are relayed separately.
                const auto string_hash = reinterpret_cast<StringHashFunction>(
                    g_module + kStringHashRva);
                static const std::uint32_t kJumpHash = string_hash("jump", 4, 0);
                static const std::uint32_t kJumpHoldHash =
                    string_hash("jump-hold", 9, 0);
                static const std::uint32_t kEdgeJumpAHash =
                    string_hash("edge-jump-a", 11, 0);
                static const std::uint32_t kEdgeDropHash =
                    string_hash("drop", 4, 0);
                static const std::uint32_t kCrouchHash =
                    string_hash("crouch", 6, 0);
                static const std::uint32_t kCoverEnterHash =
                    string_hash("cover-enter", 11, 0);
                static const std::uint32_t kCoverExitHash =
                    string_hash("cover-exit", 10, 0);
                static const std::uint32_t kTryEnterCoverHash =
                    string_hash("try-enter-cover", 15, 0);
                static const std::uint32_t kMeleeTriangleHash =
                    string_hash("melee-triangle", 14, 0);
                static const std::uint32_t kMeleeSquareHash =
                    string_hash("melee-square", 12, 0);
                const std::uint64_t force =
                    g_state_net.puppet_traversal_force.load(
                        std::memory_order_acquire);
                const std::uint8_t cover_force =
                    g_state_net.puppet_cover_force.load(
                        std::memory_order_acquire);
                // INTENT-only cues. Face A(=0x20) is BOTH jump pad AND ScaleCopy's
                // evade-bleed source — matching on face pads made jump animate as
                // roll and evade collide with crouch (2026-07-08bg user report).
                if ((hash == kJumpHash || hash == kJumpHoldHash) &&
                    (force & (kJoypadJumpPressButtonMask |
                              kJoypadJumpHoldButtonMask)) != 0) {
                    return 1;
                }
                // The ordinary ledge controller asks this exact command with
                // edge=0 after wall-hang. Do not alias generic jump or raw face
                // A here: the dedicated cue preserves authored command identity
                // without reintroducing jump->evade/roll bleed.
                if (hash == kEdgeJumpAHash && edge == 0 &&
                    (force & kJoypadEdgeJumpAIntentMask) != 0) {
                    static std::atomic<unsigned> edge_jump_a_force_logs{0};
                    const unsigned log_index = edge_jump_a_force_logs.fetch_add(
                        1, std::memory_order_relaxed);
                    if (log_index < 8) {
                        std::ostringstream line;
                        line << "TRAVERSAL-EDGE-JUMP-A-FORCE edge="
                             << static_cast<unsigned>(edge)
                             << " force=0x" << std::hex << force << std::dec;
                        boot_log_line(line.str().c_str());
                    }
                    return 1;
                }
                // Ordinary Player::Edge release is a distinct held command.
                // Force it only for the exact remote Joypad-3 query so the
                // existing crouch/drop-hold/evade mappings remain isolated.
                const bool edge_drop_packet_active =
                    (force & kJoypadEdgeDropIntentMask) != 0;
                const bool edge_drop_latched =
                    GetTickCount64() <
                    g_state_net.puppet_edge_drop_force_until_ms.load(
                        std::memory_order_acquire);
                if (hash == kEdgeDropHash && edge == 0 &&
                    (edge_drop_packet_active || edge_drop_latched)) {
                    static std::atomic<unsigned> edge_drop_force_logs{0};
                    const unsigned log_index =
                        edge_drop_force_logs.fetch_add(
                            1, std::memory_order_relaxed);
                    if (log_index < 8) {
                        std::ostringstream line;
                        line << "TRAVERSAL-EDGE-DROP-FORCE edge="
                             << static_cast<unsigned>(edge)
                             << " force=0x" << std::hex << force << std::dec
                             << " latched=" << (edge_drop_latched ? 1 : 0);
                        boot_log_line(line.str().c_str());
                    }
                    return 1;
                }
                if (hash == kCrouchHash &&
                    (force & kJoypadCrouchButtonMask) != 0) {
                    return 1;
                }
                // The stock dispatcher inserts melee-square from this Joypad
                // query, and PlayerMoveStick later consumes it through the
                // controller's +0x210 queue slot. Do not translate the peer
                // press to melee-r1: that path requires a locally rated target.
                if (g_enable_puppet_melee_callsite_relay &&
                    hash == kMeleeSquareHash) {
                    const ULONGLONG received =
                        g_state_net.peer_state_received_ms.load(
                            std::memory_order_acquire);
                    if (received != 0 && GetTickCount64() - received <= 500) {
                        std::uint32_t pending =
                            g_state_net.pending_puppet_melee_presses.load(
                                std::memory_order_acquire);
                        while (pending != 0) {
                            if (g_state_net.pending_puppet_melee_presses
                                    .compare_exchange_weak(
                                        pending, pending - 1,
                                        std::memory_order_acq_rel,
                                        std::memory_order_acquire)) {
                                return 1;
                            }
                        }
                    }
                }
                if (g_enable_puppet_melee_button_relay &&
                    (force & kJoypadMeleeTriangleButtonMask) != 0 &&
                    (hash == kMeleeTriangleHash ||
                     melee_relay_hash_is_puppet_force_target(hash))) {
                    return 1;
                }
                if ((hash == kCoverEnterHash &&
                     ((cover_force & kPuppetCoverEnterActive) != 0 ||
                      (cover_force & kPuppetCoverEnterPulse) != 0))) {
                    return 1;
                }
                if (hash == kCoverExitHash &&
                    (cover_force & kPuppetCoverExitPulse) != 0) {
                    return 1;
                }
            }
        }
    }
    const char original =
        g_original_joypad_is_command_active(joypad, hash, edge);
    if (original && joypad != nullptr && g_module != 0 &&
        hash == kEdgeDropCommandHash && edge == 0 &&
        joypad == player_joypad_object(retained_player_object(0))) {
        const std::uintptr_t return_address =
            reinterpret_cast<std::uintptr_t>(_ReturnAddress());
        const std::uintptr_t return_rva =
            return_address >= g_module ? return_address - g_module : 0;
        if (return_rva ==
                kPlayerEdgeDropJoypadIsCommandActiveCallsiteARva + 5 ||
            return_rva ==
                kPlayerEdgeDropJoypadIsCommandActiveCallsiteBRva + 5) {
            latch_local_player_edge_drop("joypad");
        }
    }
    if (original && g_enable_puppet_melee_callsite_relay && joypad != nullptr &&
        g_module != 0 && hash == melee_relay_hashes().square) {
        void* const local_player = retained_player_object(0);
        void* const frame_state =
            *reinterpret_cast<void**>(g_module + kFrameStateGlobalRva);
        if (local_player != nullptr && frame_state != nullptr &&
            readable_bytes(static_cast<std::byte*>(local_player) +
                           kPlayerJoypadIndexOffset) >= sizeof(std::int32_t)) {
            const auto joypad_index = *reinterpret_cast<const std::int32_t*>(
                static_cast<const std::byte*>(local_player) +
                kPlayerJoypadIndexOffset);
            if (joypad_index >= 0 && joypad_index < 6) {
                void* const local_joypad =
                    static_cast<std::byte*>(frame_state) +
                    kFrameStateScreenBlockBaseOffset +
                    kFrameStateScreenBlockStride *
                        static_cast<std::uintptr_t>(joypad_index);
                if (joypad == local_joypad) {
                    g_local_melee_press_until_ms.store(
                        GetTickCount64() + 150, std::memory_order_release);
                }
            }
        }
    }
    return original;
}

bool install_joypad3_is_command_active_force() {
    auto* const target = reinterpret_cast<std::uint8_t*>(
        g_module + kJoypadIsCommandActiveRva);
    // First 14 bytes: mov [rsp+10],rbx; mov [rsp+18],rbp; push rsi; push rdi; push r14
    constexpr std::array<std::uint8_t, 14> expected14{
        0x48, 0x89, 0x5C, 0x24, 0x10, 0x48, 0x89, 0x6C, 0x24, 0x18,
        0x56, 0x57, 0x41, 0x56,
    };
    if (std::memcmp(target, expected14.data(), expected14.size()) != 0) {
        std::ostringstream line;
        line << "Joypad3 IsCommandActive force skipped: prologue bytes";
        for (int i = 0; i < 16; ++i) {
            line << ' ' << std::hex << static_cast<unsigned>(target[i]);
        }
        force_log_line(line.str().c_str());
        return false;
    }
    constexpr std::size_t kStolen = 14;
    constexpr std::size_t kReturnJumpSize = 14;
    auto* const trampoline = static_cast<std::uint8_t*>(VirtualAlloc(
        nullptr, kStolen + kReturnJumpSize, MEM_COMMIT | MEM_RESERVE,
        PAGE_EXECUTE_READWRITE));
    if (trampoline == nullptr) {
        force_log_line("Joypad3 IsCommandActive force skipped: trampoline alloc failed");
        return false;
    }
    std::memcpy(trampoline, target, kStolen);
    auto* const jump_back = trampoline + kStolen;
    jump_back[0] = 0xFF;
    jump_back[1] = 0x25;
    *reinterpret_cast<std::uint32_t*>(jump_back + 2) = 0;
    *reinterpret_cast<std::uintptr_t*>(jump_back + 6) =
        reinterpret_cast<std::uintptr_t>(target + kStolen);
    FlushInstructionCache(
        GetCurrentProcess(), trampoline, kStolen + kReturnJumpSize);
    g_original_joypad_is_command_active =
        reinterpret_cast<JoypadIsCommandActiveFunction>(trampoline);

    DWORD old_protection = 0;
    if (!VirtualProtect(target, kStolen, PAGE_EXECUTE_READWRITE,
                        &old_protection)) {
        VirtualFree(trampoline, 0, MEM_RELEASE);
        g_original_joypad_is_command_active = nullptr;
        force_log_line("Joypad3 IsCommandActive force skipped: VirtualProtect failed");
        return false;
    }
    // 12-byte absolute jmp via rax (same pattern as keyboard isolation).
    target[0] = 0x48;
    target[1] = 0xB8;
    *reinterpret_cast<std::uintptr_t*>(target + 2) =
        reinterpret_cast<std::uintptr_t>(&hooked_joypad_is_command_active);
    target[10] = 0xFF;
    target[11] = 0xE0;
    std::memset(target + 12, 0x90, 2);  // pad stolen=14
    FlushInstructionCache(GetCurrentProcess(), target, kStolen);
    DWORD ignored = 0;
    VirtualProtect(target, kStolen, old_protection, &ignored);
    force_log_line(
        "Joypad3 IsCommandActive force-hook installed (jump/crouch/melee/cover)");
    return true;
}

char __fastcall hooked_player_input_is_command_active(
    void* state, std::uint32_t hash, std::uint8_t edge) {
    if (g_state_net.enabled && state != nullptr &&
        g_original_player_input_is_command_active != nullptr) {
        auto* const player =
            static_cast<std::byte*>(state) - kPlayerInputCommandStateOffset;
        if (player == static_cast<std::byte*>(retained_player_object(1))) {
            const std::uint64_t force =
                g_state_net.puppet_traversal_force.load(
                    std::memory_order_acquire);
            if ((force & kJoypadMeleeTriangleButtonMask) != 0 &&
                melee_relay_hash_is_puppet_force_target(hash)) {
                (void)edge;
                return 1;
            }
        }
    }
    return g_original_player_input_is_command_active(state, hash, edge);
}

bool install_player_input_is_command_active_force() {
    auto* const target = reinterpret_cast<std::uint8_t*>(
        g_module + kPlayerInputCommandStateIsCommandActiveRva);
    constexpr std::array<std::uint8_t, 16> expected16{
        0xC5, 0xFA, 0x10, 0x05, 0x40, 0x1B, 0xD0, 0x04,
        0xC5, 0xF8, 0x2E, 0x05, 0x94, 0xF4, 0xDA, 0x00,
    };
    if (std::memcmp(target, expected16.data(), expected16.size()) != 0) {
        force_log_line(
            "PlayerInputCommandState IsCommandActive force skipped: prologue");
        return false;
    }
    constexpr std::size_t kStolen = 16;
    constexpr std::size_t kReturnJumpSize = 14;
    auto* const trampoline = static_cast<std::uint8_t*>(VirtualAlloc(
        nullptr, kStolen + kReturnJumpSize, MEM_COMMIT | MEM_RESERVE,
        PAGE_EXECUTE_READWRITE));
    if (trampoline == nullptr) {
        force_log_line(
            "PlayerInputCommandState IsCommandActive force skipped: alloc failed");
        return false;
    }
    std::memcpy(trampoline, target, kStolen);
    auto* const jump_back = trampoline + kStolen;
    jump_back[0] = 0xFF;
    jump_back[1] = 0x25;
    *reinterpret_cast<std::uint32_t*>(jump_back + 2) = 0;
    *reinterpret_cast<std::uintptr_t*>(jump_back + 6) =
        reinterpret_cast<std::uintptr_t>(target + kStolen);
    FlushInstructionCache(
        GetCurrentProcess(), trampoline, kStolen + kReturnJumpSize);
    g_original_player_input_is_command_active =
        reinterpret_cast<PlayerInputIsCommandActiveFunction>(trampoline);

    DWORD old_protection = 0;
    if (!VirtualProtect(target, kStolen, PAGE_EXECUTE_READWRITE,
                        &old_protection)) {
        VirtualFree(trampoline, 0, MEM_RELEASE);
        g_original_player_input_is_command_active = nullptr;
        force_log_line(
            "PlayerInputCommandState IsCommandActive force skipped: protect");
        return false;
    }
    target[0] = 0x48;
    target[1] = 0xB8;
    *reinterpret_cast<std::uintptr_t*>(target + 2) =
        reinterpret_cast<std::uintptr_t>(&hooked_player_input_is_command_active);
    target[10] = 0xFF;
    target[11] = 0xE0;
    std::memset(target + 12, 0x90, 4);
    FlushInstructionCache(GetCurrentProcess(), target, kStolen);
    DWORD ignored = 0;
    VirtualProtect(target, kStolen, old_protection, &ignored);
    force_log_line(
        "PlayerInputCommandState IsCommandActive force-hook installed (melee)");
    return true;
}

char __fastcall hooked_player_edge_drop_command_callsite(
    void* state, std::uint32_t hash, std::uint8_t edge) {
    auto call_original = [&]() -> char {
        return g_original_player_edge_drop_callsite_is_command_active != nullptr
            ? g_original_player_edge_drop_callsite_is_command_active(
                  state, hash, edge)
            : 0;
    };
    if (state == nullptr || hash != kEdgeDropCommandHash || edge != 0 ||
        !g_state_net.enabled) {
        return call_original();
    }
    auto* const player =
        static_cast<std::byte*>(state) - kPlayerInputCommandStateOffset;
    if (player == static_cast<std::byte*>(retained_player_object(0))) {
        const char original = call_original();
        if (original) {
            latch_local_player_edge_drop("state");
        }
        return original;
    }
    if (player != static_cast<std::byte*>(retained_player_object(1))) {
        return call_original();
    }
    const ULONGLONG now = GetTickCount64();
    const ULONGLONG force_until =
        g_state_net.puppet_edge_drop_force_until_ms.load(
            std::memory_order_acquire);
    if (now >= force_until) {
        return call_original();
    }
    const std::uint32_t sequence =
        g_state_net.puppet_edge_drop_event_sequence.load(
            std::memory_order_acquire);
    const std::uint32_t logged_sequence =
        g_state_net.puppet_edge_drop_state_force_logged_sequence.exchange(
            sequence, std::memory_order_acq_rel);
    if (sequence != 0 && logged_sequence != sequence) {
        std::ostringstream line;
        line << "TRAVERSAL-EDGE-DROP-STATE-FORCE seq=" << sequence
             << " edge=" << static_cast<unsigned>(edge)
             << " remainingMs=" << (force_until - now);
        boot_log_line(line.str().c_str());
    }
    return 1;
}

struct FastGrenadeWeaponSlotSnapshot {
    void* handle_node = nullptr;
    std::uint32_t handle = 0;
    void* weapon = nullptr;
    void* weapon_vtable = nullptr;
    std::uint32_t art_id = 0;
    std::int16_t magazine = 0;
    std::int16_t reserve = 0;
    bool valid = false;
};

struct FastGrenadeControllerSnapshot {
    void* controller = nullptr;
    void* owner = nullptr;
    std::uint32_t state = 0;
    std::uint32_t slot = 0;
    std::uint32_t action_mode = 0;
    std::uint64_t release_deadline = 0;
    std::uint8_t flags = 0;
    std::array<FastGrenadeWeaponSlotSnapshot, 6> weapons{};
};

bool seh_read_fast_grenade_controller_raw(
    void* controller, FastGrenadeControllerSnapshot* out) {
    if (controller == nullptr || out == nullptr) {
        return false;
    }
    __try {
        out->controller = controller;
        out->owner = *reinterpret_cast<void**>(
            static_cast<std::byte*>(controller) + 0x108);
        out->state = *reinterpret_cast<std::uint32_t*>(
            static_cast<std::byte*>(controller) + 0x120);
        out->flags = *reinterpret_cast<std::uint8_t*>(
            static_cast<std::byte*>(controller) + 0x1A0);
        out->slot = *reinterpret_cast<std::uint32_t*>(
            static_cast<std::byte*>(controller) + 0x18C);
        out->action_mode = *reinterpret_cast<std::uint32_t*>(
            static_cast<std::byte*>(controller) + 0x540);
        out->release_deadline = *reinterpret_cast<std::uint64_t*>(
            static_cast<std::byte*>(controller) + 0x530);
        for (std::size_t slot = 0; slot < out->weapons.size(); ++slot) {
            auto& weapon = out->weapons[slot];
            auto* const pair = static_cast<std::byte*>(controller) +
                               0x128 + slot * 0x10;
            weapon.handle_node = *reinterpret_cast<void**>(pair);
            weapon.handle = *reinterpret_cast<std::uint32_t*>(pair + 0x8);
            if (weapon.handle_node == nullptr || weapon.handle == 0) {
                continue;
            }
            weapon.weapon = *reinterpret_cast<void**>(
                static_cast<std::byte*>(weapon.handle_node) + 0x8);
            if (weapon.weapon == nullptr ||
                *reinterpret_cast<std::uint32_t*>(
                    static_cast<std::byte*>(weapon.weapon) + 0xBC) !=
                    weapon.handle) {
                continue;
            }
            weapon.valid = true;
            weapon.weapon_vtable =
                *reinterpret_cast<void**>(weapon.weapon);
            if (reinterpret_cast<std::uintptr_t>(weapon.weapon_vtable) ==
                g_module + kProcessWeaponVtableRva) {
                weapon.art_id = *reinterpret_cast<std::uint32_t*>(
                    static_cast<std::byte*>(weapon.weapon) + 0x860);
                weapon.magazine = *reinterpret_cast<std::int16_t*>(
                    static_cast<std::byte*>(weapon.weapon) + 0x900);
                weapon.reserve = *reinterpret_cast<std::int16_t*>(
                    static_cast<std::byte*>(weapon.weapon) + 0x902);
            }
        }
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

bool seh_read_fast_grenade_controller(
    void* puppet, FastGrenadeControllerSnapshot* out) {
    if (puppet == nullptr || out == nullptr) {
        return false;
    }
    void* controller = nullptr;
    __try {
        controller = *reinterpret_cast<void**>(
            static_cast<std::byte*>(puppet) +
            kPlayerFastGrenadeControllerOffset);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
    return seh_read_fast_grenade_controller_raw(controller, out);
}

void log_grenade_controller_state(
    void* player, const char* scope, const char* stage, bool value,
    std::uint32_t sequence) {
    FastGrenadeControllerSnapshot snapshot{};
    if (!seh_read_fast_grenade_controller(player, &snapshot)) {
        boot_log_line("GRENADE-CONTROLLER state read fault");
        return;
    }
    std::ostringstream line;
    line << "GRENADE-CONTROLLER scope=" << scope
         << " stage=" << stage
         << " value=" << (value ? 1 : 0)
         << " seq=" << sequence
         << " controller=0x" << std::hex
         << reinterpret_cast<std::uintptr_t>(snapshot.controller)
         << " ownerMatch=" << (snapshot.owner == player ? 1 : 0)
         << " state=0x" << snapshot.state
         << " flags=0x" << static_cast<unsigned>(snapshot.flags)
         << " slot=0x" << snapshot.slot
         << " mode540=0x" << snapshot.action_mode
         << " deadline530=0x" << snapshot.release_deadline;
    for (std::size_t slot = 0; slot < snapshot.weapons.size(); ++slot) {
        const auto& weapon = snapshot.weapons[slot];
        line << " s" << slot
             << "Node=0x"
             << reinterpret_cast<std::uintptr_t>(weapon.handle_node)
             << " s" << slot << "Handle=0x" << weapon.handle
             << " s" << slot << "Weapon=0x"
             << reinterpret_cast<std::uintptr_t>(weapon.weapon)
             << " s" << slot << "Vtable=0x"
             << reinterpret_cast<std::uintptr_t>(weapon.weapon_vtable)
             << std::dec
             << " s" << slot << "Valid=" << (weapon.valid ? 1 : 0)
             << " s" << slot << "Art=0x" << std::hex << weapon.art_id
             << std::dec
             << " s" << slot << "Magazine=" << weapon.magazine
             << " s" << slot << "Reserve=" << weapon.reserve
             << " s" << slot << "Total="
             << static_cast<int>(weapon.magazine) +
                    static_cast<int>(weapon.reserve)
             << std::hex;
    }
    line << std::dec;
    boot_log_line(line.str().c_str());
}

void log_peer_grenade_controller_state(
    const char* stage, bool value, std::uint32_t sequence) {
    log_grenade_controller_state(
        retained_player_object(1), "peer", stage, value, sequence);
}

void log_peer_grenade_reset(
    const char* stage, void* controller, std::uintptr_t return_rva) {
    const unsigned row = g_peer_grenade_reset_log_rows.fetch_add(
        1, std::memory_order_relaxed);
    if (row >= 12) {
        return;
    }
    FastGrenadeControllerSnapshot snapshot{};
    const bool readable =
        seh_read_fast_grenade_controller_raw(controller, &snapshot);
    void* const peer_player = retained_player_object(1);
    coop::StatePacket peer{};
    const bool have_peer = copy_peer_state_snapshot(peer);
    const char* cause = "other";
    if (return_rva == kGrenadeResetReturnCoverAbortRva) {
        cause = "cover-abort";
    } else if (return_rva == kGrenadeResetReturnNetGateAbortRva) {
        cause = "net-gate-abort";
    } else if (return_rva == kGrenadeResetReturnState7Or8AbortRva) {
        cause = "state7-or-state8-abort";
    }
    std::ostringstream line;
    line << "GRENADE-RESET stage=" << stage
         << " row=" << row
         << " seq=" << (have_peer ? peer.sequence : 0)
         << " ret=0x" << std::hex << return_rva
         << " cause=" << cause
         << " controller=0x"
         << reinterpret_cast<std::uintptr_t>(controller)
         << " readable=" << std::dec << (readable ? 1 : 0)
         << " ownerMatch="
         << (readable && snapshot.owner == peer_player ? 1 : 0)
         << " state=0x" << std::hex << snapshot.state
         << " mode540=0x" << snapshot.action_mode
         << " deadline530=0x" << snapshot.release_deadline;
    boot_log_line(line.str().c_str());
}

std::int64_t __fastcall hooked_fast_grenade_reset(void* controller) {
    const std::uintptr_t return_address =
        reinterpret_cast<std::uintptr_t>(_ReturnAddress());
    const std::uintptr_t return_rva =
        return_address >= g_module ? return_address - g_module : 0;
    const bool classified_return =
        return_rva == kGrenadeResetReturnCoverAbortRva ||
        return_rva == kGrenadeResetReturnNetGateAbortRva ||
        return_rva == kGrenadeResetReturnState7Or8AbortRva;
    const ULONGLONG now = GetTickCount64();
    const bool peer_release_window =
        classified_return && controller != nullptr &&
        now <= g_peer_grenade_release_probe_until_ms.load(
                   std::memory_order_acquire);
    if (peer_release_window) {
        log_peer_grenade_reset("entry", controller, return_rva);
    }
    const std::int64_t result =
        g_original_fast_grenade_reset != nullptr
            ? g_original_fast_grenade_reset(controller)
            : 0;
    if (peer_release_window) {
        log_peer_grenade_reset("exit", controller, return_rva);
    }
    return result;
}

std::int64_t __fastcall hooked_fast_grenade_release(void* controller) {
    FastGrenadeControllerSnapshot snapshot{};
    void* const peer_player = retained_player_object(1);
    const bool peer_release = peer_player != nullptr &&
        seh_read_fast_grenade_controller_raw(controller, &snapshot) &&
        snapshot.owner == peer_player;
    if (peer_release) {
        ++g_peer_fast_grenade_release_scope_depth;
        boot_log_line("GRENADE-PLAYER-RELEASE-SCOPE enter");
    }
    const std::int64_t result =
        g_original_fast_grenade_release != nullptr
            ? g_original_fast_grenade_release(controller)
            : 0;
    if (peer_release) {
        if (g_peer_fast_grenade_release_scope_depth != 0) {
            --g_peer_fast_grenade_release_scope_depth;
        }
        boot_log_line("GRENADE-PLAYER-RELEASE-SCOPE exit");
    }
    return result;
}

void log_peer_grenade_release(
    const char* stage, void* controller, std::int64_t result) {
    const unsigned row = g_peer_grenade_release_log_rows.fetch_add(
        1, std::memory_order_relaxed);
    if (row >= 8) {
        return;
    }
    FastGrenadeControllerSnapshot snapshot{};
    const bool readable =
        seh_read_fast_grenade_controller_raw(controller, &snapshot);
    void* const peer_player = retained_player_object(1);
    coop::StatePacket peer{};
    const bool have_peer = copy_peer_state_snapshot(peer);
    const std::uint32_t net_mode_flags =
        *reinterpret_cast<const std::uint32_t*>(
            g_module + kNetModeFlagsGlobalRva);
    std::ostringstream line;
    line << "GRENADE-RELEASE stage=" << stage
         << " row=" << row
         << " seq=" << (have_peer ? peer.sequence : 0)
         << " controller=0x" << std::hex
         << reinterpret_cast<std::uintptr_t>(controller)
         << " readable=" << std::dec << (readable ? 1 : 0)
         << " ownerMatch="
         << (readable && snapshot.owner == peer_player ? 1 : 0)
         << " netModeHigh=0x" << std::hex
         << ((net_mode_flags >> 24) & 0xFFu)
         << " state=0x" << std::hex << snapshot.state
         << " mode540=0x" << snapshot.action_mode
         << " deadline530=0x" << snapshot.release_deadline
         << " result=0x" << static_cast<std::uint64_t>(result);
    boot_log_line(line.str().c_str());
}

std::int64_t __fastcall hooked_grenade_release_post_arc_hold(
    void* controller) {
    const ULONGLONG now = GetTickCount64();
    const bool peer_release_window =
        controller != nullptr &&
        now <= g_peer_grenade_release_probe_until_ms.load(
                   std::memory_order_acquire);
    if (peer_release_window) {
        log_peer_grenade_release("entry", controller, 0);
    }
    const std::int64_t result =
        g_original_grenade_release_post_arc_hold != nullptr
            ? g_original_grenade_release_post_arc_hold(controller)
            : 0;
    if (peer_release_window) {
        log_peer_grenade_release("exit", controller, result);
    }
    return result;
}

bool ensure_puppet_grenade_weapon_binding(
    void* puppet, void* grenade_controller, const coop::StatePacket& peer) {
    if (puppet == nullptr || grenade_controller == nullptr ||
        peer.grenade_art_id == 0 || peer.grenade_total_ammo <= 0 ||
        g_module == 0) {
        return false;
    }

    FastGrenadeControllerSnapshot before{};
    if (seh_read_fast_grenade_controller(puppet, &before) &&
        before.slot < before.weapons.size()) {
        const auto& selected = before.weapons[before.slot];
        if (selected.valid &&
            reinterpret_cast<std::uintptr_t>(selected.weapon_vtable) ==
                g_module + kProcessWeaponVtableRva &&
            selected.art_id == peer.grenade_art_id &&
            static_cast<int>(selected.magazine) +
                    static_cast<int>(selected.reserve) >
                0) {
            return true;
        }
    }

    int existing_slot =
        find_weapon_slot_by_art_id(puppet, peer.grenade_art_id);
    void* weapon =
        existing_slot >= 0 ? get_weapon_from_slot(puppet, existing_slot)
                           : nullptr;
    bool created = false;
    bool bound = false;
    bool faulted = false;
    bool slot_two_occupied = false;
    bool art_definition_valid = false;
    bool weapon_type_valid = false;
    int art_grenade_slot = -1;
    int total_before_bind = -1;

    __try {
        using GetRegistryFunction = void*(__fastcall*)();
        using LookupRecordFunction =
            void*(__fastcall*)(void*, std::uint32_t);
        void* const registry = reinterpret_cast<GetRegistryFunction>(
            g_module + kGetCachedWeaponArtDefsHashRegistryRva)();
        void* const art_definition =
            registry != nullptr
                ? reinterpret_cast<LookupRecordFunction>(
                      g_module + kLookupRegistryRecordPointerByIdRva)(
                      registry, peer.grenade_art_id)
                : nullptr;
        if (art_definition != nullptr &&
            readable_bytes(
                static_cast<std::byte*>(art_definition) + 0xC) >=
                sizeof(std::int8_t)) {
            art_grenade_slot =
                *reinterpret_cast<const std::int8_t*>(
                    static_cast<const std::byte*>(art_definition) + 0xC);
            art_definition_valid =
                art_grenade_slot >= 0 && art_grenade_slot < 6;
        }

        auto* const player_bytes = static_cast<std::byte*>(puppet);
        void* const weapon_controller =
            *reinterpret_cast<void**>(player_bytes + 0x1D88);
        const bool weapon_controller_valid =
            weapon_controller != nullptr &&
            *reinterpret_cast<void**>(weapon_controller) ==
                reinterpret_cast<void*>(
                    g_module + kPlayerWeaponControllerVtableRva);

        if (art_definition_valid && weapon_controller_valid &&
            weapon == nullptr) {
            slot_two_occupied =
                get_weapon_from_slot(puppet, 2) != nullptr;
            if (!slot_two_occupied) {
                auto** const weapon_vtable =
                    *reinterpret_cast<void***>(weapon_controller);
                using CreateWeaponFunction = void*(__fastcall*)(
                    void*, std::uint32_t, std::int32_t, int, char,
                    std::uint8_t, std::int16_t, std::int16_t, void*, char);
                const auto create_weapon =
                    reinterpret_cast<CreateWeaponFunction>(
                        weapon_vtable[0x130 / sizeof(void*)]);
                if (reinterpret_cast<std::uintptr_t>(create_weapon) ==
                    g_module +
                        kPlayerWeaponControllerCreateAndAddWeaponRva) {
                    weapon = create_weapon(
                        weapon_controller, peer.grenade_art_id,
                        peer.grenade_total_ammo, 2, 0, 0, -1, -1, nullptr,
                        0);
                    created = weapon != nullptr;
                }
            }
        }

        if (weapon != nullptr) {
            weapon_type_valid =
                *reinterpret_cast<void**>(weapon) ==
                    reinterpret_cast<void*>(
                        g_module + kProcessWeaponVtableRva) &&
                *reinterpret_cast<std::uint32_t*>(
                    static_cast<std::byte*>(weapon) + 0x860) ==
                    peer.grenade_art_id;
        }

        if (art_definition_valid && weapon_type_valid) {
            using GetTotalAmmoFunction = int(__fastcall*)(void*);
            using InitializeAmmoFunction =
                void(__fastcall*)(void*, std::int32_t);
            const auto get_total_ammo =
                reinterpret_cast<GetTotalAmmoFunction>(
                    g_module + kProcessWeaponGetTotalAmmoRva);
            total_before_bind = get_total_ammo(weapon);
            if (total_before_bind <= 0) {
                reinterpret_cast<InitializeAmmoFunction>(
                    g_module +
                    kProcessWeaponInitializeAmmoFromTotalRva)(
                    weapon, peer.grenade_total_ammo);
                total_before_bind = get_total_ammo(weapon);
            }

            auto** const grenade_vtable =
                *reinterpret_cast<void***>(grenade_controller);
            using BindGrenadeWeaponFunction =
                std::int64_t(__fastcall*)(void*, void*);
            const auto bind_weapon =
                reinterpret_cast<BindGrenadeWeaponFunction>(
                    grenade_vtable[0xF0 / sizeof(void*)]);
            if (total_before_bind > 0 &&
                reinterpret_cast<std::uintptr_t>(bind_weapon) ==
                    g_module +
                        kPlayerGrenadeControllerBindWeaponSlotRva) {
                bind_weapon(grenade_controller, weapon);
                bound = true;
            }
        }
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        faulted = true;
    }

    FastGrenadeControllerSnapshot after{};
    const bool read_after =
        seh_read_fast_grenade_controller(puppet, &after);
    bool selected_valid = false;
    int selected_total = 0;
    std::uint32_t selected_art = 0;
    if (read_after && after.slot < after.weapons.size()) {
        const auto& selected = after.weapons[after.slot];
        selected_valid =
            selected.valid &&
            reinterpret_cast<std::uintptr_t>(selected.weapon_vtable) ==
                g_module + kProcessWeaponVtableRva;
        selected_total =
            static_cast<int>(selected.magazine) +
            static_cast<int>(selected.reserve);
        selected_art = selected.art_id;
    }

    char line[320]{};
    sprintf_s(
        line,
        "GRENADE-BIND art=0x%08x ammo=%d peerSlot=%u existingSlot=%d "
        "artSlot=%d artValid=%d slot2Occupied=%d created=%d typeValid=%d "
        "preBindTotal=%d bound=%d fault=%d activeSlot=%u "
        "selectedValid=%d selectedArt=0x%08x selectedTotal=%d",
        peer.grenade_art_id, static_cast<int>(peer.grenade_total_ammo),
        static_cast<unsigned>(peer.grenade_selected_slot), existing_slot,
        art_grenade_slot, art_definition_valid ? 1 : 0,
        slot_two_occupied ? 1 : 0, created ? 1 : 0,
        weapon_type_valid ? 1 : 0, total_before_bind,
        bound ? 1 : 0, faulted ? 1 : 0,
        read_after ? after.slot : 0xFFFFFFFFu, selected_valid ? 1 : 0,
        selected_art, selected_total);
    boot_log_line(line);

    return !faulted && bound && selected_valid &&
           selected_art == peer.grenade_art_id && selected_total > 0;
}

char __fastcall hooked_player_grenade_command_callsite(
    void* state, std::uint32_t hash, std::uint8_t edge) {
    const std::uintptr_t return_address =
        reinterpret_cast<std::uintptr_t>(_ReturnAddress());
    const std::uintptr_t return_rva =
        return_address >= g_module ? return_address - g_module : 0;
    if (g_grenade_relay_wrapper_entries.fetch_add(
            1, std::memory_order_relaxed) == 0) {
        g_grenade_relay_first_return_rva.store(
            return_rva, std::memory_order_relaxed);
        unsigned stage =
            g_grenade_relay_install_stage.load(std::memory_order_relaxed);
        while (stage < 10 &&
               !g_grenade_relay_install_stage.compare_exchange_weak(
                   stage, 10, std::memory_order_relaxed,
                   std::memory_order_relaxed)) {
        }
    }
    const char* phase = nullptr;
    std::atomic<int>* last = nullptr;
    if (return_rva ==
        kGrenadeSchedulerIsCommandActiveCallsiteRva + 5) {
        phase = "scheduler";
        last = &g_grenade_scheduler_command_last;
    } else if (
        return_rva == kGrenadeState1IsCommandActiveCallsiteRva + 5) {
        phase = "state1";
        last = &g_grenade_state1_command_last;
    } else if (
        return_rva == kGrenadeState2IsCommandActiveCallsiteRva + 5) {
        phase = "state2";
        last = &g_grenade_state2_command_last;
    } else if (
        return_rva == kGrenadeState4IsCommandActiveCallsiteRva + 5) {
        phase = "state4";
        last = &g_grenade_state4_command_last;
    }

    auto call_original = [&]() -> char {
        return g_original_player_grenade_callsite_is_command_active != nullptr
            ? g_original_player_grenade_callsite_is_command_active(
                  state, hash, edge)
            : 0;
    };
    if (phase == nullptr || state == nullptr ||
        hash != kGrenadeArcCommandHash || edge != 0 ||
        !g_state_net.enabled) {
        return call_original();
    }

    auto* const player =
        static_cast<std::byte*>(state) - kPlayerInputCommandStateOffset;
    if (player != static_cast<std::byte*>(retained_player_object(1))) {
        return call_original();
    }

    coop::StatePacket peer{};
    const ULONGLONG now = GetTickCount64();
    const ULONGLONG received =
        g_state_net.peer_state_received_ms.load(std::memory_order_acquire);
    if (received == 0 || now - received > 250 ||
        !copy_peer_state_snapshot(peer)) {
        // Never manufacture a release edge from a stale network packet.
        return call_original();
    }

    const bool active = peer.grenade_arc_active != 0;
    const int previous = last->exchange(
        active ? 1 : 0, std::memory_order_acq_rel);
    if (previous != (active ? 1 : 0)) {
        log_peer_grenade_controller_state(phase, active, peer.sequence);
    }

    const bool was_active = g_peer_grenade_command_was_active.exchange(
        active, std::memory_order_acq_rel);
    if (!was_active && active) {
        g_peer_grenade_scheduler_consumed.store(
            false, std::memory_order_release);
        g_grenade_can_start_last.store(-1, std::memory_order_release);
        g_peer_grenade_bind_attempted.store(
            false, std::memory_order_release);
        g_peer_grenade_pose_seed_logged.store(
            false, std::memory_order_release);
        g_peer_grenade_release_pose_seed_logged.store(
            false, std::memory_order_release);
        g_peer_grenade_reset_log_rows.store(
            0, std::memory_order_release);
        g_peer_grenade_release_log_rows.store(
            0, std::memory_order_release);
        g_peer_grenade_release_probe_until_ms.store(
            0, std::memory_order_release);
        g_peer_release_probe_grenade.store(
            nullptr, std::memory_order_release);
        g_peer_release_probe_grenade_ms.store(
            0, std::memory_order_release);
        g_peer_release_probe_track_last_ms.store(
            0, std::memory_order_release);
        g_peer_release_probe_init_rows.store(
            0, std::memory_order_release);
        g_peer_release_probe_track_rows.store(
            0, std::memory_order_release);
    }
    if (was_active && !active) {
        g_peer_grenade_release_until_ms.store(
            now + 2500, std::memory_order_release);
        // Read-only discriminator window: ReleasePostArcHold executes
        // immediately after this exact state-4 false result. Its successful
        // state-8 path or one of the three classified reset returns completes
        // well inside the observed ~400 ms state-4 -> state-0 interval.
        g_peer_grenade_release_probe_until_ms.store(
            now + 1500, std::memory_order_release);
        g_peer_native_grenade_spawn_ms.store(0, std::memory_order_release);
        g_peer_animated_grenade_init_seen.store(
            false, std::memory_order_release);
        g_peer_release_probe_grenade.store(
            nullptr, std::memory_order_release);
        g_peer_release_probe_grenade_ms.store(
            0, std::memory_order_release);
        g_peer_release_probe_track_last_ms.store(
            0, std::memory_order_release);
        g_peer_release_probe_init_rows.store(
            0, std::memory_order_release);
        g_peer_release_probe_track_rows.store(
            0, std::memory_order_release);
    }
    if (return_rva ==
            kGrenadeSchedulerIsCommandActiveCallsiteRva + 5 &&
        active &&
        g_peer_grenade_scheduler_consumed.load(
            std::memory_order_acquire)) {
        return 0;
    }
    return active ? 1 : 0;
}

bool __fastcall hooked_fast_grenade_can_start(void* controller) {
    const std::uintptr_t return_address =
        reinterpret_cast<std::uintptr_t>(_ReturnAddress());
    const std::uintptr_t return_rva =
        return_address >= g_module ? return_address - g_module : 0;
    const bool result = g_original_fast_grenade_can_start != nullptr &&
                        g_original_fast_grenade_can_start(controller);
    void* const puppet = retained_player_object(1);
    void* expected = nullptr;
    if (puppet != nullptr) {
        __try {
            expected = *reinterpret_cast<void**>(
                static_cast<std::byte*>(puppet) +
                kPlayerFastGrenadeControllerOffset);
        } __except (EXCEPTION_EXECUTE_HANDLER) {
            expected = nullptr;
        }
    }
    if (controller != nullptr && controller == expected) {
        coop::StatePacket peer{};
        if (copy_peer_state_snapshot(peer)) {
            const int previous = g_grenade_can_start_last.exchange(
                result ? 1 : 0, std::memory_order_acq_rel);
            if (previous != (result ? 1 : 0)) {
                log_peer_grenade_controller_state(
                    "can-start", result, peer.sequence);
            }
            // Stock loadout order is factory/bind -> StartArc. Provision only
            // after the scheduler eligibility check succeeds. StartArc's own
            // CanStart recheck (return RVA 0xE19612) sees the ready record but
            // must never create/bind another ProcessWeapon.
            const ULONGLONG now = GetTickCount64();
            const ULONGLONG received =
                g_state_net.peer_state_received_ms.load(
                    std::memory_order_acquire);
            if (result && return_rva == kGrenadeSchedulerCanStartReturnRva &&
                peer.grenade_arc_active != 0 && received != 0 &&
                now - received <= 250 &&
                !g_peer_grenade_bind_attempted.exchange(
                    true, std::memory_order_acq_rel)) {
                ensure_puppet_grenade_weapon_binding(
                    puppet, controller, peer);
            }
        }
    }
    return result;
}

std::int64_t __fastcall hooked_fast_grenade_start(void* controller) {
    void* const puppet = retained_player_object(1);
    void* expected = nullptr;
    if (puppet != nullptr) {
        __try {
            expected = *reinterpret_cast<void**>(
                static_cast<std::byte*>(puppet) +
                kPlayerFastGrenadeControllerOffset);
        } __except (EXCEPTION_EXECUTE_HANDLER) {
            expected = nullptr;
        }
    }
    coop::StatePacket peer{};
    const bool is_peer =
        controller != nullptr && controller == expected &&
        copy_peer_state_snapshot(peer);
    if (is_peer) {
        log_peer_grenade_controller_state(
            "start-entry", true, peer.sequence);
    }
    const std::int64_t result =
        g_original_fast_grenade_start != nullptr
            ? g_original_fast_grenade_start(controller)
            : 0;
    if (is_peer) {
        FastGrenadeControllerSnapshot after_start{};
        if (seh_read_fast_grenade_controller(
                puppet, &after_start) &&
            after_start.state == 1) {
            if (!g_peer_grenade_scheduler_consumed.exchange(
                    true, std::memory_order_acq_rel)) {
                char line[160]{};
                sprintf_s(
                    line, sizeof(line),
                    "GRENADE-SCHEDULER-CONSUME seq=%u state=%u consumed=1",
                    peer.sequence, after_start.state);
                boot_log_line(line);
            }
        }
        log_peer_grenade_controller_state(
            "start-exit", true, peer.sequence);
    }
    return result;
}

struct SuspendedProcessThreads {
    std::array<HANDLE, 256> handles{};
    std::size_t count = 0;
};

void resume_suspended_process_threads(SuspendedProcessThreads& threads) {
    while (threads.count != 0) {
        HANDLE const thread = threads.handles[--threads.count];
        ResumeThread(thread);
        CloseHandle(thread);
    }
}

bool suspend_other_process_threads(SuspendedProcessThreads& out) {
    const DWORD process_id = GetCurrentProcessId();
    const DWORD current_thread_id = GetCurrentThreadId();
    HANDLE const snapshot =
        CreateToolhelp32Snapshot(TH32CS_SNAPTHREAD, 0);
    if (snapshot == INVALID_HANDLE_VALUE) {
        return false;
    }

    bool complete = true;
    THREADENTRY32 entry{};
    entry.dwSize = sizeof(entry);
    if (Thread32First(snapshot, &entry)) {
        do {
            if (entry.th32OwnerProcessID != process_id ||
                entry.th32ThreadID == current_thread_id) {
                continue;
            }
            if (out.count >= out.handles.size()) {
                complete = false;
                break;
            }
            HANDLE const thread = OpenThread(
                THREAD_SUSPEND_RESUME, FALSE, entry.th32ThreadID);
            if (thread == nullptr) {
                complete = false;
                break;
            }
            if (SuspendThread(thread) == static_cast<DWORD>(-1)) {
                CloseHandle(thread);
                complete = false;
                break;
            }
            out.handles[out.count++] = thread;
        } while (Thread32Next(snapshot, &entry));
    } else {
        complete = false;
    }
    CloseHandle(snapshot);
    if (!complete) {
        resume_suspended_process_threads(out);
    }
    return complete;
}

bool install_player_grenade_command_callsite_relay() {
    g_grenade_relay_install_stage.store(1, std::memory_order_relaxed);
    boot_log_line(
        "grenade command relay install begin (cold validate)");
    constexpr std::array<std::uintptr_t, 4> kCallsiteRvas{
        kGrenadeSchedulerIsCommandActiveCallsiteRva,
        kGrenadeState1IsCommandActiveCallsiteRva,
        kGrenadeState2IsCommandActiveCallsiteRva,
        kGrenadeState4IsCommandActiveCallsiteRva,
    };
    std::array<std::uint8_t*, kCallsiteRvas.size()> callsites{};
    const std::uintptr_t expected_target =
        g_module + kPlayerInputCommandStateIsCommandActiveRva;
    for (std::size_t i = 0; i < callsites.size(); ++i) {
        callsites[i] = reinterpret_cast<std::uint8_t*>(
            g_module + kCallsiteRvas[i]);
        if (callsites[i][0] != 0xE8) {
            boot_log_line(
                "grenade command callsite relay SKIPPED (not E8)");
            return false;
        }
        std::int32_t displacement = 0;
        std::memcpy(
            &displacement, callsites[i] + 1, sizeof(displacement));
        const std::uintptr_t target =
            reinterpret_cast<std::uintptr_t>(callsites[i] + 5) +
            static_cast<std::intptr_t>(displacement);
        if (target != expected_target) {
            boot_log_line(
                "grenade command callsite relay SKIPPED (target)");
            return false;
        }
    }
    g_grenade_relay_install_stage.store(2, std::memory_order_relaxed);
    boot_log_line(
        "grenade command relay callsites validated");

    constexpr std::size_t kRelaySize = 14;
    auto* const relay = static_cast<std::uint8_t*>(
        allocate_executable_near(callsites[0], kRelaySize));
    if (relay == nullptr) {
        boot_log_line(
            "grenade command callsite relay SKIPPED (relay)");
        return false;
    }
    relay[0] = 0xFF;
    relay[1] = 0x25;
    *reinterpret_cast<std::uint32_t*>(relay + 2) = 0;
    *reinterpret_cast<std::uintptr_t*>(relay + 6) =
        reinterpret_cast<std::uintptr_t>(
            &hooked_player_grenade_command_callsite);
    FlushInstructionCache(GetCurrentProcess(), relay, kRelaySize);
    g_grenade_relay_install_stage.store(3, std::memory_order_relaxed);
    boot_log_line(
        "grenade command relay near thunk allocated");

    std::array<std::int32_t, kCallsiteRvas.size()> displacements{};
    for (std::size_t i = 0; i < callsites.size(); ++i) {
        const std::int64_t displacement =
            reinterpret_cast<std::intptr_t>(relay) -
            reinterpret_cast<std::intptr_t>(callsites[i] + 5);
        if (displacement < INT32_MIN || displacement > INT32_MAX) {
            VirtualFree(relay, 0, MEM_RELEASE);
            boot_log_line(
                "grenade command callsite relay SKIPPED (range)");
            return false;
        }
        displacements[i] = static_cast<std::int32_t>(displacement);
    }

    // Publish the original before any callsite can target the wrapper. hg did
    // this after resume, leaving a real (though non-faulting) first-entry race.
    g_original_player_grenade_callsite_is_command_active =
        reinterpret_cast<PlayerInputIsCommandActiveFunction>(expected_target);
    g_grenade_relay_install_stage.store(4, std::memory_order_relaxed);
    SuspendedProcessThreads suspended_threads{};
    if (!suspend_other_process_threads(suspended_threads)) {
        VirtualFree(relay, 0, MEM_RELEASE);
        boot_log_line(
            "grenade command callsite relay SKIPPED (thread suspend)");
        return false;
    }
    g_grenade_relay_install_stage.store(5, std::memory_order_relaxed);

    std::array<DWORD, kCallsiteRvas.size()> old_protections{};
    std::size_t protected_count = 0;
    for (; protected_count < callsites.size(); ++protected_count) {
        if (!VirtualProtect(
                callsites[protected_count], 5, PAGE_EXECUTE_READWRITE,
                &old_protections[protected_count])) {
            for (std::size_t j = 0; j < protected_count; ++j) {
                DWORD ignored = 0;
                VirtualProtect(
                    callsites[j], 5, old_protections[j], &ignored);
            }
            resume_suspended_process_threads(suspended_threads);
            VirtualFree(relay, 0, MEM_RELEASE);
            boot_log_line(
                "grenade command callsite relay SKIPPED (protect)");
            return false;
        }
    }
    g_grenade_relay_install_stage.store(6, std::memory_order_relaxed);
    for (std::size_t i = 0; i < callsites.size(); ++i) {
        *reinterpret_cast<std::int32_t*>(callsites[i] + 1) =
            displacements[i];
        FlushInstructionCache(GetCurrentProcess(), callsites[i], 5);
    }
    g_grenade_relay_install_stage.store(7, std::memory_order_relaxed);
    for (std::size_t i = 0; i < callsites.size(); ++i) {
        DWORD ignored = 0;
        VirtualProtect(
            callsites[i], 5, old_protections[i], &ignored);
    }
    g_grenade_relay_install_stage.store(8, std::memory_order_relaxed);
    resume_suspended_process_threads(suspended_threads);
    g_grenade_relay_install_stage.store(9, std::memory_order_relaxed);
    boot_log_line(
        "grenade command relay installed (scheduler/state1/state2/state4 only)");
    g_grenade_relay_install_stage.store(11, std::memory_order_relaxed);
    return true;
}

bool install_fast_grenade_controller_boundary_probe() {
    auto** const start_slot = reinterpret_cast<void**>(
        g_module + kFastGrenadeControllerVtableRva +
        kFastGrenadeControllerStartVtableOffset);
    auto** const reset_slot = reinterpret_cast<void**>(
        g_module + kFastGrenadeControllerVtableRva +
        kFastGrenadeControllerResetVtableOffset);
    auto** const can_start_slot = reinterpret_cast<void**>(
        g_module + kFastGrenadeControllerVtableRva +
        kFastGrenadeControllerCanStartVtableOffset);
    if (*start_slot != reinterpret_cast<void*>(
                           g_module + kFastGrenadeControllerStartRva) ||
        *reset_slot != reinterpret_cast<void*>(
                           g_module + kFastGrenadeControllerResetRva) ||
        *can_start_slot != reinterpret_cast<void*>(
                               g_module +
                               kFastGrenadeControllerCanStartRva)) {
        boot_log_line(
            "FastGrenade boundary probe SKIPPED (vtable mismatch)");
        return false;
    }

    DWORD start_old = 0;
    DWORD reset_old = 0;
    DWORD can_start_old = 0;
    if (!VirtualProtect(
            start_slot, sizeof(void*), PAGE_READWRITE, &start_old)) {
        boot_log_line(
            "FastGrenade boundary probe SKIPPED (start protect)");
        return false;
    }
    if (!VirtualProtect(
            reset_slot, sizeof(void*), PAGE_READWRITE, &reset_old)) {
        DWORD ignored = 0;
        VirtualProtect(start_slot, sizeof(void*), start_old, &ignored);
        boot_log_line(
            "FastGrenade boundary probe SKIPPED (reset protect)");
        return false;
    }
    if (!VirtualProtect(
            can_start_slot, sizeof(void*), PAGE_READWRITE,
            &can_start_old)) {
        DWORD ignored = 0;
        VirtualProtect(start_slot, sizeof(void*), start_old, &ignored);
        VirtualProtect(reset_slot, sizeof(void*), reset_old, &ignored);
        boot_log_line(
            "FastGrenade boundary probe SKIPPED (can-start protect)");
        return false;
    }
    g_original_fast_grenade_start =
        reinterpret_cast<FastGrenadeStartFunction>(*start_slot);
    g_original_fast_grenade_reset =
        reinterpret_cast<FastGrenadeResetFunction>(*reset_slot);
    g_original_fast_grenade_can_start =
        reinterpret_cast<FastGrenadeCanStartFunction>(*can_start_slot);
    *start_slot = reinterpret_cast<void*>(&hooked_fast_grenade_start);
    *reset_slot = reinterpret_cast<void*>(&hooked_fast_grenade_reset);
    *can_start_slot =
        reinterpret_cast<void*>(&hooked_fast_grenade_can_start);
    DWORD ignored = 0;
    VirtualProtect(start_slot, sizeof(void*), start_old, &ignored);
    VirtualProtect(reset_slot, sizeof(void*), reset_old, &ignored);
    VirtualProtect(
        can_start_slot, sizeof(void*), can_start_old, &ignored);
    boot_log_line(
        "FastGrenade boundary probe installed (+0x40 start, +0x60 reset, "
        "+0xA8 can-start)");
    return true;
}

bool install_fast_grenade_release_scope() {
    auto** const release_slot = reinterpret_cast<void**>(
        g_module + kFastGrenadeControllerVtableRva +
        kFastGrenadeControllerReleaseVtableOffset);
    if (*release_slot != reinterpret_cast<void*>(
                             g_module + kFastGrenadeControllerReleaseRva)) {
        boot_log_line(
            "FastGrenade retained-Player Release scope SKIPPED (vtable mismatch)");
        return false;
    }
    DWORD old_protection = 0;
    if (!VirtualProtect(
            release_slot, sizeof(void*), PAGE_READWRITE,
            &old_protection)) {
        boot_log_line(
            "FastGrenade retained-Player Release scope SKIPPED (protect)");
        return false;
    }
    g_original_fast_grenade_release =
        reinterpret_cast<FastGrenadeReleaseFunction>(*release_slot);
    *release_slot = reinterpret_cast<void*>(&hooked_fast_grenade_release);
    DWORD ignored = 0;
    VirtualProtect(
        release_slot, sizeof(void*), old_protection, &ignored);
    boot_log_line(
        "FastGrenade retained-Player Release scope installed (+0x140)");
    return true;
}

char __fastcall hooked_player_melee_try_anim(
    void** player, void* move_vec, double move_mag) {
    if (g_puppet_melee_try_anim_bypass.load(std::memory_order_acquire) &&
        player != nullptr &&
        reinterpret_cast<void*>(player) == retained_player_object(1)) {
        void** const vtable = reinterpret_cast<void**>(*player);
        if (vtable != nullptr) {
            using MeleeAnimDecisionFunction = void(__fastcall*)(void*);
            const auto decision = reinterpret_cast<MeleeAnimDecisionFunction>(
                vtable[kPlayerMeleeAnimDecisionVtableOffset / sizeof(void*)]);
            if (decision != nullptr) {
                __try {
                    decision(reinterpret_cast<void*>(player));
                    return 1;
                } __except (EXCEPTION_EXECUTE_HANDLER) {
                }
            }
        }
    }
    if (g_original_player_melee_try_anim == nullptr) {
        return 0;
    }
    return g_original_player_melee_try_anim(player, move_vec, move_mag);
}

bool install_player_melee_try_anim_bypass() {
    auto* const target = reinterpret_cast<std::uint8_t*>(
        g_module + kPlayerMeleeTryAnimRva);
    constexpr std::array<std::uint8_t, 17> expected17{
        0x48, 0x89, 0x5C, 0x24, 0x08, 0x57, 0x48, 0x83, 0xEC, 0x40,
        0x80, 0x3D, 0x19, 0x29, 0xDD, 0x02, 0x00,
    };
    if (std::memcmp(target, expected17.data(), expected17.size()) != 0) {
        force_log_line("PlayerMeleeTryAnim bypass skipped: prologue bytes");
        return false;
    }
    constexpr std::size_t kStolen = 17;
    constexpr std::size_t kReturnJumpSize = 14;
    auto* const trampoline = static_cast<std::uint8_t*>(VirtualAlloc(
        nullptr, kStolen + kReturnJumpSize, MEM_COMMIT | MEM_RESERVE,
        PAGE_EXECUTE_READWRITE));
    if (trampoline == nullptr) {
        force_log_line("PlayerMeleeTryAnim bypass skipped: alloc failed");
        return false;
    }
    std::memcpy(trampoline, target, kStolen);
    auto* const jump_back = trampoline + kStolen;
    jump_back[0] = 0xFF;
    jump_back[1] = 0x25;
    *reinterpret_cast<std::uint32_t*>(jump_back + 2) = 0;
    *reinterpret_cast<std::uintptr_t*>(jump_back + 6) =
        reinterpret_cast<std::uintptr_t>(target + kStolen);
    FlushInstructionCache(
        GetCurrentProcess(), trampoline, kStolen + kReturnJumpSize);
    g_original_player_melee_try_anim =
        reinterpret_cast<PlayerMeleeTryAnimFunction>(trampoline);

    DWORD old_protection = 0;
    if (!VirtualProtect(target, kStolen, PAGE_EXECUTE_READWRITE,
                        &old_protection)) {
        VirtualFree(trampoline, 0, MEM_RELEASE);
        g_original_player_melee_try_anim = nullptr;
        force_log_line("PlayerMeleeTryAnim bypass skipped: protect failed");
        return false;
    }
    target[0] = 0x48;
    target[1] = 0xB8;
    *reinterpret_cast<std::uintptr_t*>(target + 2) =
        reinterpret_cast<std::uintptr_t>(&hooked_player_melee_try_anim);
    target[10] = 0xFF;
    target[11] = 0xE0;
    std::memset(target + 12, 0x90, 5);
    FlushInstructionCache(GetCurrentProcess(), target, kStolen);
    DWORD ignored = 0;
    VirtualProtect(target, kStolen, old_protection, &ignored);
    force_log_line("PlayerMeleeTryAnim bypass-hook installed (puppet melee)");
    return true;
}

std::int64_t __fastcall hooked_input_scale_copy(
    void* joypad, void* source, std::uint32_t destination_index) {
    // Serialize source mutation and the thread-local destination-3 mode override.
    // Do not write g_InputWindowFocused here: the window pump reads the same byte
    // to center and clip the cursor, so a transient background write can recapture
    // the mouse after Alt-Tab.
    AcquireSRWLockExclusive(&g_joypad3_analog_lock);
    const DWORD previous = destination_index == 3
        ? g_force_joypad3_analog_thread.exchange(
              GetCurrentThreadId(), std::memory_order_acq_rel)
        : 0;

    // Feed the remote Player through the same normalized button boundary used by
    // a native local Player. Input_ScaleCopyVirtual derives held/pressed/released
    // Joypad masks and hold timestamps from source+0x518, so command bindings
    // (jump, crouch, melee, cover, traversal, etc.) remain engine-owned.
    //
    // SHARED BUS: `source` here is NOT a private per-slot block. FrameState ctor
    // 0x14179D780 initializes the Joypad+0xF0 block selectors as {0,1,0,1,0,1}:
    // slot 3 (puppet) reads g_InputStateBlocks[1], the SAME block as slot 1 (the
    // engine's local-player-1 lane) and slot 5. Anything left in block 1 after
    // this conversion is consumed by the other lanes and by screen-level
    // HUD/strafe-camera logic -> crosshair/aim leak on the local viewport. So the
    // peer mask and look stick exist in the block only inside this call:
    // save before, restore right after the original returns.
    bool shared_bus_touched = false;
    std::uint64_t shared_bus_saved_mask = 0;
    float shared_bus_saved_look[2] = {0.0F, 0.0F};
    if (destination_index == 3 && readable_bytes(source) >= 0x520) {
        coop::StatePacket peer{};
        const bool have_peer_input =
            copy_peer_state_snapshot(peer) && (peer.flags & 8) != 0;
        const bool peer_aiming =
            have_peer_input && peer_packet_aim_active(peer);
        const bool puppet_wants_aim = peer_aiming;
        if (have_peer_input) {
            // A short press can begin and end between two conversions. Received
            // pressed edges accumulate even when a newer state snapshot replaces
            // their packet, then become one held pulse for this conversion.
            // Input_ScaleCopyVirtual derives native pressed/released masks and
            // command timestamps from that pulse.
            const std::uint64_t new_edges =
                g_state_net.pending_button_presses.exchange(
                    0, std::memory_order_acq_rel);
            if (new_edges != 0) {
                g_state_net.active_button_press_latch.fetch_or(
                    remote_puppet_actions_from_peer(new_edges) |
                        remote_puppet_fire_pulse(new_edges),
                    std::memory_order_release);
            }
            const std::uint64_t edge_pulse =
                sanitize_remote_puppet_button_mask(
                    g_state_net.active_button_press_latch.load(
                        std::memory_order_acquire));
            auto* const source_bytes = static_cast<std::byte*>(source);
            shared_bus_saved_mask =
                *reinterpret_cast<const std::uint64_t*>(source_bytes + 0x518);
            const std::uint64_t synthetic_move_gate =
                shared_bus_saved_mask & 0x500u;
            std::uint64_t held_mask =
                remote_puppet_actions_from_peer(peer.input_buttons) | edge_pulse;
            held_mask &= ~(kJoypadAimButtonMask | kJoypadFireButtonMask);
            if (puppet_aim_press_relay_enabled_for_peer(peer) && puppet_wants_aim) {
                held_mask |= kJoypadAimButtonMask;
            }
            if (GetTickCount64() < g_fire_button_hold_until_ms &&
                !puppet_fire_buttons_suppressed()) {
                held_mask |= kJoypadFireButtonMask;
            }
            if (puppet_fire_buttons_suppressed()) {
                held_mask &= ~kJoypadFireButtonMask;
            }
            held_mask = sanitize_remote_puppet_button_mask(held_mask);
            held_mask |= shared_bus_saved_mask & kInputBlockButtonBaseMask;
            *reinterpret_cast<std::uint64_t*>(source_bytes + 0x518) =
                held_mask | synthetic_move_gate;
            // Feed only the sender's native transient right-stick rate. The old
            // derived camera-minus-body error stayed non-zero after mouse motion
            // stopped and therefore spun continuously. The shared-bus sandwich
            // still keeps these axes private to puppet Joypad 3.
            auto* const axes = reinterpret_cast<float*>(source_bytes);
            shared_bus_saved_look[0] = axes[2];
            shared_bus_saved_look[1] = axes[3];
            if (puppet_aim_press_relay_enabled_for_peer(peer) &&
                g_puppet_relay_look_stick &&
                peer_packet_aim_active(peer) &&
                (peer.flags & coop::kStateFlagPeerCamera) != 0 &&
                (std::fabs(peer.look_stick[0]) > 0.001F ||
                 std::fabs(peer.look_stick[1]) > 0.001F)) {
                axes[2] = peer.look_stick[0];
                axes[3] = peer.look_stick[1];
            }
            shared_bus_touched = true;
        }
    }
    const std::int64_t result =
        g_original_input_scale_copy(joypad, source, destination_index);
    if (shared_bus_touched) {
        // Scrub the shared block-1 bus: slot 3 has consumed the peer state into
        // its own Joypad; slots 1/5 and any screen-level reader must never see
        // the peer aim/fire bits or look axes.
        auto* const source_bytes = static_cast<std::byte*>(source);
        *reinterpret_cast<std::uint64_t*>(source_bytes + 0x518) =
            shared_bus_saved_mask;
        auto* const axes = reinterpret_cast<float*>(source_bytes);
        axes[2] = shared_bus_saved_look[0];
        axes[3] = shared_bus_saved_look[1];
    }
    if (destination_index == 3 && readable_bytes(joypad) >= 0xD8) {
        // Joypad 3 is converted several times before the remote Player consumes
        // its command state. Keep accumulated traversal edges (jump/roll/crouch)
        // visible through those conversions; hooked_player_input_state_update
        // clears them after Player slot 16 consumes them (fire edge deferred).
        *reinterpret_cast<std::uint64_t*>(
            static_cast<std::byte*>(joypad) + 0xD0) |=
            remote_puppet_actions_from_peer(
                g_state_net.active_button_press_latch.load(
                    std::memory_order_acquire));
    }
    if (destination_index == 3) {
        g_force_joypad3_analog_thread.store(previous, std::memory_order_release);
    }
    ReleaseSRWLockExclusive(&g_joypad3_analog_lock);

    return result;
}

bool install_joypad3_focus_bypass() {
    // Input_ScaleCopyVirtual reads g_InputWindowFocused at 0x14183B467. Replace
    // only that 15-byte test: destination 3 may continue while backgrounded;
    // every other destination still reads the native focus byte. The window pump
    // and cursor clipping therefore continue to see the real foreground state.
    auto* const target = reinterpret_cast<std::uint8_t*>(g_module + 0x183B467);
    constexpr std::array<std::uint8_t, 15> expected{
        0x0F, 0xB6, 0x05, 0xBE, 0xF1, 0xFA, 0x01, 0x84,
        0xC0, 0x0F, 0x84, 0x4B, 0x15, 0x00, 0x00,
    };
    if (std::memcmp(target, expected.data(), expected.size()) != 0) {
        log_line("Joypad3 focus bypass skipped: unexpected focus-test bytes");
        return false;
    }

    constexpr std::size_t kStubSize = 51;
    auto* const stub = static_cast<std::uint8_t*>(VirtualAlloc(
        nullptr, kStubSize, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE));
    if (stub == nullptr) {
        log_line("Joypad3 focus bypass skipped: stub allocation failed");
        return false;
    }
    std::size_t offset = 0;
    const std::uint8_t prefix[] = {
        0x41, 0x83, 0xFC, 0x03,       // cmp r12d, 3
        0x74, 0x11,                   // je allow
        0x48, 0xB8,                   // mov rax, focus-byte address
    };
    std::memcpy(stub + offset, prefix, sizeof(prefix));
    offset += sizeof(prefix);
    *reinterpret_cast<std::uintptr_t*>(stub + offset) = g_module + 0x37EA62C;
    offset += sizeof(std::uintptr_t);
    const std::uint8_t test_focus[] = {
        0x0F, 0xB6, 0x00,             // movzx eax, byte ptr [rax]
        0x84, 0xC0,                   // test al, al
        0x74, 0x0E,                   // jz deny
    };
    std::memcpy(stub + offset, test_focus, sizeof(test_focus));
    offset += sizeof(test_focus);
    auto emit_absolute_jump = [&](std::uintptr_t destination) {
        stub[offset++] = 0xFF;
        stub[offset++] = 0x25;
        *reinterpret_cast<std::uint32_t*>(stub + offset) = 0;
        offset += sizeof(std::uint32_t);
        *reinterpret_cast<std::uintptr_t*>(stub + offset) = destination;
        offset += sizeof(std::uintptr_t);
    };
    emit_absolute_jump(g_module + 0x183B476);  // allow
    emit_absolute_jump(g_module + 0x183C9C1);  // deny
    if (offset != kStubSize) {
        VirtualFree(stub, 0, MEM_RELEASE);
        log_line("Joypad3 focus bypass skipped: internal stub size mismatch");
        return false;
    }
    FlushInstructionCache(GetCurrentProcess(), stub, kStubSize);

    DWORD old_protection = 0;
    if (!VirtualProtect(target, expected.size(), PAGE_EXECUTE_READWRITE,
                        &old_protection)) {
        VirtualFree(stub, 0, MEM_RELEASE);
        log_line("Joypad3 focus bypass skipped: VirtualProtect failed");
        return false;
    }
    target[0] = 0xFF;
    target[1] = 0x25;
    *reinterpret_cast<std::uint32_t*>(target + 2) = 0;
    *reinterpret_cast<std::uintptr_t*>(target + 6) =
        reinterpret_cast<std::uintptr_t>(stub);
    target[14] = 0x90;
    FlushInstructionCache(GetCurrentProcess(), target, expected.size());
    DWORD ignored = 0;
    VirtualProtect(target, expected.size(), old_protection, &ignored);
    log_line("Joypad3 background input bypasses focus test without changing cursor focus");
    return true;
}

bool install_joypad3_analog_route() {
    auto* const game_info_vtable = reinterpret_cast<std::uintptr_t*>(
        g_module + kGameInfoVtableRva);
    auto* const mode_slot = &game_info_vtable[0x90 / sizeof(void*)];
    if (*mode_slot != g_module + 0x29AB50) {
        log_line("Joypad3 analog route skipped: unexpected GameInfo vfunc+0x90");
        return false;
    }
    g_original_gameinfo_keyboard_mode =
        reinterpret_cast<GameInfoKeyboardModeFunction>(*mode_slot);
    DWORD old_mode_protection = 0;
    if (!VirtualProtect(mode_slot, sizeof(*mode_slot), PAGE_READWRITE,
                        &old_mode_protection)) {
        log_line("Joypad3 analog route skipped: GameInfo vtable protect failed");
        return false;
    }
    *mode_slot = reinterpret_cast<std::uintptr_t>(&hooked_gameinfo_keyboard_mode);
    FlushInstructionCache(GetCurrentProcess(), mode_slot, sizeof(*mode_slot));
    DWORD ignored_mode = 0;
    VirtualProtect(mode_slot, sizeof(*mode_slot), old_mode_protection, &ignored_mode);

    auto* const target = reinterpret_cast<std::uint8_t*>(
        g_module + kInputScaleCopyRva);
    constexpr std::array<std::uint8_t, 15> expected{
        0x40, 0x55, 0x56, 0x41, 0x54, 0x41, 0x57, 0x48,
        0x8D, 0xAC, 0x24, 0xB8, 0xCB, 0xFF, 0xFF,
    };
    if (std::memcmp(target, expected.data(), expected.size()) != 0) {
        log_line("Joypad3 analog route skipped: unexpected Input_ScaleCopy prologue");
        return false;
    }

    constexpr std::size_t kPatchSize = expected.size();
    constexpr std::size_t kJumpSize = 12;
    auto* const trampoline = static_cast<std::uint8_t*>(VirtualAlloc(
        nullptr, kPatchSize + kJumpSize, MEM_COMMIT | MEM_RESERVE,
        PAGE_EXECUTE_READWRITE));
    if (trampoline == nullptr) {
        log_line("Joypad3 analog route skipped: trampoline allocation failed");
        return false;
    }
    std::memcpy(trampoline, target, kPatchSize);
    auto* const jump_back = trampoline + kPatchSize;
    jump_back[0] = 0x48;
    jump_back[1] = 0xB8;
    *reinterpret_cast<std::uintptr_t*>(jump_back + 2) =
        reinterpret_cast<std::uintptr_t>(target + kPatchSize);
    jump_back[10] = 0xFF;
    jump_back[11] = 0xE0;
    FlushInstructionCache(GetCurrentProcess(), trampoline, kPatchSize + kJumpSize);
    g_original_input_scale_copy =
        reinterpret_cast<InputScaleCopyFunction>(trampoline);

    DWORD old_target_protection = 0;
    if (!VirtualProtect(target, kPatchSize, PAGE_EXECUTE_READWRITE,
                        &old_target_protection)) {
        VirtualFree(trampoline, 0, MEM_RELEASE);
        g_original_input_scale_copy = nullptr;
        log_line("Joypad3 analog route skipped: function protect failed");
        return false;
    }
    target[0] = 0x48;
    target[1] = 0xB8;
    *reinterpret_cast<std::uintptr_t*>(target + 2) =
        reinterpret_cast<std::uintptr_t>(&hooked_input_scale_copy);
    target[10] = 0xFF;
    target[11] = 0xE0;
    std::memset(target + kJumpSize, 0x90, kPatchSize - kJumpSize);
    FlushInstructionCache(GetCurrentProcess(), target, kPatchSize);
    DWORD ignored_target = 0;
    VirtualProtect(target, kPatchSize, old_target_protection, &ignored_target);
    log_line("Joypad3 uses native analog source while keyboard mode remains global");
    install_joypad3_focus_bypass();
    return true;
}

bool install_joypad_disabled_commands_lock() {
    auto* const target = reinterpret_cast<std::uint8_t*>(
        g_module + kAddJoypadDisabledCommandsRva);
    constexpr std::array<std::uint8_t, 14> expected{
        0x40, 0x53, 0x55, 0x56, 0x57, 0x41, 0x57, 0x48,
        0x81, 0xEC, 0x80, 0x00, 0x00, 0x00,
    };
    if (std::memcmp(target, expected.data(), expected.size()) != 0) {
        log_line("joypad command lock hook skipped: unexpected function prologue");
        return false;
    }

    constexpr std::size_t kPatchSize = expected.size();
    constexpr std::size_t kJumpSize = 12;
    auto* const trampoline = static_cast<std::uint8_t*>(VirtualAlloc(
        nullptr, kPatchSize + kJumpSize, MEM_COMMIT | MEM_RESERVE,
        PAGE_EXECUTE_READWRITE));
    if (trampoline == nullptr) {
        log_line("joypad command lock hook skipped: trampoline allocation failed");
        return false;
    }
    std::memcpy(trampoline, target, kPatchSize);
    std::uint8_t* jump_back = trampoline + kPatchSize;
    jump_back[0] = 0x48;
    jump_back[1] = 0xB8;  // mov rax, imm64
    *reinterpret_cast<std::uintptr_t*>(jump_back + 2) =
        reinterpret_cast<std::uintptr_t>(target + kPatchSize);
    jump_back[10] = 0xFF;
    jump_back[11] = 0xE0;  // jmp rax
    FlushInstructionCache(GetCurrentProcess(), trampoline, kPatchSize + kJumpSize);

    g_original_add_joypad_disabled_commands =
        reinterpret_cast<AddJoypadDisabledCommandsFunction>(trampoline);

    DWORD old_protection = 0;
    if (!VirtualProtect(target, kPatchSize, PAGE_EXECUTE_READWRITE,
                        &old_protection)) {
        VirtualFree(trampoline, 0, MEM_RELEASE);
        g_original_add_joypad_disabled_commands = nullptr;
        log_line("joypad command lock hook skipped: VirtualProtect failed");
        return false;
    }
    target[0] = 0x48;
    target[1] = 0xB8;  // mov rax, imm64
    *reinterpret_cast<std::uintptr_t*>(target + 2) =
        reinterpret_cast<std::uintptr_t>(&hooked_add_joypad_disabled_commands);
    target[10] = 0xFF;
    target[11] = 0xE0;  // jmp rax
    target[12] = 0x90;
    target[13] = 0x90;
    FlushInstructionCache(GetCurrentProcess(), target, kPatchSize);
    DWORD ignored = 0;
    VirtualProtect(target, kPatchSize, old_protection, &ignored);

    log_line("joypad disabled-command mutation serialized for multiple Players");
    return true;
}

