bool install_breakable_event_probe() {
    constexpr std::array<std::uint8_t, 16> kSendMaskPrologue{
        0x48, 0x89, 0x5C, 0x24, 0x18, 0x55, 0x56, 0x57,
        0x41, 0x54, 0x41, 0x55, 0x41, 0x56, 0x41, 0x57,
    };
    g_original_net_event_send_mask =
        reinterpret_cast<NetGameManagerSendNetEventMaskFn>(
            install_fire_gate_detour(
                kNetGameManagerSendNetEventMaskRva,
                kSendMaskPrologue.data(),
                kSendMaskPrologue.size(),
                reinterpret_cast<void*>(&hooked_net_event_send_mask),
                "breakable NetEvent send-mask probe"));
    boot_log_line(g_original_net_event_send_mask != nullptr
                      ? "breakable NetEvent send-mask probe installed"
                      : "breakable NetEvent send-mask probe SKIPPED");

    install_breakable_sync_multicast_callsite_hook();
    install_breakable_resolver_override_hook();
    install_send_sync_breakable_hook();
    install_simple_breakable_explosion_damage_hook();

    if (install_simple_breakable_local_apply_hook()) {
        g_breakable_local_apply_hook_installed.store(
            true, std::memory_order_release);
    } else if (install_simple_breakable_local_apply_hook_alt()) {
        g_breakable_local_apply_hook_installed.store(
            true, std::memory_order_release);
    }
    install_breakable_explosion_damage_post_hook();

    return g_original_net_event_send_mask != nullptr;
}

bool seh_execute_breakable_event_blob(
    std::uint8_t kind, const std::uint8_t* blob, std::size_t blob_size,
    std::uintptr_t* fault_rva, DWORD* fault_code) {
    if (blob == nullptr || blob_size == 0) return false;
    if (fault_rva != nullptr) *fault_rva = 0;
    if (fault_code != nullptr) *fault_code = 0;
    const auto resolver_ctx =
        static_cast<__int64>(g_module + kNetObjectResolverTableRva);
    __try {
        if (kind == coop::kBreakableNetEventTypeExplosionWithResults &&
            blob_size >= coop::kBreakableExplosionEventBytes) {
            alignas(16) std::uint8_t event[coop::kBreakableExplosionEventBytes]{};
            std::memcpy(event, blob, coop::kBreakableExplosionEventBytes);
            const auto execute =
                reinterpret_cast<BreakableExplosionWithResultsExecuteFn>(
                    g_module +
                    kNetEventBreakableAttackExplosionWithResultsExecuteRva);
            execute(event, 0, resolver_ctx);
            return true;
        }
        if (kind == coop::kBreakableNetEventTypeExplosionPlain &&
            blob_size >= coop::kBreakableExplosionPlainEventBytes) {
            alignas(16) std::uint8_t event[coop::kBreakableExplosionPlainEventBytes]{};
            std::memcpy(event, blob, coop::kBreakableExplosionPlainEventBytes);
            const auto execute = reinterpret_cast<BreakableExplosionExecuteFn>(
                g_module + kNetEventBreakableAttackExplosionExecuteRva);
            execute(event, 0, resolver_ctx);
            return true;
        }
        if (kind == coop::kBreakableNetEventTypeProjectileWithResults &&
            blob_size >= coop::kBreakableProjectileEventBytes) {
            alignas(16) std::uint8_t event[coop::kBreakableProjectileEventBytes]{};
            std::memcpy(event, blob, coop::kBreakableProjectileEventBytes);
            const auto execute =
                reinterpret_cast<BreakableProjectileWithResultsExecuteFn>(
                    g_module +
                    kNetEventBreakableAttackProjectileWithResultsExecuteRva);
            execute(event, 0, resolver_ctx);
            return true;
        }
        if (kind == coop::kBreakableNetEventTypeProjectilePlain &&
            blob_size >= coop::kBreakableProjectilePlainEventBytes) {
            alignas(16) std::uint8_t event[coop::kBreakableProjectilePlainEventBytes]{};
            std::memcpy(event, blob, coop::kBreakableProjectilePlainEventBytes);
            const auto execute = reinterpret_cast<BreakableProjectileExecuteFn>(
                g_module + kNetEventBreakableAttackProjectileExecuteRva);
            execute(event, 0, resolver_ctx);
            return true;
        }
        if (kind == coop::kBreakableNetEventTypeSync &&
            blob_size >= coop::kBreakableSyncEventBytes) {
            alignas(16) std::uint8_t event[coop::kBreakableSyncEventBytes]{};
            std::memcpy(event, blob, coop::kBreakableSyncEventBytes);
            const auto execute = reinterpret_cast<BreakableSyncExecuteFn>(
                g_module + kNetEventSyncBreakableExecuteRva);
            execute(event, 0, resolver_ctx);
            return true;
        }
    } __except (capture_grenade_event_exception(
        GetExceptionInformation(), fault_rva, fault_code)) {
        return false;
    }
    return false;
}

void apply_pending_peer_breakable_event() {
    if (!g_breakable_event_relay ||
        !g_pending_breakable_event.exchange(false, std::memory_order_acq_rel)) {
        return;
    }
    const std::uint32_t seq = g_pending_breakable_seq.load(
        std::memory_order_relaxed);
    if (seq == 0 || seq == g_last_applied_breakable_seq.load(
                               std::memory_order_relaxed)) {
        return;
    }
    const auto kind = g_pending_breakable_kind.load(std::memory_order_relaxed);
    const std::size_t blob_size = breakable_blob_size_for_kind(kind);
    std::uint32_t net_id = 0;
    if (readable_bytes(g_pending_breakable_blob + 28) >= 4) {
        std::memcpy(&net_id, g_pending_breakable_blob + 24, sizeof(net_id));
    }
    void* resolved = nullptr;
    if (kind == coop::kBreakableNetEventTypeSync) {
        resolved = peek_net_object_from_table(net_id);
        if (resolved == nullptr) {
            const std::uint32_t scene_hash =
                g_pending_breakable_scene_hash.load(std::memory_order_relaxed);
            if (scene_hash != 0) {
                resolved = find_simple_breakable_by_scene_hash(scene_hash);
            }
        }
        if (resolved == nullptr &&
            valid_network_position(g_pending_breakable_world_pos)) {
            resolved = find_simple_breakable_near_position(
                g_pending_breakable_world_pos, 16.0f * 16.0f);
        }
        if (resolved != nullptr) {
            std::uint32_t override_id = net_id;
            if (override_id == 0 &&
                readable_bytes(static_cast<std::byte*>(resolved) + 0xDC) >= 4) {
                std::memcpy(&override_id, static_cast<std::byte*>(resolved) + 0xD8,
                            sizeof(override_id));
                if (override_id != 0) {
                    std::memcpy(g_pending_breakable_blob + 24, &override_id,
                                sizeof(override_id));
                }
            }
            if (override_id != 0) {
                g_breakable_resolver_override_id.store(
                    override_id, std::memory_order_relaxed);
                g_breakable_resolver_override_obj.store(
                    resolved, std::memory_order_relaxed);
            }
        }
    }
    std::uintptr_t fault_rva = 0;
    DWORD fault_code = 0;
    const bool ok = seh_execute_breakable_event_blob(
        kind, g_pending_breakable_blob, blob_size, &fault_rva, &fault_code);
    g_breakable_resolver_override_id.store(0, std::memory_order_relaxed);
    g_breakable_resolver_override_obj.store(nullptr, std::memory_order_relaxed);
    g_last_applied_breakable_seq.store(seq, std::memory_order_relaxed);
    std::ostringstream line;
    line << "BRK-EXEC seq=" << seq
         << " kind=0x" << std::hex << static_cast<unsigned>(kind) << std::dec
         << " netId=" << net_id
         << " hash=0x" << std::hex
         << g_pending_breakable_scene_hash.load(std::memory_order_relaxed)
         << std::dec
         << " resolved=" << resolved
         << " pos=(" << g_pending_breakable_world_pos[0] << ","
         << g_pending_breakable_world_pos[1] << ","
         << g_pending_breakable_world_pos[2] << ")"
         << " ok=" << (ok ? 1 : 0)
         << " faultRva=0x" << std::hex << fault_rva
         << " faultCode=0x" << fault_code << std::dec;
    log_breakable_line(line);
}

bool install_weapon_pickup_gate() {
    // WeaponPickupInteractControl::OnInteract 0x14157AA70 prologue:
    // mov rax,rsp; push rbp; push rsi; push rdi; push r12..r15 (14 bytes, all
    // position-independent).
    constexpr std::array<std::uint8_t, 14> kOnInteractPrologue{
        0x48, 0x8B, 0xC4,
        0x55, 0x56, 0x57,
        0x41, 0x54, 0x41, 0x55, 0x41, 0x56, 0x41, 0x57,
    };
    g_original_weapon_pickup_on_interact =
        reinterpret_cast<WeaponPickupOnInteractFunction>(
            install_fire_gate_detour(
                kWeaponPickupOnInteractRva,
                kOnInteractPrologue.data(),
                kOnInteractPrologue.size(),
                reinterpret_cast<void*>(&hooked_weapon_pickup_on_interact),
                "weapon-pickup OnInteract relay"));
    boot_log_line(g_original_weapon_pickup_on_interact != nullptr
                      ? "weapon-pickup OnInteract relay installed"
                      : "weapon-pickup OnInteract relay SKIPPED");
    return g_original_weapon_pickup_on_interact != nullptr;
}

// DIAGNOSTIC (2026-07-06): log every PlayerWeaponController::GiveWeapon call with
// the art id and the RETURN ADDRESS RVA. Purpose: the OnInteract pickup hook is
// installed but SILENT on real ground pickups (runtime-disproved twice), so the
// true pickup->give caller is unknown. GiveWeapon is vtable +0x158 (virtual, no
// static xrefs); one logged pickup names the real path. Hooked at +9 because the
// function opens with `test rdx,rdx; jz rel32` (relative, not relocatable); at +9
// the next 17 bytes are position-independent pushes/lea and RAX is dead.
using GiveWeaponTailFunction = void(__fastcall*)(
    void*, void*, std::int64_t, std::int64_t, std::int64_t);
GiveWeaponTailFunction g_original_give_weapon_tail = nullptr;

void* seh_get_give_replaced_weapon(void* controller, const void* weapon_info) {
    if (controller == nullptr || weapon_info == nullptr) {
        return nullptr;
    }
    __try {
        std::uint32_t slot = *reinterpret_cast<const std::uint32_t*>(
            static_cast<const std::byte*>(weapon_info) + 8);
        // PlayerWeaponController::GiveWeapon performs this exact campaign-only
        // raw-slot mapping at 0x1410A4E2D..0x1410A4E47 before vt+0xB0.
        if (slot == 16) {
            slot = 0;
        } else if (slot == 17 || slot == 22) {
            slot = 1;
        }
        auto** const vtable = *reinterpret_cast<void***>(controller);
        using GetWeaponBySlotFn = void*(__fastcall*)(void*, std::uint32_t);
        const auto get_weapon = reinterpret_cast<GetWeaponBySlotFn>(
            vtable[0xB0 / sizeof(void*)]);
        return get_weapon != nullptr ? get_weapon(controller, slot) : nullptr;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return nullptr;
    }
}

bool seh_build_dropped_pickup_event_payload(
    void* dropped_weapon, std::uint8_t out[coop::kDroppedPickupEventPayloadBytes]) {
    if (dropped_weapon == nullptr || out == nullptr || g_module == 0) {
        return false;
    }
    alignas(16) std::uint8_t event[0x80]{};
    using CtorFn = void*(__fastcall*)(void*, void*);
    const auto ctor = reinterpret_cast<CtorFn>(
        g_module + kNetEventAddDroppedPickupCtorFromProcessWeaponRva);
    __try {
        ctor(event, dropped_weapon);
        const std::uint32_t stable_id =
            *reinterpret_cast<const std::uint32_t*>(event + 0x1C);
        const std::uint32_t network_art =
            *reinterpret_cast<const std::uint32_t*>(event + 0x20);
        if (stable_id == 0 || network_art == 0) {
            return false;
        }
        std::memcpy(out, event + 0x18,
                    coop::kDroppedPickupEventPayloadBytes);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

void __fastcall hooked_give_weapon_tail(
    void* controller, void* weapon_info, std::int64_t a3, std::int64_t a4,
    std::int64_t a5) {
    const std::uintptr_t ret =
        reinterpret_cast<std::uintptr_t>(_ReturnAddress());
    static std::atomic<int> logged{0};
    if (logged.fetch_add(1) < 400) {
        std::uint32_t art = 0;
        if (weapon_info != nullptr &&
            readable_bytes(static_cast<std::byte*>(weapon_info) + 0x80) >=
                sizeof(art)) {
            std::memcpy(
                &art, static_cast<std::byte*>(weapon_info) + 0x80, sizeof(art));
        }
        std::ostringstream line;
        line << "GIVEWEAPON-CALL art=0x" << std::hex << art
             << " ctrl=0x" << reinterpret_cast<std::uintptr_t>(controller)
             << " ret_rva=0x" << (ret - g_module)
             << std::dec << " a3=" << a3 << " a4=" << a4 << " a5=" << a5;
        force_log_line(line.str().c_str());
        // Full 0xC0 WeaponInfo hex (24 qwords): needed to learn the real block
        // schema (which fields are pointers vs POD) before any cross-process
        // relay of picked-up weapons. Compare a real pickup's block against our
        // synthetic initialize_info+art one for the same art.
        if (weapon_info != nullptr &&
            readable_bytes(static_cast<std::byte*>(weapon_info)) >= 0xC0) {
            const auto* q = static_cast<const std::uint64_t*>(weapon_info);
            for (int row = 0; row < 3; ++row) {
                std::ostringstream dump;
                dump << "GIVEWEAPON-INFO+" << std::hex << (row * 0x40) << ":";
                for (int i = 0; i < 8; ++i) {
                    dump << " " << std::setw(16) << std::setfill('0')
                         << q[row * 8 + i];
                }
                force_log_line(dump.str().c_str());
            }
        }
    }
    // PICKED-UP WEAPON RELAY (sender): capture after native GiveWeapon completes so
    // find_weapon_slot_by_art_id sees the new inventory entry.
    bool relay_pickup_after_give = false;
    std::uint32_t relay_pickup_object_id = 0;
    std::uint32_t relay_pickup_stable_id = 0;
    std::uint32_t relay_pickup_class_id = 0;
    std::uint32_t relay_pickup_name_id = 0;
    void* relay_dropped_weapon = nullptr;
    std::uint32_t relay_dropped_weapon_art = 0;
    std::uint8_t relay_dropped_weapon_detach_flags = 0;
    coop::WeaponGivePacket relay_pkt{};
    void* relay_local_player = nullptr;
    if (g_pickup_relay && g_state_net.enabled && g_state_net.peer_set &&
        weapon_info != nullptr) {
        if (ret - g_module == kPickupGiveRetRva) {
            void* const resolved_local = resolve_live_player_safe(0);
            void* const retained_local = retained_player_object(0);
            auto controller_from_player = [](void* candidate) -> void* {
                if (candidate == nullptr ||
                    readable_bytes(static_cast<std::byte*>(candidate) + 0x1D90) <
                        sizeof(void*)) {
                    return nullptr;
                }
                return *reinterpret_cast<void**>(
                    static_cast<std::byte*>(candidate) + 0x1D88);
            };
            void* const resolved_ctrl = controller_from_player(resolved_local);
            void* const retained_ctrl = controller_from_player(retained_local);
            const bool resolved_owner =
                controller != nullptr && controller == resolved_ctrl;
            const bool retained_owner =
                controller != nullptr && controller == retained_ctrl;
            void* const local_player = retained_owner
                ? retained_local
                : (resolved_owner ? resolved_local : nullptr);
            {
                static std::atomic<int> exact_logged{0};
                if (exact_logged.fetch_add(1, std::memory_order_relaxed) < 32) {
                    std::ostringstream line;
                    line << "GIVEWEAPON-PICKUP-ADMISSION ctrl=0x" << std::hex
                         << reinterpret_cast<std::uintptr_t>(controller)
                         << " retainedCtrl=0x"
                         << reinterpret_cast<std::uintptr_t>(retained_ctrl)
                         << " resolvedCtrl=0x"
                         << reinterpret_cast<std::uintptr_t>(resolved_ctrl)
                         << std::dec << " retained=" << (retained_owner ? 1 : 0)
                         << " resolved=" << (resolved_owner ? 1 : 0);
                    force_log_line(line.str().c_str());
                }
            }
            if (local_player != nullptr &&
                readable_bytes(static_cast<std::byte*>(weapon_info)) >=
                    coop::kWeaponInfoBytes) {
                std::uint32_t relay_art = 0;
                std::memcpy(&relay_art,
                            static_cast<std::byte*>(weapon_info) + 0x80,
                            sizeof(relay_art));
                if (!is_pickup_relay_art(relay_art)) {
                    // Spawn/loadout whitelist arts: held-weapon sync only.
                } else {
                    // Capture while the pickup is still in the world / interact
                    // control — after GiveWeapon the nearby list is usually empty.
                    relay_pickup_object_id = capture_weapon_pickup_for_relay(
                        local_player, controller, relay_art);
                    if (relay_pickup_object_id == 0) {
                        relay_pickup_object_id =
                            capture_pickup_id_from_weapon_info(weapon_info);
                    }
                    if (relay_pickup_object_id != 0) {
                        void* const pickup = resolve_weapon_pickup_by_runtime_id(
                            relay_pickup_object_id, relay_art);
                        if (pickup != nullptr) {
                            relay_pickup_stable_id =
                                read_weapon_pickup_stable_id(
                                    reinterpret_cast<std::uint64_t>(pickup));
                            seh_read_dword(
                                static_cast<const std::byte*>(pickup) + 0x38,
                                relay_pickup_class_id);
                            seh_read_dword(
                                static_cast<const std::byte*>(pickup) + 0xD8,
                                relay_pickup_name_id);
                        }
                        std::ostringstream cap;
                        cap << "PICKUP-ID-CAPTURE pre-give id=0x" << std::hex
                            << relay_pickup_object_id << " art=0x" << relay_art
                            << " class=0x" << relay_pickup_class_id
                            << " name=0x" << relay_pickup_name_id
                            << std::dec;
                        force_log_line(cap.str().c_str());
                    }
                    const ULONGLONG captured_ms =
                        g_sender_pickup_capture_ms.load(
                            std::memory_order_acquire);
                    if (relay_pickup_stable_id == 0 && captured_ms != 0 &&
                        GetTickCount64() - captured_ms <= 4000 &&
                        relay_weapon_art_matches(
                            g_sender_pickup_capture_art.load(
                                std::memory_order_acquire),
                            relay_art)) {
                        relay_pickup_stable_id =
                            g_sender_pickup_stable_id.load(
                                std::memory_order_acquire);
                    }
                    relay_pickup_after_give = true;
                    relay_local_player = local_player;
                    relay_pkt.sequence = g_weapon_give_send_seq.fetch_add(1) + 1;
                    relay_pkt.draw_flag = static_cast<std::uint8_t>(a3 & 0xFF);
                    std::memcpy(&relay_pkt.weapon_art_id,
                                static_cast<std::byte*>(weapon_info) + 0x80,
                                sizeof(relay_pkt.weapon_art_id));
                    std::memcpy(relay_pkt.weapon_info, weapon_info,
                                coop::kWeaponInfoBytes);
                    if (kGiveWeaponWorldLifecycleEnabled &&
                        relay_pickup_stable_id != 0) {
                        relay_pkt.world_flags |=
                            coop::kWeaponGiveWorldConsume;
                        relay_pkt.consumed_pickup_stable_id =
                            relay_pickup_stable_id;
                    }
                    relay_dropped_weapon =
                        seh_get_give_replaced_weapon(controller, weapon_info);
                    if (relay_dropped_weapon != nullptr &&
                        readable_bytes(relay_dropped_weapon) >= 0x87E) {
                        relay_dropped_weapon_art =
                            *reinterpret_cast<const std::uint32_t*>(
                                static_cast<const std::byte*>(
                                    relay_dropped_weapon) +
                                0x860);
                        relay_dropped_weapon_detach_flags =
                            *reinterpret_cast<const std::uint8_t*>(
                                static_cast<const std::byte*>(
                                    relay_dropped_weapon) +
                                0x690);
                    }
                }
            }
        }
    }
    if (ret - g_module == kPickupGiveRetRva &&
        GetTickCount64() <
            g_puppet_pickup_anim_suppress_until_ms.load(
                std::memory_order_acquire)) {
        void* const puppet = retained_player_object(1);
        void* puppet_controller = nullptr;
        if (puppet != nullptr &&
            readable_bytes(static_cast<std::byte*>(puppet) + 0x1D90) >=
                sizeof(void*)) {
            puppet_controller = *reinterpret_cast<void**>(
                static_cast<std::byte*>(puppet) + 0x1D88);
        }
        if (controller == puppet_controller && puppet_controller != nullptr) {
            force_log_line(
                "PICKUP-ANIM-SUPPRESS puppet give-weapon completion");
            return;
        }
    }
    if (g_original_give_weapon_tail != nullptr) {
        g_original_give_weapon_tail(controller, weapon_info, a3, a4, a5);
    }
    if (relay_pickup_after_give && relay_dropped_weapon != nullptr &&
        relay_dropped_weapon_art != 0 &&
        relay_dropped_weapon_art != relay_pkt.weapon_art_id &&
        readable_bytes(relay_dropped_weapon) >= 0x87E) {
        const std::uint8_t detach_flags =
            *reinterpret_cast<const std::uint8_t*>(
                static_cast<const std::byte*>(relay_dropped_weapon) + 0x690);
        const bool newly_detached =
            (detach_flags & 0x08) != 0 &&
            (relay_dropped_weapon_detach_flags & 0x08) == 0;
        if (kGiveWeaponWorldLifecycleEnabled && newly_detached &&
            seh_build_dropped_pickup_event_payload(
                                  relay_dropped_weapon,
                                  relay_pkt.dropped_pickup_event_payload)) {
            relay_pkt.world_flags |= coop::kWeaponGiveWorldDrop;
            relay_pkt.dropped_weapon_art_id = relay_dropped_weapon_art;
        }
    }
    if (relay_pickup_after_give) {
        if (relay_local_player != nullptr) {
            const int found_slot = find_weapon_slot_by_art_id(
                relay_local_player, relay_pkt.weapon_art_id);
            const int slot = resolve_give_target_slot(
                relay_pkt.weapon_art_id, found_slot);
            relay_pkt.manager_slot = static_cast<std::int8_t>(slot);
        }
        sendto(g_state_net.send_socket,
               reinterpret_cast<const char*>(&relay_pkt), sizeof(relay_pkt), 0,
               reinterpret_cast<const sockaddr*>(&g_state_net.peer_addr),
               sizeof(g_state_net.peer_addr));
        std::ostringstream line;
        line << "GIVEWEAPON-RELAY-SEND art=0x" << std::hex
             << relay_pkt.weapon_art_id << std::dec
             << " seq=" << relay_pkt.sequence
             << " draw=" << static_cast<int>(relay_pkt.draw_flag)
             << " slot=" << static_cast<int>(relay_pkt.manager_slot)
             << " pickup_id=0x" << std::hex << relay_pickup_object_id
             << " stable_id=0x" << relay_pkt.consumed_pickup_stable_id
             << " dropped_art=0x" << relay_pkt.dropped_weapon_art_id
             << std::dec << " world_flags=0x" << std::hex
             << relay_pkt.world_flags << std::dec;
        force_log_line(line.str().c_str());
        g_sender_pickup_capture_ms.store(0, std::memory_order_release);
        if (relay_pickup_object_id != 0) {
            coop::PickupPacket anim_pkt{};
            anim_pkt.sequence = g_pickup_send_seq.fetch_add(1) + 1;
            anim_pkt.pickup_object_id = relay_pickup_object_id;
            anim_pkt.weapon_art_id = relay_pkt.weapon_art_id;
            anim_pkt.interact_class_id = relay_pickup_class_id;
            anim_pkt.interact_name_id = relay_pickup_name_id;
            sendto(g_state_net.send_socket,
                   reinterpret_cast<const char*>(&anim_pkt), sizeof(anim_pkt), 0,
                   reinterpret_cast<const sockaddr*>(&g_state_net.peer_addr),
                   sizeof(g_state_net.peer_addr));
            std::ostringstream anim_line;
            anim_line << "PICKUP-ANIM-SEND id=0x" << std::hex
                      << relay_pickup_object_id << " art=0x"
                      << relay_pkt.weapon_art_id << " class=0x"
                      << anim_pkt.interact_class_id << " name=0x"
                      << anim_pkt.interact_name_id << std::dec
                      << " seq=" << anim_pkt.sequence << " via=give-relay";
            force_log_line(anim_line.str().c_str());
        }
        // Compare placements: local (sender) slot layout right after the pickup
        // give vs the puppet's PUPPET-AFTER-GIVE dump on the receiver.
        {
            void* sender_player = resolve_live_player_safe(0);
            if (sender_player != nullptr) {
                dump_player_weapon_slots("SENDER-AFTER-PICKUP", sender_player);
            }
        }
        // Do not synthesize NetEventSyncWeaponPickups from WeaponInfo here.
        // +0x58 was misidentified as a pickup runtime id: it is the same
        // 0xe446a2ce for different pickups. Applying it locally hung the sender
        // after M-30 GiveWeapon. Weapon display/loadout sync is fully carried by
        // WeaponGivePacket + the peer raw-slot snapshot.
    }
}

bool install_give_weapon_diagnostic() {
    // PlayerWeaponController::GiveWeapon 0x1410A4D40 + 9 (skip test rdx/jz):
    // mov r11,rsp; push rbp; push r13; push r14; push r15; lea rbp,[r11-0x868].
    constexpr std::array<std::uint8_t, 17> kGiveWeaponTailPrologue{
        0x4C, 0x8B, 0xDC, 0x55, 0x41, 0x55, 0x41, 0x56, 0x41, 0x57,
        0x49, 0x8D, 0xAB, 0x98, 0xF7, 0xFF, 0xFF,
    };
    g_original_give_weapon_tail =
        reinterpret_cast<GiveWeaponTailFunction>(
            install_fire_gate_detour(
                kGiveWeaponTailRva,
                kGiveWeaponTailPrologue.data(),
                kGiveWeaponTailPrologue.size(),
                reinterpret_cast<void*>(&hooked_give_weapon_tail),
                "GiveWeapon caller diagnostic"));
    boot_log_line(g_original_give_weapon_tail != nullptr
                      ? "GiveWeapon caller diagnostic installed"
                      : "GiveWeapon caller diagnostic SKIPPED");
    return g_original_give_weapon_tail != nullptr;
}

using FhudPublishInteractRecordFunction = void(__fastcall*)(void*, void*);
FhudPublishInteractRecordFunction g_original_hud_draw_interactable_record =
    nullptr;

struct FhudFallbackRecordIdentity {
    std::uintptr_t weak_handle{0};
    std::uint32_t weak_generation{0};
    std::uint32_t fallback_id{0};
};

bool seh_read_fhud_fallback_record_identity(
    const void* record, FhudFallbackRecordIdentity& identity) {
    identity = {};
    if (record == nullptr || readable_bytes(record) < 0x2C) return false;
    __try {
        const auto* bytes = static_cast<const std::byte*>(record);
        identity.weak_handle =
            *reinterpret_cast<const std::uintptr_t*>(bytes + 0x18);
        identity.weak_generation =
            *reinterpret_cast<const std::uint32_t*>(bytes + 0x20);
        identity.fallback_id =
            *reinterpret_cast<const std::uint32_t*>(bytes + 0x28);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        identity = {};
        return false;
    }
}

void __fastcall hooked_hud_draw_interactable_record(
    void* per_screen_hud_state, void* record) {
    // hud-draw-interactable-on-object builds a fallback-keyed record without a
    // Player pointer or object weak handle. Its explicit per-screen state is the
    // only proven ownership value: as with the confirmed reticle fix, screen 0
    // is this copy's visible local HUD and screen != 0 is the retained puppet.
    FhudFallbackRecordIdentity identity{};
    const bool have_identity =
        seh_read_fhud_fallback_record_identity(record, identity);
    if (hud_state_is_non_primary_screen(per_screen_hud_state)) {
        static std::atomic<int> suppressed{0};
        if (suppressed.fetch_add(1, std::memory_order_relaxed) < 32) {
            std::ostringstream line;
            line << "PICKUP-HUD-FALLBACK-SUPPRESS screen=non-primary"
                 << " weak=0x" << std::hex
                 << (have_identity ? identity.weak_handle : 0)
                 << ":" << (have_identity ? identity.weak_generation : 0)
                 << " fallback=0x"
                 << (have_identity ? identity.fallback_id : 0)
                 << std::dec;
            boot_log_line(line.str().c_str());
        }
        return;
    }
    static std::atomic<bool> local_logged{false};
    if (!local_logged.exchange(true, std::memory_order_relaxed)) {
        std::ostringstream line;
        line << "PICKUP-HUD-FALLBACK-ALLOW screen=primary"
             << " weak=0x" << std::hex
             << (have_identity ? identity.weak_handle : 0)
             << ":" << (have_identity ? identity.weak_generation : 0)
             << " fallback=0x"
             << (have_identity ? identity.fallback_id : 0)
             << std::dec;
        boot_log_line(line.str().c_str());
    }
    if (g_original_hud_draw_interactable_record != nullptr) {
        g_original_hud_draw_interactable_record(
            per_screen_hud_state, record);
    }
}

bool install_hud_draw_interactable_primary_screen_gate() {
    std::uint8_t* callsite = nullptr;
    std::uint8_t* relay = nullptr;
    std::int32_t displacement = 0;
    if (!prepare_plain_callsite_relay(
            kHudDrawInteractableRecordCallsiteRva,
            kFhudPublishInteractRecordRva,
            reinterpret_cast<const void*>(
                &hooked_hud_draw_interactable_record),
            callsite, relay, displacement)) {
        boot_log_line(
            "hud-draw-interactable primary-screen gate SKIPPED (preflight)");
        return false;
    }
    SuspendedProcessThreads suspended_threads{};
    if (!suspend_other_process_threads(suspended_threads)) {
        VirtualFree(relay, 0, MEM_RELEASE);
        boot_log_line(
            "hud-draw-interactable primary-screen gate SKIPPED (thread suspend)");
        return false;
    }
    DWORD old = 0;
    if (!VirtualProtect(callsite, 5, PAGE_EXECUTE_READWRITE, &old)) {
        resume_suspended_process_threads(suspended_threads);
        VirtualFree(relay, 0, MEM_RELEASE);
        boot_log_line(
            "hud-draw-interactable primary-screen gate SKIPPED (protect)");
        return false;
    }
    g_original_hud_draw_interactable_record =
        reinterpret_cast<FhudPublishInteractRecordFunction>(
            g_module + kFhudPublishInteractRecordRva);
    std::memcpy(callsite + 1, &displacement, sizeof(displacement));
    FlushInstructionCache(GetCurrentProcess(), callsite, 5);
    DWORD ignored = 0;
    VirtualProtect(callsite, 5, old, &ignored);
    resume_suspended_process_threads(suspended_threads);
    boot_log_line(
        "hud-draw-interactable fallback primary-screen gate installed");
    return true;
}

struct WeaponInteractWorldContext {
    bool active{false};
    bool source_killed{false};
    bool drop_captured{false};
    void* source{nullptr};
    std::uint32_t source_stable_id{0};
    std::uint32_t picked_art{0};
    std::uint32_t dropped_art{0};
    std::uint8_t dropped_payload[
        coop::kDroppedPickupEventPayloadBytes]{};
};

WeaponInteractWorldContext g_weapon_interact_world_context{};
std::atomic<DWORD> g_weapon_interact_owner_thread{0};

using WeaponInteractOnInteractFunction =
    void(__fastcall*)(void*, void*, void*, void*);
using ProcessKillTreeFunction = void(__fastcall*)(void*);
using ProcessWeaponDetachFunction = std::int64_t(__fastcall*)(
    void*, float, void*, void*, char, char);

WeaponInteractOnInteractFunction g_original_weapon_interact_on_interact = nullptr;
ProcessKillTreeFunction g_original_process_kill_tree_for_weapon_interact = nullptr;
ProcessWeaponDetachFunction g_original_process_weapon_detach = nullptr;

bool seh_capture_detached_weapon_world_payload(
    void* weapon, void* source, std::uint32_t& art,
    std::uint8_t payload[coop::kDroppedPickupEventPayloadBytes]) {
    art = 0;
    if (weapon == nullptr || weapon == source ||
        readable_bytes(weapon) < 0x864) {
        return false;
    }
    __try {
        const auto* bytes = static_cast<const std::byte*>(weapon);
        art = *reinterpret_cast<const std::uint32_t*>(bytes + 0x860);
        const std::uint8_t flags =
            *reinterpret_cast<const std::uint8_t*>(bytes + 0x690);
        return art != 0 && (flags & 0x08) != 0 &&
            seh_build_dropped_pickup_event_payload(weapon, payload);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        art = 0;
        return false;
    }
}

bool seh_read_weapon_interact_source(
    void* control, void* source, std::uint32_t& stable_id,
    std::uint32_t& art) {
    stable_id = 0;
    art = 0;
    if (control == nullptr || source == nullptr ||
        readable_bytes(source) < 0x864) {
        return false;
    }
    __try {
        if (*reinterpret_cast<const std::uintptr_t*>(control) !=
            g_module + kWeaponInteractControlVftableRva) {
            return false;
        }
        const auto* bytes = static_cast<const std::byte*>(source);
        stable_id =
            *reinterpret_cast<const std::uint32_t*>(bytes + 0xD8);
        art = *reinterpret_cast<const std::uint32_t*>(bytes + 0x860);
        return stable_id != 0 && art != 0;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        stable_id = 0;
        art = 0;
        return false;
    }
}

void __fastcall hooked_process_kill_tree_for_weapon_interact(void* process) {
    const DWORD thread_id = GetCurrentThreadId();
    auto& context = g_weapon_interact_world_context;
    if (g_weapon_interact_owner_thread.load(std::memory_order_acquire) ==
            thread_id &&
        context.active && process == context.source) {
        context.source_killed = true;
        std::ostringstream line;
        line << "WORLD-WEAPON-SOURCE-COMMIT stable=0x" << std::hex
             << context.source_stable_id << " art=0x" << context.picked_art
             << std::dec;
        boot_log_line(line.str().c_str());
    }
    if (g_original_process_kill_tree_for_weapon_interact != nullptr) {
        g_original_process_kill_tree_for_weapon_interact(process);
    }
}

std::int64_t __fastcall hooked_process_weapon_detach(
    void* weapon, float scalar, void* translation, void* rotation,
    char a5, char a6) {
    const DWORD thread_id = GetCurrentThreadId();
    auto& context = g_weapon_interact_world_context;
    const bool transaction_owned =
        g_weapon_interact_owner_thread.load(std::memory_order_acquire) ==
            thread_id &&
        context.active && weapon != nullptr && weapon != context.source;
    if (transaction_owned) {
        static std::atomic<int> entered{0};
        if (entered.fetch_add(1, std::memory_order_relaxed) < 16) {
            boot_log_line("WORLD-WEAPON-DROP-ENTER exact GiveWeapon callsite");
        }
    }
    const std::int64_t result = g_original_process_weapon_detach != nullptr
        ? g_original_process_weapon_detach(
              weapon, scalar, translation, rotation, a5, a6)
        : 0;
    if (!transaction_owned) {
        return result;
    }
    std::uint32_t art = 0;
    if (seh_capture_detached_weapon_world_payload(
            weapon, context.source, art, context.dropped_payload)) {
        context.dropped_art = art;
        context.drop_captured = true;
        std::ostringstream line;
        line << "WORLD-WEAPON-DROP-COMMIT art=0x" << std::hex << art
             << " weapon=0x" << reinterpret_cast<std::uintptr_t>(weapon)
             << std::dec;
        boot_log_line(line.str().c_str());
    }
    return result;
}

void __fastcall hooked_weapon_interact_on_interact(
    void* control, void* source, void* player, void* a4) {
    void* const retained_local = retained_player_object(0);
    void* const resolved_local = resolve_live_player_safe(0);
    void* const puppet = retained_player_object(1);
    bool admitted = source != nullptr && player != nullptr && player != puppet &&
        (player == retained_local || player == resolved_local) &&
        g_pickup_relay && g_state_net.enabled && g_state_net.peer_set;
    std::uint32_t source_stable_id = 0;
    std::uint32_t picked_art = 0;
    if (admitted) {
        admitted = seh_read_weapon_interact_source(
            control, source, source_stable_id, picked_art);
    }
    const DWORD thread_id = GetCurrentThreadId();
    if (admitted) {
        DWORD no_owner = 0;
        admitted = g_weapon_interact_owner_thread.compare_exchange_strong(
            no_owner, thread_id, std::memory_order_acq_rel,
            std::memory_order_acquire);
    }
    if (admitted) {
        g_weapon_interact_world_context = {};
        g_weapon_interact_world_context.active = true;
        g_weapon_interact_world_context.source = source;
        g_weapon_interact_world_context.source_stable_id = source_stable_id;
        g_weapon_interact_world_context.picked_art = picked_art;
        std::ostringstream line;
        line << "WORLD-WEAPON-INTERACT stable=0x" << std::hex
             << source_stable_id << " art=0x" << picked_art
             << " source=0x" << reinterpret_cast<std::uintptr_t>(source)
             << std::dec;
        boot_log_line(line.str().c_str());
    }
    if (g_original_weapon_interact_on_interact != nullptr) {
        g_original_weapon_interact_on_interact(control, source, player, a4);
    }
    if (!admitted) return;

    const WeaponInteractWorldContext completed =
        g_weapon_interact_world_context;
    g_weapon_interact_world_context = {};
    g_weapon_interact_owner_thread.store(0, std::memory_order_release);
    if (!completed.source_killed) {
        boot_log_line(
            "WORLD-WEAPON-REJECT interaction returned without source kill");
        return;
    }
    coop::WeaponWorldPacket packet{};
    packet.sequence = g_weapon_world_send_seq.fetch_add(1) + 1;
    packet.flags = coop::kWeaponGiveWorldConsume;
    packet.picked_weapon_art_id = completed.picked_art;
    packet.consumed_pickup_stable_id = completed.source_stable_id;
    if (completed.drop_captured) {
        packet.flags |= coop::kWeaponGiveWorldDrop;
        packet.dropped_weapon_art_id = completed.dropped_art;
        std::memcpy(packet.dropped_pickup_event_payload,
                    completed.dropped_payload,
                    sizeof(packet.dropped_pickup_event_payload));
    }
    const int sent = sendto(
        g_state_net.send_socket, reinterpret_cast<const char*>(&packet),
        sizeof(packet), 0,
        reinterpret_cast<const sockaddr*>(&g_state_net.peer_addr),
        sizeof(g_state_net.peer_addr));
    std::ostringstream line;
    line << "WORLD-WEAPON-SEND seq=" << packet.sequence
         << " picked=0x" << std::hex << packet.picked_weapon_art_id
         << " consume=0x" << packet.consumed_pickup_stable_id
         << " dropped=0x" << packet.dropped_weapon_art_id
         << " flags=0x" << packet.flags << std::dec
         << " boundary=WeaponInteractControl bytes=" << sent;
    boot_log_line(line.str().c_str());
}

bool install_weapon_interact_world_lifecycle() {
    auto* const on_interact_slot = reinterpret_cast<void**>(
        g_module + kWeaponInteractOnInteractVtableSlotRva);
    void* const expected_on_interact = reinterpret_cast<void*>(
        g_module + kWeaponInteractOnInteractRva);
    if (*on_interact_slot != expected_on_interact) {
        boot_log_line(
            "WeaponInteractControl lifecycle SKIPPED (vtable mismatch)");
        return false;
    }
    std::uint8_t* detach_callsite = nullptr;
    std::uint8_t* detach_relay = nullptr;
    std::int32_t detach_displacement = 0;
    std::uint8_t* kill_callsite = nullptr;
    std::uint8_t* kill_relay = nullptr;
    std::int32_t kill_displacement = 0;
    if (!prepare_plain_callsite_relay(
            kPickupReplacementDetachCallsiteRva,
            kProcessWeaponDetachRva,
            reinterpret_cast<const void*>(&hooked_process_weapon_detach),
            detach_callsite, detach_relay, detach_displacement) ||
        !prepare_plain_callsite_relay(
            kWeaponInteractSourceKillCallsiteRva,
            kProcessKillTreeRva,
            reinterpret_cast<const void*>(
                &hooked_process_kill_tree_for_weapon_interact),
            kill_callsite, kill_relay, kill_displacement)) {
        if (detach_relay != nullptr) {
            VirtualFree(detach_relay, 0, MEM_RELEASE);
        }
        if (kill_relay != nullptr) {
            VirtualFree(kill_relay, 0, MEM_RELEASE);
        }
        boot_log_line(
            "WeaponInteractControl lifecycle SKIPPED (callsite preflight)");
        return false;
    }
    SuspendedProcessThreads suspended_threads{};
    if (!suspend_other_process_threads(suspended_threads)) {
        VirtualFree(detach_relay, 0, MEM_RELEASE);
        VirtualFree(kill_relay, 0, MEM_RELEASE);
        boot_log_line(
            "WeaponInteractControl lifecycle SKIPPED (thread suspend)");
        return false;
    }
    DWORD detach_old = 0;
    DWORD kill_old = 0;
    DWORD on_interact_old = 0;
    const bool detach_protected = VirtualProtect(
        detach_callsite, 5, PAGE_EXECUTE_READWRITE, &detach_old) != 0;
    const bool kill_protected = VirtualProtect(
        kill_callsite, 5, PAGE_EXECUTE_READWRITE, &kill_old) != 0;
    const bool on_interact_protected = VirtualProtect(
        on_interact_slot, sizeof(void*), PAGE_READWRITE,
        &on_interact_old) != 0;
    if (!detach_protected || !kill_protected || !on_interact_protected) {
        DWORD ignored = 0;
        if (detach_protected) {
            VirtualProtect(detach_callsite, 5, detach_old, &ignored);
        }
        if (kill_protected) {
            VirtualProtect(kill_callsite, 5, kill_old, &ignored);
        }
        if (on_interact_protected) {
            VirtualProtect(
                on_interact_slot, sizeof(void*), on_interact_old, &ignored);
        }
        resume_suspended_process_threads(suspended_threads);
        VirtualFree(detach_relay, 0, MEM_RELEASE);
        VirtualFree(kill_relay, 0, MEM_RELEASE);
        boot_log_line(
            "WeaponInteractControl lifecycle SKIPPED (protect)");
        return false;
    }
    g_original_process_weapon_detach =
        reinterpret_cast<ProcessWeaponDetachFunction>(
            g_module + kProcessWeaponDetachRva);
    g_original_process_kill_tree_for_weapon_interact =
        reinterpret_cast<ProcessKillTreeFunction>(
            g_module + kProcessKillTreeRva);
    g_original_weapon_interact_on_interact =
        reinterpret_cast<WeaponInteractOnInteractFunction>(
            expected_on_interact);
    *on_interact_slot =
        reinterpret_cast<void*>(&hooked_weapon_interact_on_interact);
    std::memcpy(detach_callsite + 1, &detach_displacement,
                sizeof(detach_displacement));
    std::memcpy(kill_callsite + 1, &kill_displacement,
                sizeof(kill_displacement));
    FlushInstructionCache(GetCurrentProcess(), detach_callsite, 5);
    FlushInstructionCache(GetCurrentProcess(), kill_callsite, 5);
    DWORD ignored = 0;
    VirtualProtect(detach_callsite, 5, detach_old, &ignored);
    VirtualProtect(kill_callsite, 5, kill_old, &ignored);
    VirtualProtect(
        on_interact_slot, sizeof(void*), on_interact_old, &ignored);
    resume_suspended_process_threads(suspended_threads);
    const bool installed = g_original_process_weapon_detach != nullptr &&
        g_original_process_kill_tree_for_weapon_interact != nullptr &&
        g_original_weapon_interact_on_interact != nullptr;
    boot_log_line(installed
        ? "WeaponInteractControl vtable-scoped exact-callsite relay installed"
        : "WeaponInteractControl consume/drop lifecycle relay incomplete");
    return installed;
}

