float horizontal_yaw_degrees(float forward_x, float forward_z) {
    return std::atan2(forward_x, forward_z) * (180.0F / 3.14159265F);
}

bool read_aim_additive_lrdu(
    const void* base, std::size_t left_offset, float out[4]) {
    if (base == nullptr || readable_bytes(base) < left_offset + 8) {
        return false;
    }
    const auto* const bytes = static_cast<const std::byte*>(base);
    out[0] = *reinterpret_cast<const float*>(bytes + left_offset);
    out[1] = *reinterpret_cast<const float*>(bytes + left_offset + 4);
    out[2] = *reinterpret_cast<const float*>(bytes + left_offset + 8);
    out[3] = *reinterpret_cast<const float*>(bytes + left_offset + 12);
    return true;
}

void* aim_publish_active_state_from_player(void* player) {
    if (player == nullptr ||
        readable_bytes(player) < kPlayerUpperStateOwnerOffset + sizeof(void*)) {
        return nullptr;
    }
    const auto* const player_bytes = static_cast<const std::byte*>(player);
    void* const hub = *reinterpret_cast<void* const*>(
        player_bytes + kPlayerUpperStateOwnerOffset);
    if (hub == nullptr ||
        readable_bytes(hub) < kPlayerAnimHubChildOffset + sizeof(void*)) {
        return nullptr;
    }
    void* const child = *reinterpret_cast<void* const*>(
        static_cast<const std::byte*>(hub) + kPlayerAnimHubChildOffset);
    if (child == nullptr ||
        readable_bytes(child) < kPlayerAnimActiveStateOffset + sizeof(void*)) {
        return nullptr;
    }
    return *reinterpret_cast<void* const*>(
        static_cast<const std::byte*>(child) + kPlayerAnimActiveStateOffset);
}

bool player_screen_index_is(const void* player, std::uint32_t index) {
    if (player == nullptr ||
        readable_bytes(static_cast<const std::byte*>(player) + 0x4010) <
            sizeof(std::uint32_t)) {
        return false;
    }
    return *reinterpret_cast<const std::uint32_t*>(
               static_cast<const std::byte*>(player) + 0x4010) == index;
}

bool read_aim_named_channel_mode(
    void* controller, void* owner, bool& uses_named_channels,
    std::uint8_t* branch_value = nullptr) {
    uses_named_channels = false;
    if (controller == nullptr || owner == nullptr ||
        g_resolve_aim_base_state == nullptr ||
        readable_bytes(static_cast<std::byte*>(owner) +
                       kPlayerUpperStateOwnerOffset) < sizeof(void*)) {
        return false;
    }
    void* const channel_base = *reinterpret_cast<void**>(
        static_cast<std::byte*>(owner) + kPlayerUpperStateOwnerOffset);
    if (channel_base == nullptr) {
        return false;
    }
    __try {
        void* const resolved = g_resolve_aim_base_state(channel_base, 0);
        if (resolved == nullptr ||
            readable_bytes(static_cast<std::byte*>(resolved) + 0x40) < 1) {
            return false;
        }
        auto* const branch_ctl = *reinterpret_cast<std::uint8_t**>(
            static_cast<std::byte*>(resolved) + 0x38);
        if (branch_ctl == nullptr || readable_bytes(branch_ctl) < 1) {
            return false;
        }
        const std::uint8_t value = branch_ctl[0];
        uses_named_channels = value == 0;
        if (branch_value != nullptr) {
            *branch_value = value;
        }
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

