bool install_native_aim_foot_turn_relays() {
    std::uint8_t* writer_site = nullptr;
    std::uint8_t* writer_relay = nullptr;
    std::int32_t writer_displacement = 0;
    std::uint8_t* selector_site = nullptr;
    std::uint8_t* selector_relay = nullptr;
    std::int32_t selector_displacement = 0;
    if (!prepare_plain_callsite_relay(
            kGunMoveUpdateTurnYawCallsiteRva,
            kGunMoveUpdateTurnYawRva,
            reinterpret_cast<const void*>(
                &hooked_update_turn_yaw_from_direction),
            writer_site, writer_relay, writer_displacement) ||
        !prepare_plain_callsite_relay(
            kGunMoveSelectAimIdleTurnCallsiteRva,
            kGunMoveSelectAimIdleTurnRva,
            reinterpret_cast<const void*>(
                &hooked_select_aim_idle_turn_state),
            selector_site, selector_relay, selector_displacement)) {
        if (writer_relay != nullptr) {
            VirtualFree(writer_relay, 0, MEM_RELEASE);
        }
        if (selector_relay != nullptr) {
            VirtualFree(selector_relay, 0, MEM_RELEASE);
        }
        boot_log_line("native aim-foot relay SKIPPED (pair preflight)");
        return false;
    }
    g_update_turn_yaw_from_direction =
        reinterpret_cast<UpdateTurnYawFromDirectionFunction>(
            g_module + kGunMoveUpdateTurnYawRva);
    g_select_aim_idle_turn_state =
        reinterpret_cast<SelectAimIdleTurnStateFunction>(
            g_module + kGunMoveSelectAimIdleTurnRva);
    DWORD old = 0;
    const std::size_t patch_span =
        static_cast<std::size_t>(selector_site + 5 - writer_site);
    if (!VirtualProtect(
            writer_site, patch_span, PAGE_EXECUTE_READWRITE, &old)) {
        VirtualFree(writer_relay, 0, MEM_RELEASE);
        VirtualFree(selector_relay, 0, MEM_RELEASE);
        boot_log_line("native aim-foot relay SKIPPED (protect)");
        return false;
    }
    *reinterpret_cast<std::int32_t*>(writer_site + 1) = writer_displacement;
    *reinterpret_cast<std::int32_t*>(selector_site + 1) = selector_displacement;
    FlushInstructionCache(GetCurrentProcess(), writer_site, patch_span);
    DWORD ignored = 0;
    VirtualProtect(writer_site, patch_span, old, &ignored);
    boot_log_line("native aim-foot relays installed (0x140E90605/0x140E9060F)");
    return true;
}

void* player_fganim_from_player(void* player) {
    if (player == nullptr ||
        readable_bytes(player) < kPlayerFgAnimDataOffset + sizeof(void*)) {
        return nullptr;
    }
    return *reinterpret_cast<void* const*>(
        static_cast<const std::byte*>(player) + kPlayerFgAnimDataOffset);
}

bool read_fganim_buffer_ptrs(
    void* object, const void** palette, const void** skinning) {
    if (palette != nullptr) {
        *palette = nullptr;
    }
    if (skinning != nullptr) {
        *skinning = nullptr;
    }
    if (object == nullptr ||
        readable_bytes(object) <
            kFgAnimDataCurrentSkinningMatsOffset + sizeof(void*)) {
        return false;
    }
    const auto* const bytes = static_cast<const std::byte*>(object);
    if (palette != nullptr) {
        *palette = *reinterpret_cast<const void* const*>(
            bytes + kFgAnimDataRuntimePayloadOffset);
    }
    if (skinning != nullptr) {
        *skinning = *reinterpret_cast<const void* const*>(
            bytes + kFgAnimDataCurrentSkinningMatsOffset);
    }
    return true;
}

bool pointer_looks_like_heap(const void* ptr) {
    const auto value = reinterpret_cast<std::uintptr_t>(ptr);
    // Reject float bit-patterns and SkelTable inline fields (e.g. 0x760000).
    if (value < 0x10000ULL || value >= 0x00007FFFFFFFFFFFULL) {
        return false;
    }
    MEMORY_BASIC_INFORMATION mbi{};
    if (VirtualQuery(ptr, &mbi, sizeof(mbi)) == 0) {
        return false;
    }
    if (mbi.State != MEM_COMMIT) {
        return false;
    }
    if ((mbi.Protect & (PAGE_NOACCESS | PAGE_GUARD)) != 0) {
        return false;
    }
    return readable_bytes(ptr) >= 0x10;
}

struct PuppetAllocatedSkinningBuffer {
    void* memory = nullptr;
    std::size_t bytes = 0;
};

std::unordered_map<void*, PuppetAllocatedSkinningBuffer> g_puppet_skinning_allocs;

struct PuppetAllocatedPaletteBuffer {
    void* memory = nullptr;
    std::size_t bytes = 0;
};

std::unordered_map<void*, PuppetAllocatedPaletteBuffer> g_puppet_palette_allocs;

bool ensure_fganim_palette_buffer(void* fg, std::size_t buffer_bytes) {
    if (fg == nullptr || buffer_bytes == 0 ||
        readable_bytes(fg) < kFgAnimDataRuntimePayloadOffset + sizeof(void*)) {
        return false;
    }
    void* const current = *reinterpret_cast<void* const*>(
        static_cast<const std::byte*>(fg) + kFgAnimDataRuntimePayloadOffset);
    if (pointer_looks_like_heap(current) &&
        readable_bytes(current) >= buffer_bytes) {
        return true;
    }
    auto& slot = g_puppet_palette_allocs[fg];
    if (slot.memory == nullptr || slot.bytes < buffer_bytes) {
        if (slot.memory != nullptr) {
            VirtualFree(slot.memory, 0, MEM_RELEASE);
            slot.memory = nullptr;
            slot.bytes = 0;
        }
        slot.memory = VirtualAlloc(
            nullptr, buffer_bytes, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
        slot.bytes = buffer_bytes;
    }
    if (slot.memory == nullptr) {
        return false;
    }
    *reinterpret_cast<void**>(
        static_cast<std::byte*>(fg) + kFgAnimDataRuntimePayloadOffset) =
        slot.memory;
    return true;
}

bool ensure_fganim_skinning_buffer(
    void* fg, void* current_skinning, std::size_t buffer_bytes) {
    if (fg == nullptr || buffer_bytes == 0) {
        return false;
    }
    if (pointer_looks_like_heap(current_skinning) &&
        readable_bytes(current_skinning) >= buffer_bytes) {
        return true;
    }
    auto& slot = g_puppet_skinning_allocs[fg];
    if (slot.memory == nullptr || slot.bytes < buffer_bytes) {
        if (slot.memory != nullptr) {
            VirtualFree(slot.memory, 0, MEM_RELEASE);
            slot.memory = nullptr;
            slot.bytes = 0;
        }
        slot.memory = VirtualAlloc(
            nullptr, buffer_bytes, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
        slot.bytes = buffer_bytes;
        if (slot.memory != nullptr) {
            static ULONGLONG last_log = 0;
            const ULONGLONG now = GetTickCount64();
            if (now - last_log >= 1000) {
                last_log = now;
                std::ostringstream line;
                line << "AIM-FGANIM-SKIN-ALLOC fg=0x" << std::hex
                     << reinterpret_cast<std::uintptr_t>(fg) << " buf=0x"
                     << reinterpret_cast<std::uintptr_t>(slot.memory) << std::dec
                     << " bytes=" << buffer_bytes;
                force_log_line(line.str().c_str());
            }
        }
    }
    if (slot.memory == nullptr) {
        return false;
    }
    if (readable_bytes(fg) <
        kFgAnimDataCurrentSkinningMatsOffset + sizeof(void*)) {
        return false;
    }
    *reinterpret_cast<void**>(
        static_cast<std::byte*>(fg) + kFgAnimDataCurrentSkinningMatsOffset) =
        slot.memory;
    return true;
}

bool write_fganim_aim_add_lrdu(void* fg, float left, float right, float up, float down) {
    if (fg == nullptr ||
        readable_bytes(fg) < kAnimStateAimAddRightOffset + sizeof(float)) {
        return false;
    }
    auto* const fg_bytes = static_cast<std::byte*>(fg);
    *reinterpret_cast<float*>(fg_bytes + kAnimStateAimAddDownOffset) = down;
    *reinterpret_cast<float*>(fg_bytes + kAnimStateAimAddUpOffset) = up;
    *reinterpret_cast<float*>(fg_bytes + kAnimStateAimAddLeftOffset) = left;
    *reinterpret_cast<float*>(fg_bytes + kAnimStateAimAddRightOffset) = right;
    return true;
}

bool mirror_puppet_aim_add_to_fganim(void* player) {
    if (!g_enable_puppet_fganim_aim_add_mirror || player == nullptr) {
        return false;
    }
    void* const fg = player_fganim_from_player(player);
    if (fg == nullptr) {
        return false;
    }
    constexpr std::size_t kAimAddSpan =
        kAnimStateAimAddRightOffset + sizeof(float) - kAnimStateAimAddDownOffset;
    if (readable_bytes(fg) < kAnimStateAimAddDownOffset + kAimAddSpan) {
        return false;
    }

    float before[4]{};
    read_aim_additive_lrdu(fg, kAnimStateAimAddDownOffset, before);

    float left = 0.0F;
    float right = 0.0F;
    float up = 0.0F;
    float down = 0.0F;
    bool have_source = false;
    if (void* const aim = player_aim_controller_from_player(player);
        aim != nullptr && readable_bytes(aim) >= 0x8F0) {
        const auto* const aim_bytes = static_cast<const std::byte*>(aim);
        left = *reinterpret_cast<const float*>(aim_bytes + 0x8B8);
        right = *reinterpret_cast<const float*>(aim_bytes + 0x8BC);
        up = *reinterpret_cast<const float*>(aim_bytes + 0x8C0);
        down = *reinterpret_cast<const float*>(aim_bytes + 0x8C4);
        const float blend = std::clamp(
            *reinterpret_cast<const float*>(aim_bytes + 0x8EC), 0.0F, 1.0F);
        have_source = std::isfinite(left) && std::isfinite(right) &&
                      std::isfinite(up) && std::isfinite(down) &&
                      std::isfinite(blend);
        if (have_source) {
            // PublishDirectionalAimWeights applies this exact ADS blend before
            // publishing Aim0..Aim7. Mirroring raw controller weights bypassed
            // authored easing and exposed a saturated pose on ADS entry.
            left *= blend;
            right *= blend;
            up *= blend;
            down *= blend;
        }
    }
    void* const publish_state = aim_publish_active_state_from_player(player);
    if (!have_source && publish_state != nullptr && publish_state != fg &&
        readable_bytes(publish_state) >= kAnimStateAimAddDownOffset + kAimAddSpan) {
        float pub_raw[4]{};
        if (read_aim_additive_lrdu(publish_state, kAnimStateAimAddDownOffset, pub_raw)) {
            down = pub_raw[0];
            up = pub_raw[1];
            left = pub_raw[2];
            right = pub_raw[3];
            const float pub_sum = std::fabs(left) + std::fabs(right) +
                                  std::fabs(up) + std::fabs(down);
            have_source = pub_sum >= 0.01F;
        }
    }
    if (!have_source) {
        return false;
    }
    if (!write_fganim_aim_add_lrdu(fg, left, right, up, down)) {
        return false;
    }

    float after[4]{};
    read_aim_additive_lrdu(fg, kAnimStateAimAddDownOffset, after);
    const float delta = std::fabs(before[0] - after[0]) +
                        std::fabs(before[1] - after[1]) +
                        std::fabs(before[2] - after[2]) +
                        std::fabs(before[3] - after[3]);
    if (delta < 0.001F) {
        return false;
    }
    static ULONGLONG last_log = 0;
    const ULONGLONG now = GetTickCount64();
    if (now - last_log >= 400) {
        last_log = now;
        std::ostringstream line;
        line << "AIM-FGANIM-MIRROR fgBefore=(" << before[2] << "," << before[3]
             << "," << before[0] << "," << before[1] << ") fgAfter=("
             << after[2] << "," << after[3] << "," << after[0] << ","
             << after[1] << ") src=(" << left << "," << right << "," << up
             << "," << down << ") pubObj=0x" << std::hex
             << reinterpret_cast<std::uintptr_t>(publish_state) << " fg=0x"
             << reinterpret_cast<std::uintptr_t>(fg) << std::dec;
        force_log_line(line.str().c_str());
    }
    return true;
}

void clear_puppet_fganim_aim_add(void* player) {
    if (!g_enable_puppet_fganim_aim_add_mirror || player == nullptr) {
        return;
    }
    if (void* const fg = player_fganim_from_player(player); fg != nullptr) {
        write_fganim_aim_add_lrdu(fg, 0.0F, 0.0F, 0.0F, 0.0F);
    }
}

void log_puppet_aim_render_discriminator(
    void* puppet, const coop::StatePacket& peer) {
    if (!peer_packet_aim_active(peer) || puppet == nullptr) {
        return;
    }
    static ULONGLONG last_log = 0;
    static float last_peer_yaw = 0.0F;
    const ULONGLONG now = GetTickCount64();
    if (now - last_log < 400) {
        return;
    }

    float peer_fx = 0.0F;
    float peer_fy = 0.0F;
    float peer_fz = 0.0F;
    quat_forward_pos_z(peer.pose_seed + 4, peer_fx, peer_fy, peer_fz);
    const float peer_yaw = horizontal_yaw_degrees(peer_fx, peer_fz);
    if (last_log != 0 && std::fabs(peer_yaw - last_peer_yaw) < 2.0F) {
        return;
    }
    last_log = now;
    last_peer_yaw = peer_yaw;

    float root_fx = 0.0F;
    float root_fy = 0.0F;
    float root_fz = 0.0F;
    float root_yaw = 0.0F;
    if (readable_bytes(static_cast<std::byte*>(puppet) + kPlayerQuatOffset) >=
        16) {
        const float* const root_quat = reinterpret_cast<const float*>(
            static_cast<const std::byte*>(puppet) + kPlayerQuatOffset);
        quat_forward_pos_z(root_quat, root_fx, root_fy, root_fz);
        root_yaw = horizontal_yaw_degrees(root_fx, root_fz);
    }

    float ctrl_weights[4]{};
    float ctrl_blend = 0.0F;
    if (void* const aim = player_aim_controller_from_player(puppet);
        aim != nullptr && readable_bytes(aim) >= 0x8F0) {
        const auto* const aim_bytes = static_cast<const std::byte*>(aim);
        std::memcpy(ctrl_weights, aim_bytes + 0x8B8, sizeof(ctrl_weights));
        ctrl_blend = *reinterpret_cast<const float*>(aim_bytes + 0x8EC);
    }
    const float ctrl_sum = std::fabs(ctrl_weights[0]) + std::fabs(ctrl_weights[1]) +
                           std::fabs(ctrl_weights[2]) + std::fabs(ctrl_weights[3]);
    if (ctrl_sum < 0.01F && ctrl_blend < 0.5F) {
        return;
    }

    float fg_weights[4]{};
    float pub_weights[4]{};
    void* const fg = readable_bytes(
        static_cast<std::byte*>(puppet) + kPlayerFgAnimDataOffset) >= sizeof(void*)
        ? *reinterpret_cast<void* const*>(
              static_cast<const std::byte*>(puppet) + kPlayerFgAnimDataOffset)
        : nullptr;
    if (fg != nullptr) {
        float raw[4]{};
        if (read_aim_additive_lrdu(
                fg, kAnimStateAimAddDownOffset, raw)) {
            fg_weights[0] = raw[2];
            fg_weights[1] = raw[3];
            fg_weights[2] = raw[0];
            fg_weights[3] = raw[1];
        }
    }
    void* const publish_state = aim_publish_active_state_from_player(puppet);
    if (publish_state != nullptr) {
        float raw[4]{};
        if (read_aim_additive_lrdu(
                publish_state, kAnimStateAimAddDownOffset, raw)) {
            pub_weights[0] = raw[2];
            pub_weights[1] = raw[3];
            pub_weights[2] = raw[0];
            pub_weights[3] = raw[1];
        }
    }

    std::ostringstream line;
    line << "AIM-RENDER-DISC peerFwd=(" << peer_fx << "," << peer_fz
         << ") rootFwd=(" << root_fx << "," << root_fz << ") peerYaw="
         << peer_yaw << " rootYaw=" << root_yaw
         << " yawDelta=" << (peer_yaw - root_yaw)
         << " ctrlAdd=(" << ctrl_weights[0] << "," << ctrl_weights[1] << ","
         << ctrl_weights[2] << "," << ctrl_weights[3] << ") blend="
         << ctrl_blend << " fgAdd=(" << fg_weights[0] << "," << fg_weights[1]
         << "," << fg_weights[2] << "," << fg_weights[3] << ") pubAdd=("
         << pub_weights[0] << "," << pub_weights[1] << "," << pub_weights[2]
         << "," << pub_weights[3] << ") pubState=0x" << std::hex
         << reinterpret_cast<std::uintptr_t>(publish_state) << " fg=0x"
         << reinterpret_cast<std::uintptr_t>(fg) << std::dec
         << " samePtr=" << ((publish_state == fg) ? 1 : 0) << " seq="
         << peer.sequence;
    force_log_line(line.str().c_str());
}

struct FgAnimJointBuffers {
    void* object = nullptr;
    void* skeleton = nullptr;
    const float* palette = nullptr;
    const float* skinning = nullptr;
    std::uint32_t joint_count = 0;
};

bool resolve_fganim_joint_buffers(
    void* object, FgAnimJointBuffers& out, const char** fail_stage) {
    out = {};
    if (object == nullptr) {
        if (fail_stage != nullptr) {
            *fail_stage = "null-object";
        }
        return false;
    }
    if (readable_bytes(object) <
        kFgAnimDataPreviousSkinningMatsOffset + sizeof(void*)) {
        if (fail_stage != nullptr) {
            *fail_stage = "object-span";
        }
        return false;
    }
    auto* const bytes = static_cast<const std::byte*>(object);
    out.object = object;
    out.skeleton = *reinterpret_cast<void* const*>(bytes + kFgAnimDataSkeletonOffset);
    out.palette = *reinterpret_cast<const float* const*>(
        bytes + kFgAnimDataRuntimePayloadOffset);
    out.skinning = *reinterpret_cast<const float* const*>(
        bytes + kFgAnimDataCurrentSkinningMatsOffset);
    if (out.skeleton == nullptr ||
        readable_bytes(out.skeleton) < kSkeletonJointCountOffset + sizeof(std::uint32_t)) {
        if (fail_stage != nullptr) {
            *fail_stage = "skeleton";
        }
        return false;
    }
    out.joint_count = *reinterpret_cast<const std::uint32_t*>(
        static_cast<const std::byte*>(out.skeleton) + kSkeletonJointCountOffset);
    if (out.joint_count == 0 || out.joint_count > 1024) {
        if (fail_stage != nullptr) {
            *fail_stage = "joint-count";
        }
        return false;
    }
    return true;
}

float joint_matrix_delta(
    const float* a, const float* b, std::uint32_t joint_count, std::uint32_t joint) {
    constexpr std::size_t kJointFloatCount = 12;
    constexpr std::size_t kJointStride = kJointFloatCount * sizeof(float);
    const std::size_t palette_bytes =
        static_cast<std::size_t>(joint_count) * kJointStride;
    if (a == nullptr || b == nullptr || joint >= joint_count ||
        readable_bytes(a) < palette_bytes || readable_bytes(b) < palette_bytes) {
        return 0.0F;
    }
    const std::size_t base = static_cast<std::size_t>(joint) * kJointFloatCount;
    float sum_sq = 0.0F;
    for (std::size_t component = 0; component < kJointFloatCount; ++component) {
        const float lhs = a[base + component];
        const float rhs = b[base + component];
        if (!std::isfinite(lhs) || !std::isfinite(rhs)) {
            return 0.0F;
        }
        const float delta = lhs - rhs;
        sum_sq += delta * delta;
    }
    return std::sqrt(sum_sq);
}

bool sync_puppet_fganim_palette_to_skinning(void* player) {
    if (!g_enable_puppet_fganim_palette_to_skinning || player == nullptr) {
        return false;
    }
    void* const fg = player_fganim_from_player(player);
    FgAnimJointBuffers buffers{};
    const char* stage = "ok";
    if (!resolve_fganim_joint_buffers(fg, buffers, &stage)) {
        return false;
    }
    if (!pointer_looks_like_heap(buffers.palette) || buffers.joint_count == 0) {
        return false;
    }
    constexpr std::size_t kJointFloatCount = 12;
    const std::size_t buffer_bytes =
        static_cast<std::size_t>(buffers.joint_count) * kJointFloatCount *
        sizeof(float);
    if (readable_bytes(buffers.palette) < buffer_bytes) {
        return false;
    }
    if (!ensure_fganim_skinning_buffer(
            fg, const_cast<void*>(static_cast<const void*>(buffers.skinning)),
            buffer_bytes)) {
        return false;
    }
    FgAnimJointBuffers refreshed{};
    const char* refresh_stage = "ok";
    if (!resolve_fganim_joint_buffers(fg, refreshed, &refresh_stage) ||
        !pointer_looks_like_heap(refreshed.skinning) ||
        readable_bytes(refreshed.skinning) < buffer_bytes) {
        return false;
    }
    buffers.skinning = refreshed.skinning;
    std::memcpy(
        const_cast<float*>(buffers.skinning), buffers.palette, buffer_bytes);
    static ULONGLONG last_log = 0;
    const ULONGLONG now = GetTickCount64();
    if (now - last_log >= 1000) {
        last_log = now;
        std::ostringstream line;
        line << "AIM-FGANIM-SKIN-COPY joints=" << buffers.joint_count
             << " pal=0x" << std::hex
             << reinterpret_cast<std::uintptr_t>(buffers.palette) << " skin=0x"
             << reinterpret_cast<std::uintptr_t>(buffers.skinning) << std::dec
             << " bytes=" << buffer_bytes;
        force_log_line(line.str().c_str());
    }
    return true;
}

struct SkelOwnerAllocatedBuffer {
    void* memory = nullptr;
    std::size_t bytes = 0;
};

std::unordered_map<std::uint64_t, SkelOwnerAllocatedBuffer>
    g_skel_owner_buffer_allocs;

std::uint64_t skel_owner_buffer_alloc_key(
    void* owner, std::size_t ptr_field_offset) {
    return (reinterpret_cast<std::uint64_t>(owner) << 16) ^
           static_cast<std::uint64_t>(ptr_field_offset);
}

bool ensure_owner_ptr_buffer(
    void* owner, std::size_t ptr_field_offset, std::size_t buffer_bytes) {
    if (owner == nullptr || buffer_bytes == 0 ||
        readable_bytes(owner) < ptr_field_offset + sizeof(void*)) {
        return false;
    }
    void* const current = *reinterpret_cast<void* const*>(
        static_cast<const std::byte*>(owner) + ptr_field_offset);
    if (pointer_looks_like_heap(current) &&
        readable_bytes(current) >= buffer_bytes) {
        return true;
    }
    auto& slot = g_skel_owner_buffer_allocs[skel_owner_buffer_alloc_key(
        owner, ptr_field_offset)];
    if (slot.memory == nullptr || slot.bytes < buffer_bytes) {
        if (slot.memory != nullptr) {
            VirtualFree(slot.memory, 0, MEM_RELEASE);
            slot.memory = nullptr;
            slot.bytes = 0;
        }
        slot.memory = VirtualAlloc(
            nullptr, buffer_bytes, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
        slot.bytes = buffer_bytes;
    }
    if (slot.memory == nullptr) {
        return false;
    }
    *reinterpret_cast<void**>(
        static_cast<std::byte*>(owner) + ptr_field_offset) = slot.memory;
    return true;
}

void log_puppet_skel_inject_skip(void* skel_owner, const char* reason) {
    static ULONGLONG last_log = 0;
    const ULONGLONG now = GetTickCount64();
    if (now - last_log < 400) {
        return;
    }
    last_log = now;
    const void* skel_palette = nullptr;
    const void* skel_skinning = nullptr;
    read_fganim_buffer_ptrs(skel_owner, &skel_palette, &skel_skinning);
    void* skel_global = nullptr;
    if (g_module != 0) {
        skel_global = *reinterpret_cast<void* const*>(
            reinterpret_cast<const std::byte*>(g_module) + kSkelTableGlobalRva);
    }
    std::ostringstream line;
    line << "AIM-SKEL-SKIP reason=" << reason << " owner=0x" << std::hex
         << reinterpret_cast<std::uintptr_t>(skel_owner) << " global=0x"
         << reinterpret_cast<std::uintptr_t>(skel_global) << " skelPal=0x"
         << reinterpret_cast<std::uintptr_t>(skel_palette) << " skelSkin=0x"
         << reinterpret_cast<std::uintptr_t>(skel_skinning) << std::dec
         << " palValid=" << (pointer_looks_like_heap(skel_palette) ? 1 : 0)
         << " skinValid=" << (pointer_looks_like_heap(skel_skinning) ? 1 : 0);
    force_log_line(line.str().c_str());
}

bool copy_palette_to_fganim_object(
    void* object,
    std::size_t ptr_field_offset,
    const void* src_palette,
    std::size_t buffer_bytes) {
    if (object == nullptr || src_palette == nullptr || buffer_bytes == 0) {
        return false;
    }
    if (ptr_field_offset == kFgAnimDataRuntimePayloadOffset) {
        if (!ensure_fganim_palette_buffer(object, buffer_bytes)) {
            return false;
        }
    } else if (ptr_field_offset == kFgAnimDataCurrentSkinningMatsOffset) {
        if (!ensure_fganim_skinning_buffer(object, nullptr, buffer_bytes)) {
            return false;
        }
    } else if (readable_bytes(object) < ptr_field_offset + sizeof(void*)) {
        return false;
    }
    void* const dest = *reinterpret_cast<void* const*>(
        static_cast<const std::byte*>(object) + ptr_field_offset);
    if (!pointer_looks_like_heap(dest) ||
        readable_bytes(dest) < buffer_bytes) {
        return false;
    }
    std::memcpy(dest, src_palette, buffer_bytes);
    return true;
}

bool copy_palette_bytes_to_owner_ptr_field(
    void* owner,
    std::size_t ptr_field_offset,
    const void* src_palette,
    std::size_t buffer_bytes) {
    if (owner == nullptr || src_palette == nullptr || buffer_bytes == 0 ||
        readable_bytes(owner) < ptr_field_offset + sizeof(void*)) {
        return false;
    }
    if (!ensure_owner_ptr_buffer(owner, ptr_field_offset, buffer_bytes)) {
        return false;
    }
    void* const dest = *reinterpret_cast<void* const*>(
        static_cast<const std::byte*>(owner) + ptr_field_offset);
    if (!pointer_looks_like_heap(dest) ||
        readable_bytes(dest) < buffer_bytes) {
        return false;
    }
    std::memcpy(dest, src_palette, buffer_bytes);
    return true;
}

bool puppet_skel_palette_inject_wanted();

void log_puppet_skel_inject_gate_status() {
    static ULONGLONG last_log = 0;
    const ULONGLONG now = GetTickCount64();
    if (now - last_log < 500) {
        return;
    }
    coop::StatePacket peer{};
    if (!copy_peer_state_snapshot(peer) || !peer_packet_aim_active(peer)) {
        return;
    }
    last_log = now;
    void* const puppet = retained_player_object(1);
    const ULONGLONG received =
        g_state_net.peer_state_received_ms.load(std::memory_order_acquire);
    const bool peer_fresh =
        received != 0 && now - received <= 250;
    const bool wanted = puppet_skel_palette_inject_wanted();
    std::ostringstream line;
    line << "AIM-SKEL-GATE wanted=" << (wanted ? 1 : 0)
         << " netApply=" << (g_puppet_net_apply ? 1 : 0)
         << " puppet=0x" << std::hex
         << reinterpret_cast<std::uintptr_t>(puppet) << std::dec
         << " puppetAds=" << (puppet != nullptr && player_ads_active(puppet) ? 1 : 0)
         << " peerFresh=" << (peer_fresh ? 1 : 0)
         << " peerAim=1 seq=" << peer.sequence;
    force_log_line(line.str().c_str());
}

bool sync_puppet_pubstate_palette_from_fganim(void* player) {
    if (player == nullptr) {
        return false;
    }
    FgAnimJointBuffers puppet_buffers{};
    const char* stage = "ok";
    void* const fg = player_fganim_from_player(player);
    if (!resolve_fganim_joint_buffers(fg, puppet_buffers, &stage) ||
        !pointer_looks_like_heap(puppet_buffers.palette) ||
        puppet_buffers.joint_count == 0) {
        return false;
    }
    constexpr std::size_t kJointFloatCount = 12;
    const std::size_t buffer_bytes =
        static_cast<std::size_t>(puppet_buffers.joint_count) * kJointFloatCount *
        sizeof(float);
    if (readable_bytes(puppet_buffers.palette) < buffer_bytes) {
        return false;
    }
    void* const pub_state = aim_publish_active_state_from_player(player);
    if (pub_state == nullptr || pub_state == fg) {
        return false;
    }
    const bool copied_pub_palette = copy_palette_to_fganim_object(
        pub_state, kFgAnimDataRuntimePayloadOffset, puppet_buffers.palette,
        buffer_bytes);
    const bool copied_pub_skinning = copy_palette_to_fganim_object(
        pub_state, kFgAnimDataCurrentSkinningMatsOffset, puppet_buffers.palette,
        buffer_bytes);
    if (!copied_pub_palette && !copied_pub_skinning) {
        return false;
    }
    static ULONGLONG last_log = 0;
    const ULONGLONG now = GetTickCount64();
    if (now - last_log >= 400) {
        last_log = now;
        const void* pub_palette = nullptr;
        const void* pub_skinning = nullptr;
        read_fganim_buffer_ptrs(pub_state, &pub_palette, &pub_skinning);
        std::ostringstream line;
        line << "AIM-PUB-SYNC joints=" << puppet_buffers.joint_count
             << " fgPal=0x" << std::hex
             << reinterpret_cast<std::uintptr_t>(puppet_buffers.palette)
             << " pub=0x"
             << reinterpret_cast<std::uintptr_t>(pub_state) << " pubPal=0x"
             << reinterpret_cast<std::uintptr_t>(pub_palette) << " pubSkin=0x"
             << reinterpret_cast<std::uintptr_t>(pub_skinning) << std::dec
             << " copiedPubPal=" << (copied_pub_palette ? 1 : 0)
             << " copiedPubSkin=" << (copied_pub_skinning ? 1 : 0);
        force_log_line(line.str().c_str());
    }
    return true;
}

bool puppet_skel_palette_inject_wanted() {
    if ((!g_enable_puppet_skel_palette_inject &&
         !g_enable_puppet_workspace_palette_inject) ||
        !g_puppet_net_apply || g_module == 0) {
        return false;
    }
    void* const puppet = retained_player_object(1);
    if (puppet == nullptr) {
        return false;
    }
    const ULONGLONG received =
        g_state_net.peer_state_received_ms.load(std::memory_order_acquire);
    if (received == 0 || GetTickCount64() - received > 250) {
        return false;
    }
    coop::StatePacket peer{};
    // Peer packet aim is authoritative for puppet ADS relay. Player+0x1548 on the
    // puppet can lag force_puppet_ads_flag by a frame and blocked all bw injects.
    return copy_peer_state_snapshot(peer) && peer_packet_aim_active(peer);
}

bool inject_puppet_palette_into_skel_owner(void* skel_owner) {
    const bool wanted = puppet_skel_palette_inject_wanted();
    if (!wanted) {
        return false;
    }

    void* const puppet = retained_player_object(1);
    if (puppet == nullptr) {
        log_puppet_skel_inject_skip(skel_owner, "no-puppet");
        return false;
    }
    mirror_puppet_aim_add_to_fganim(puppet);
    sync_puppet_fganim_palette_to_skinning(puppet);

    FgAnimJointBuffers puppet_buffers{};
    const char* stage = "ok";
    void* const fg = player_fganim_from_player(puppet);
    if (!resolve_fganim_joint_buffers(fg, puppet_buffers, &stage) ||
        !pointer_looks_like_heap(puppet_buffers.palette) ||
        puppet_buffers.joint_count == 0) {
        log_puppet_skel_inject_skip(skel_owner, stage);
        return false;
    }
    constexpr std::size_t kJointFloatCount = 12;
    const std::size_t buffer_bytes =
        static_cast<std::size_t>(puppet_buffers.joint_count) * kJointFloatCount *
        sizeof(float);
    if (readable_bytes(puppet_buffers.palette) < buffer_bytes) {
        log_puppet_skel_inject_skip(skel_owner, "palette-bytes");
        return false;
    }

    // REJECTED: SkelTable owner +0x230/+0x560 as FgAnimData heap pointers (bx runtime:
    // skelPal=0x760000, inline xmm rows in CharacterSkeletonEval). Inject publish-state
    // instead — pubState receives live aim-add but pubPal was null in AIM-FGANIM-DISC.
    void* const pub_state = aim_publish_active_state_from_player(puppet);
    if (pub_state == nullptr) {
        log_puppet_skel_inject_skip(skel_owner, "no-pub-state");
        return false;
    }
    if (pub_state == fg) {
        log_puppet_skel_inject_skip(skel_owner, "pub-equals-fg");
        return false;
    }
    const bool copied_pub_palette = copy_palette_to_fganim_object(
        pub_state, kFgAnimDataRuntimePayloadOffset, puppet_buffers.palette,
        buffer_bytes);
    const bool copied_pub_skinning = copy_palette_to_fganim_object(
        pub_state, kFgAnimDataCurrentSkinningMatsOffset, puppet_buffers.palette,
        buffer_bytes);
    if (!copied_pub_palette && !copied_pub_skinning) {
        log_puppet_skel_inject_skip(skel_owner, "pub-copy-fail");
        return false;
    }

    static ULONGLONG last_log = 0;
    const ULONGLONG now = GetTickCount64();
    if (now - last_log >= 400) {
        last_log = now;
        const void* pub_palette = nullptr;
        const void* pub_skinning = nullptr;
        read_fganim_buffer_ptrs(pub_state, &pub_palette, &pub_skinning);
        std::ostringstream line;
        line << "AIM-PUB-INJECT joints=" << puppet_buffers.joint_count
             << " fgPal=0x" << std::hex
             << reinterpret_cast<std::uintptr_t>(puppet_buffers.palette)
             << " pub=0x"
             << reinterpret_cast<std::uintptr_t>(pub_state) << " pubPal=0x"
             << reinterpret_cast<std::uintptr_t>(pub_palette) << " pubSkin=0x"
             << reinterpret_cast<std::uintptr_t>(pub_skinning) << std::dec
             << " copiedPubPal=" << (copied_pub_palette ? 1 : 0)
             << " copiedPubSkin=" << (copied_pub_skinning ? 1 : 0)
             << " skelOwner=0x" << std::hex
             << reinterpret_cast<std::uintptr_t>(skel_owner) << std::dec;
        force_log_line(line.str().c_str());
    }
    return true;
}

void __fastcall hooked_character_skeleton_render_update_callsite(void* skel_owner) {
    if (g_enable_puppet_skel_palette_inject) {
        log_puppet_skel_inject_gate_status();
        inject_puppet_palette_into_skel_owner(skel_owner);
    }
    if (g_original_character_skeleton_render_update != nullptr) {
        g_original_character_skeleton_render_update(skel_owner);
    }
}

bool install_character_skeleton_render_update_callsite_hook() {
    auto* const call_site = reinterpret_cast<std::uint8_t*>(
        g_module + kCharacterSkeletonRenderUpdateCallsiteRva);
    if (call_site[0] != 0xE8) {
        boot_log_line("SkelTable render inject SKIPPED (callsite not E8)");
        return false;
    }
    std::int32_t displacement = 0;
    std::memcpy(&displacement, call_site + 1, sizeof(displacement));
    const std::uintptr_t target =
        reinterpret_cast<std::uintptr_t>(call_site + 5) +
        static_cast<std::intptr_t>(displacement);
    const std::uintptr_t expected = g_module + kCharacterSkeletonRenderUpdateRva;
    if (target != expected) {
        boot_log_line("SkelTable render inject SKIPPED (Update target mismatch)");
        return false;
    }
    g_original_character_skeleton_render_update =
        reinterpret_cast<CharacterSkeletonRenderUpdateFunction>(expected);

    constexpr std::size_t kRelaySize = 14;
    auto* const relay = static_cast<std::uint8_t*>(
        allocate_executable_near(call_site, kRelaySize));
    if (relay == nullptr) {
        boot_log_line("SkelTable render inject SKIPPED (relay alloc)");
        return false;
    }
    relay[0] = 0xFF;
    relay[1] = 0x25;
    *reinterpret_cast<std::uint32_t*>(relay + 2) = 0;
    *reinterpret_cast<std::uintptr_t*>(relay + 6) =
        reinterpret_cast<std::uintptr_t>(
            &hooked_character_skeleton_render_update_callsite);
    FlushInstructionCache(GetCurrentProcess(), relay, kRelaySize);

    const std::int64_t new_displacement =
        reinterpret_cast<std::intptr_t>(relay) -
        reinterpret_cast<std::intptr_t>(call_site + 5);
    if (new_displacement < INT32_MIN || new_displacement > INT32_MAX) {
        VirtualFree(relay, 0, MEM_RELEASE);
        boot_log_line("SkelTable render inject SKIPPED (relay range)");
        return false;
    }
    DWORD old_protection = 0;
    if (!VirtualProtect(call_site, 5, PAGE_EXECUTE_READWRITE, &old_protection)) {
        VirtualFree(relay, 0, MEM_RELEASE);
        boot_log_line("SkelTable render inject SKIPPED (protect)");
        return false;
    }
    *reinterpret_cast<std::int32_t*>(call_site + 1) =
        static_cast<std::int32_t>(new_displacement);
    FlushInstructionCache(GetCurrentProcess(), call_site, 5);
    DWORD ignored = 0;
    VirtualProtect(call_site, 5, old_protection, &ignored);
    boot_log_line("SkelTable render inject installed (Update callsite 0x1B5CEA6)");
    return true;
}

bool workspace_instance_belongs_to_puppet(void* workspace, void* puppet) {
    if (workspace == nullptr || puppet == nullptr ||
        readable_bytes(workspace) <
            kSkelJointWorkspaceInstancePtrOffset + sizeof(void*)) {
        return false;
    }
    void* const instance = *reinterpret_cast<void* const*>(
        static_cast<const std::byte*>(workspace) +
        kSkelJointWorkspaceInstancePtrOffset);
    if (instance == nullptr) {
        return false;
    }
    if (instance == puppet) {
        return true;
    }
    void* const puppet_draw = readable_bytes(
        static_cast<std::byte*>(puppet) + kPlayerDrawControlOffset) >=
            sizeof(void*)
        ? *reinterpret_cast<void* const*>(
              static_cast<const std::byte*>(puppet) + kPlayerDrawControlOffset)
        : nullptr;
    void* const puppet_fg = player_fganim_from_player(puppet);
    if (instance == puppet_draw || instance == puppet_fg) {
        return true;
    }
    if (readable_bytes(instance) < 0x80) {
        return false;
    }
    const auto* const bytes = static_cast<const std::byte*>(instance);
    for (std::size_t offset = 0; offset <= 0x70; offset += sizeof(void*)) {
        void* const candidate = *reinterpret_cast<void* const*>(bytes + offset);
        if (candidate == puppet || candidate == puppet_draw ||
            candidate == puppet_fg) {
            return true;
        }
    }
    return false;
}

bool inject_puppet_palette_into_joint_workspace(void* owner, void* workspace) {
    if (!g_enable_puppet_workspace_palette_inject || owner == nullptr ||
        workspace == nullptr) {
        return false;
    }
    if (!puppet_skel_palette_inject_wanted()) {
        return false;
    }
    void* const puppet = retained_player_object(1);
    if (puppet == nullptr || !workspace_instance_belongs_to_puppet(workspace, puppet)) {
        return false;
    }
    mirror_puppet_aim_add_to_fganim(puppet);

    if (readable_bytes(workspace) <
        kSkelJointWorkspaceMatrixBaseOffset + 48) {
        return false;
    }
    const std::uint32_t joint_id = *reinterpret_cast<const std::uint32_t*>(
        static_cast<const std::byte*>(workspace) +
        kSkelJointWorkspaceJointIdOffset);

    FgAnimJointBuffers buffers{};
    const char* stage = "ok";
    void* const fg = player_fganim_from_player(puppet);
    if (!resolve_fganim_joint_buffers(fg, buffers, &stage) ||
        !pointer_looks_like_heap(buffers.palette) || buffers.joint_count == 0 ||
        joint_id >= buffers.joint_count) {
        return false;
    }
    constexpr std::size_t kJointFloatCount = 12;
    constexpr std::size_t kJointBytes = kJointFloatCount * sizeof(float);
    const std::size_t palette_bytes =
        static_cast<std::size_t>(buffers.joint_count) * kJointBytes;
    if (readable_bytes(buffers.palette) < palette_bytes) {
        return false;
    }
    const std::size_t joint_offset =
        static_cast<std::size_t>(joint_id) * kJointBytes;
    auto* const workspace_bytes = static_cast<std::byte*>(workspace);
    std::memcpy(
        workspace_bytes + kSkelJointWorkspaceMatrixBaseOffset,
        buffers.palette + (joint_offset / sizeof(float)), kJointBytes);

    static ULONGLONG last_log = 0;
    const ULONGLONG now = GetTickCount64();
    if (now - last_log >= 400) {
        last_log = now;
        std::ostringstream line;
        line << "AIM-WS-INJECT joint=" << joint_id
             << " owner=0x" << std::hex
             << reinterpret_cast<std::uintptr_t>(owner) << " ws=0x"
             << reinterpret_cast<std::uintptr_t>(workspace) << " pal=0x"
             << reinterpret_cast<std::uintptr_t>(buffers.palette) << std::dec;
        force_log_line(line.str().c_str());
    }
    return true;
}

void __fastcall hooked_character_skeleton_eval_per_joint_callsite(
    void* skel_owner, unsigned int* workspace, double xmm2, double xmm3) {
    inject_puppet_palette_into_joint_workspace(skel_owner, workspace);
    if (g_original_character_skeleton_eval_per_joint != nullptr) {
        g_original_character_skeleton_eval_per_joint(
            skel_owner, workspace, xmm2, xmm3);
    }
}

