void log_puppet_fganim_split_discriminator(
    void* puppet, const coop::StatePacket& peer) {
    constexpr std::size_t kJointFloatCount = 12;
    constexpr std::size_t kJointStride = kJointFloatCount * sizeof(float);
    constexpr std::uint32_t kMaxJoints = 1024;

    static ULONGLONG last_log = 0;
    static float last_peer_yaw = 0.0F;
    static void* last_pub = nullptr;
    static void* last_fg = nullptr;
    static std::uint32_t last_joint_count = 0;
    static std::array<float, kMaxJoints * kJointFloatCount> pub_skin_baseline{};
    static std::array<float, kMaxJoints * kJointFloatCount> fg_skin_baseline{};

    if (!peer_packet_aim_active(peer) || puppet == nullptr) {
        return;
    }
    const ULONGLONG now = GetTickCount64();
    if (now - last_log < 400) {
        return;
    }

    float peer_fx = 0.0F;
    float peer_fy = 0.0F;
    float peer_fz = 0.0F;
    quat_forward_pos_z(peer.pose_seed + 4, peer_fx, peer_fy, peer_fz);
    const float peer_yaw = horizontal_yaw_degrees(peer_fx, peer_fz);
    if (last_log != 0 && std::fabs(peer_yaw - last_peer_yaw) < 2.0F) {
        return;
    }

    float ctrl_weights[4]{};
    float ctrl_blend = 0.0F;
    if (void* const aim = player_aim_controller_from_player(puppet);
        aim != nullptr && readable_bytes(aim) >= 0x8F0) {
        const auto* const aim_bytes = static_cast<const std::byte*>(aim);
        std::memcpy(ctrl_weights, aim_bytes + 0x8B8, sizeof(ctrl_weights));
        ctrl_blend = *reinterpret_cast<const float*>(aim_bytes + 0x8EC);
    }
    const float ctrl_sum = std::fabs(ctrl_weights[0]) + std::fabs(ctrl_weights[1]) +
                           std::fabs(ctrl_weights[2]) + std::fabs(ctrl_weights[3]);
    if (ctrl_sum < 0.01F && ctrl_blend < 0.5F) {
        return;
    }

    void* const fg_object =
        readable_bytes(static_cast<std::byte*>(puppet) + kPlayerFgAnimDataOffset) >=
                sizeof(void*)
            ? *reinterpret_cast<void* const*>(
                  static_cast<const std::byte*>(puppet) + kPlayerFgAnimDataOffset)
            : nullptr;
    void* const pub_object = aim_publish_active_state_from_player(puppet);

    FgAnimJointBuffers pub{};
    FgAnimJointBuffers fg{};
    const char* pub_stage = "ok";
    const char* fg_stage = "ok";
    const bool pub_ok = resolve_fganim_joint_buffers(pub_object, pub, &pub_stage);
    const bool fg_ok = resolve_fganim_joint_buffers(fg_object, fg, &fg_stage);
    if (!pub_ok && !fg_ok) {
        std::ostringstream line;
        line << "AIM-FGANIM-DISC stage=both-fail pubStage=" << pub_stage
             << " fgStage=" << fg_stage << " pub=0x" << std::hex
             << reinterpret_cast<std::uintptr_t>(pub_object) << " fg=0x"
             << reinterpret_cast<std::uintptr_t>(fg_object) << std::dec
             << " seq=" << peer.sequence;
        force_log_line(line.str().c_str());
        last_log = now;
        last_peer_yaw = peer_yaw;
        return;
    }

    const std::uint32_t joint_count =
        pub_ok ? pub.joint_count : fg.joint_count;
    const std::size_t buffer_bytes =
        static_cast<std::size_t>(joint_count) * kJointStride;
    const bool reset_baseline = pub_object != last_pub || fg_object != last_fg ||
                                  joint_count != last_joint_count;
    if (reset_baseline) {
        if (pub_ok && pub.skinning != nullptr &&
            readable_bytes(pub.skinning) >= buffer_bytes) {
            std::memcpy(pub_skin_baseline.data(), pub.skinning, buffer_bytes);
        }
        if (fg_ok && fg.skinning != nullptr &&
            readable_bytes(fg.skinning) >= buffer_bytes) {
            std::memcpy(fg_skin_baseline.data(), fg.skinning, buffer_bytes);
        }
        last_pub = pub_object;
        last_fg = fg_object;
        last_joint_count = joint_count;
        std::ostringstream line;
        line << "AIM-FGANIM-DISC baseline seq=" << peer.sequence
             << " joints=" << joint_count << " pub=0x" << std::hex
             << reinterpret_cast<std::uintptr_t>(pub_object) << " fg=0x"
             << reinterpret_cast<std::uintptr_t>(fg_object) << " pubPal=0x"
             << reinterpret_cast<std::uintptr_t>(pub.palette) << " fgPal=0x"
             << reinterpret_cast<std::uintptr_t>(fg.palette) << " pubSkin=0x"
             << reinterpret_cast<std::uintptr_t>(pub.skinning) << " fgSkin=0x"
             << reinterpret_cast<std::uintptr_t>(fg.skinning) << std::dec
             << " sameObj=" << ((pub_object == fg_object) ? 1 : 0)
             << " samePal="
             << ((pub_ok && fg_ok && pub.palette == fg.palette) ? 1 : 0)
             << " sameSkin="
             << ((pub_ok && fg_ok && pub.skinning == fg.skinning) ? 1 : 0);
        force_log_line(line.str().c_str());
        last_log = now;
        last_peer_yaw = peer_yaw;
        return;
    }

    struct RankedJoint {
        std::uint32_t index = 0;
        float value = 0.0F;
    };
    auto rank_joint = [](RankedJoint top[3], std::uint32_t index, float value) {
        for (int rank = 0; rank < 3; ++rank) {
            if (value > top[rank].value) {
                for (int shift = 2; shift > rank; --shift) {
                    top[shift] = top[shift - 1];
                }
                top[rank] = {index, value};
                break;
            }
        }
    };

    RankedJoint cross_pal[3]{};
    RankedJoint cross_skin[3]{};
    RankedJoint pub_skin_motion[3]{};
    RankedJoint fg_skin_motion[3]{};
    float pub_skin_total = 0.0F;
    float fg_skin_total = 0.0F;
    std::uint32_t finite_joints = 0;
    for (std::uint32_t joint = 0; joint < joint_count; ++joint) {
        if (pub_ok && fg_ok) {
            rank_joint(cross_pal, joint,
                       joint_matrix_delta(pub.palette, fg.palette, joint_count, joint));
            rank_joint(cross_skin, joint,
                       joint_matrix_delta(pub.skinning, fg.skinning, joint_count, joint));
        }
        if (pub_ok && pub.skinning != nullptr) {
            const float motion = joint_matrix_delta(
                pub.skinning, pub_skin_baseline.data(), joint_count, joint);
            if (motion > 0.0F) {
                rank_joint(pub_skin_motion, joint, motion);
                pub_skin_total += motion;
                ++finite_joints;
            }
        }
        if (fg_ok && fg.skinning != nullptr) {
            const float motion = joint_matrix_delta(
                fg.skinning, fg_skin_baseline.data(), joint_count, joint);
            if (motion > 0.0F) {
                rank_joint(fg_skin_motion, joint, motion);
                fg_skin_total += motion;
            }
        }
    }

    float pub_weights[4]{};
    float fg_weights[4]{};
    if (pub_object != nullptr) {
        float raw[4]{};
        if (read_aim_additive_lrdu(pub_object, kAnimStateAimAddDownOffset, raw)) {
            pub_weights[0] = raw[2];
            pub_weights[1] = raw[3];
            pub_weights[2] = raw[0];
            pub_weights[3] = raw[1];
        }
    }
    if (fg_object != nullptr) {
        float raw[4]{};
        if (read_aim_additive_lrdu(fg_object, kAnimStateAimAddDownOffset, raw)) {
            fg_weights[0] = raw[2];
            fg_weights[1] = raw[3];
            fg_weights[2] = raw[0];
            fg_weights[3] = raw[1];
        }
    }

    float fg_pal_total = 0.0F;
    RankedJoint fg_pal_motion[3]{};
    if (fg_ok && fg.palette != nullptr) {
        static std::array<float, kMaxJoints * kJointFloatCount> fg_pal_baseline{};
        static void* fg_pal_owner = nullptr;
        static std::uint32_t fg_pal_joint_count = 0;
        const bool reset_fg_pal = fg_object != fg_pal_owner ||
                                  joint_count != fg_pal_joint_count;
        if (reset_fg_pal) {
            if (readable_bytes(fg.palette) >= buffer_bytes) {
                std::memcpy(fg_pal_baseline.data(), fg.palette, buffer_bytes);
            }
            fg_pal_owner = fg_object;
            fg_pal_joint_count = joint_count;
        } else {
            for (std::uint32_t joint = 0; joint < joint_count; ++joint) {
                const float motion = joint_matrix_delta(
                    fg.palette, fg_pal_baseline.data(), joint_count, joint);
                if (motion > 0.0F) {
                    rank_joint(fg_pal_motion, joint, motion);
                    fg_pal_total += motion;
                }
            }
            if (readable_bytes(fg.palette) >= buffer_bytes) {
                std::memcpy(fg_pal_baseline.data(), fg.palette, buffer_bytes);
            }
        }
    }

    const bool fg_skin_valid = pointer_looks_like_heap(fg.skinning);
    const bool pub_skin_valid = pointer_looks_like_heap(pub.skinning);

    std::ostringstream line;
    line << "AIM-FGANIM-DISC seq=" << peer.sequence << " peerYaw=" << peer_yaw
         << " pubAdd=(" << pub_weights[0] << "," << pub_weights[1] << ","
         << pub_weights[2] << "," << pub_weights[3] << ") fgAdd=("
         << fg_weights[0] << "," << fg_weights[1] << "," << fg_weights[2]
         << "," << fg_weights[3] << ") pubOk=" << (pub_ok ? 1 : 0)
         << " fgOk=" << (fg_ok ? 1 : 0) << " pubPalValid="
         << (pointer_looks_like_heap(pub.palette) ? 1 : 0)
         << " fgPalValid=" << (pointer_looks_like_heap(fg.palette) ? 1 : 0)
         << " pubSkinValid=" << (pub_skin_valid ? 1 : 0)
         << " fgSkinValid=" << (fg_skin_valid ? 1 : 0)
         << " samePal="
         << ((pub_ok && fg_ok && pub.palette == fg.palette) ? 1 : 0)
         << " sameSkin="
         << ((pub_ok && fg_ok && pub.skinning == fg.skinning) ? 1 : 0)
         << " crossPal=" << cross_pal[0].index << ":" << cross_pal[0].value
         << "," << cross_pal[1].index << ":" << cross_pal[1].value
         << " crossSkin=" << cross_skin[0].index << ":" << cross_skin[0].value
         << "," << cross_skin[1].index << ":" << cross_skin[1].value
         << " fgPalTot=" << fg_pal_total << " pubSkinTot=" << pub_skin_total
         << " fgSkinTot=" << fg_skin_total << " pubSkinTop="
         << pub_skin_motion[0].index << ":" << pub_skin_motion[0].value
         << " fgSkinTop=" << fg_skin_motion[0].index << ":"
         << fg_skin_motion[0].value << " fgPalTop=" << fg_pal_motion[0].index
         << ":" << fg_pal_motion[0].value << " finite=" << finite_joints;
    force_log_line(line.str().c_str());

    if (pub_ok && pub.skinning != nullptr &&
        readable_bytes(pub.skinning) >= buffer_bytes) {
        std::memcpy(pub_skin_baseline.data(), pub.skinning, buffer_bytes);
    }
    if (fg_ok && fg.skinning != nullptr &&
        readable_bytes(fg.skinning) >= buffer_bytes) {
        std::memcpy(fg_skin_baseline.data(), fg.skinning, buffer_bytes);
    }
    last_log = now;
    last_peer_yaw = peer_yaw;
}

void log_puppet_joint_palette_motion(
    void* puppet, const coop::StatePacket& peer) {
    constexpr std::size_t kJointFloatCount = 12;
    constexpr std::size_t kJointStride = kJointFloatCount * sizeof(float);
    constexpr std::size_t kMaxJoints = 1024;

    static std::array<float, kMaxJoints * kJointFloatCount> last_palette{};
    static void* last_fg = nullptr;
    static std::uint32_t last_joint_count = 0;
    static ULONGLONG last_sample_ms = 0;
    static ULONGLONG last_seen_ms = 0;
    static ULONGLONG last_status_ms = 0;

    const ULONGLONG now = GetTickCount64();
    if (!peer_packet_aim_active(peer)) {
        last_seen_ms = 0;
        return;
    }
    const bool stale_baseline = last_seen_ms == 0 || now - last_seen_ms > 1000;
    last_seen_ms = now;
    if (!stale_baseline && now - last_sample_ms < 400) {
        return;
    }
    last_sample_ms = now;

    auto log_status = [&](const char* stage, const void* fg, const void* skeleton,
                          const void* current, const void* previous,
                          std::uint32_t joint_count, std::size_t readable) {
        if (now - last_status_ms < 1000) {
            return;
        }
        last_status_ms = now;
        std::ostringstream line;
        line << "AIM-PALETTE-STATUS stage=" << stage << " seq=" << peer.sequence
             << " puppet=0x" << std::hex
             << reinterpret_cast<std::uintptr_t>(puppet) << " fg=0x"
             << reinterpret_cast<std::uintptr_t>(fg) << " skel=0x"
             << reinterpret_cast<std::uintptr_t>(skeleton) << " cur=0x"
             << reinterpret_cast<std::uintptr_t>(current) << " prev=0x"
             << reinterpret_cast<std::uintptr_t>(previous) << std::dec
             << " joints=" << joint_count << " readable=" << readable;
        force_log_line(line.str().c_str());
    };

    if (puppet == nullptr ||
        readable_bytes(puppet) < kPlayerFgAnimDataOffset + sizeof(void*)) {
        log_status("puppet", nullptr, nullptr, nullptr, nullptr, 0,
                   readable_bytes(puppet));
        return;
    }
    auto* const player_bytes = static_cast<std::byte*>(puppet);
    void* const fg = *reinterpret_cast<void**>(
        player_bytes + kPlayerFgAnimDataOffset);
    if (fg == nullptr ||
        readable_bytes(fg) < kFgAnimDataPreviousPaletteOffset + sizeof(void*)) {
        log_status("fg", fg, nullptr, nullptr, nullptr, 0, readable_bytes(fg));
        return;
    }
    auto* const fg_bytes = static_cast<std::byte*>(fg);
    void* const skeleton =
        *reinterpret_cast<void**>(fg_bytes + kFgAnimDataSkeletonOffset);
    const float* const current = *reinterpret_cast<float**>(
        fg_bytes + kFgAnimDataRuntimePayloadOffset);
    const float* const previous = *reinterpret_cast<float**>(
        fg_bytes + kFgAnimDataPreviousPaletteOffset);
    if (skeleton == nullptr ||
        readable_bytes(skeleton) < kSkeletonJointCountOffset + sizeof(std::uint32_t) ||
        current == nullptr) {
        log_status("skeleton", fg, skeleton, current, previous, 0,
                   readable_bytes(skeleton));
        return;
    }
    const std::uint32_t joint_count = *reinterpret_cast<const std::uint32_t*>(
        static_cast<const std::byte*>(skeleton) + kSkeletonJointCountOffset);
    if (joint_count == 0 || joint_count > kMaxJoints) {
        log_status("joint-count", fg, skeleton, current, previous, joint_count,
                   readable_bytes(skeleton));
        return;
    }
    const std::size_t palette_bytes =
        static_cast<std::size_t>(joint_count) * kJointStride;
    if (readable_bytes(current) < palette_bytes) {
        log_status("current-buffer", fg, skeleton, current, previous, joint_count,
                   readable_bytes(current));
        return;
    }

    const bool reset = stale_baseline || fg != last_fg ||
                       joint_count != last_joint_count;
    if (reset) {
        std::memcpy(last_palette.data(), current, palette_bytes);
        last_fg = fg;
        last_joint_count = joint_count;
        std::ostringstream line;
        line << "AIM-PALETTE baseline seq=" << peer.sequence
             << " joints=" << joint_count << " fg=0x" << std::hex
             << reinterpret_cast<std::uintptr_t>(fg) << " cur=0x"
             << reinterpret_cast<std::uintptr_t>(current) << " prev=0x"
             << reinterpret_cast<std::uintptr_t>(previous) << std::dec;
        force_log_line(line.str().c_str());
        return;
    }

    struct JointDelta {
        std::uint32_t index = 0;
        float value = 0.0F;
    };
    std::array<JointDelta, 6> top{};
    float total_delta = 0.0F;
    std::uint32_t finite_joints = 0;
    for (std::uint32_t joint = 0; joint < joint_count; ++joint) {
        const std::size_t base =
            static_cast<std::size_t>(joint) * kJointFloatCount;
        float sum_sq = 0.0F;
        bool finite = true;
        for (std::size_t component = 0; component < kJointFloatCount; ++component) {
            const float a = current[base + component];
            const float b = last_palette[base + component];
            if (!std::isfinite(a) || !std::isfinite(b)) {
                finite = false;
                break;
            }
            const float delta = a - b;
            sum_sq += delta * delta;
        }
        if (!finite || !std::isfinite(sum_sq)) {
            continue;
        }
        const float delta = std::sqrt(sum_sq);
        total_delta += delta;
        ++finite_joints;
        for (std::size_t rank = 0; rank < top.size(); ++rank) {
            if (delta > top[rank].value) {
                for (std::size_t shift = top.size() - 1; shift > rank; --shift) {
                    top[shift] = top[shift - 1];
                }
                top[rank] = {joint, delta};
                break;
            }
        }
    }

    float weights[5]{};
    if (void* const aim = player_aim_controller_from_player(puppet);
        aim != nullptr && readable_bytes(aim) >= 0x8F0) {
        const auto* const aim_bytes = static_cast<const std::byte*>(aim);
        std::memcpy(weights, aim_bytes + 0x8B8, 4 * sizeof(float));
        weights[4] = *reinterpret_cast<const float*>(aim_bytes + 0x8EC);
    }
    const float weight_sum = std::fabs(weights[0]) + std::fabs(weights[1]) +
                             std::fabs(weights[2]) + std::fabs(weights[3]);
    if (weight_sum < 0.01F && weights[4] < 0.5F) {
        return;
    }
    std::ostringstream line;
    line << "AIM-PALETTE seq=" << peer.sequence << " joints=" << joint_count
         << " finite=" << finite_joints << " total=" << total_delta
         << " weights=(" << weights[0] << "," << weights[1] << ","
         << weights[2] << "," << weights[3] << ") blend=" << weights[4]
         << " root0=(" << current[0] << "," << current[1] << ","
         << current[2] << "," << current[3] << ") top=";
    for (const JointDelta& entry : top) {
        line << entry.index << ":" << entry.value << ",";
    }
    force_log_line(line.str().c_str());
    std::memcpy(last_palette.data(), current, palette_bytes);
}

const char* action_state_hash_label(std::uint32_t hash) {
    switch (hash) {
    case 0xF52B3E61u:
        return "GunMoveShield";
    case 0x12D842C0u:
        return "GunMove";
    case 0x009C0AB7u:
        return "GunMoveGrapple";
    case 0xA4E760F7u:
        return "GunMoveCarry";
    case 0xF34DD4BEu:
        return "GunMoveCarryNpc";
    case 0xD6D6FD81u:
        return "GunMoveHeavyWeapon";
    case 0x48C615D8u:
        return "Cover";
    default:
        return "unknown";
    }
}

bool read_player_current_action_hash(
    void* player, std::uint32_t& hash, void*& active_state) {
    hash = 0;
    active_state = nullptr;
    if (player == nullptr ||
        readable_bytes(static_cast<std::byte*>(player) + 0xC0) < sizeof(void*)) {
        return false;
    }
    void* const state_slot = *reinterpret_cast<void* const*>(
        static_cast<const std::byte*>(player) + 0xC0);
    if (state_slot == nullptr || readable_bytes(state_slot) < sizeof(void*)) {
        return false;
    }
    active_state = *reinterpret_cast<void* const*>(state_slot);
    if (active_state == nullptr ||
        readable_bytes(static_cast<std::byte*>(active_state) + 0x10) <
            sizeof(void*)) {
        return false;
    }
    void* const metadata = *reinterpret_cast<void* const*>(
        static_cast<const std::byte*>(active_state) + 0x10);
    if (metadata == nullptr ||
        readable_bytes(static_cast<std::byte*>(metadata) + 0x18) <
            sizeof(std::uint32_t)) {
        return false;
    }
    hash = *reinterpret_cast<const std::uint32_t*>(
        static_cast<const std::byte*>(metadata) + 0x18);
    return true;
}

void log_puppet_action_state(
    void* puppet, const coop::StatePacket& peer) {
    if (!peer_packet_aim_active(peer)) {
        return;
    }
    static ULONGLONG last_log = 0;
    const ULONGLONG now = GetTickCount64();
    if (now - last_log < 350) {
        return;
    }
    last_log = now;
    std::uint32_t hash = 0;
    void* active_state = nullptr;
    std::ostringstream line;
    const bool ok = read_player_current_action_hash(puppet, hash, active_state);
    line << "AIM-ACTION-STATE ok=" << (ok ? 1 : 0)
         << " hash=0x" << std::hex << hash << std::dec
         << " name=" << (ok ? action_state_hash_label(hash) : "n/a")
         << " active=" << active_state << " seq=" << peer.sequence;
    force_log_line(line.str().c_str());
}

// POST (after the puppet's own update runs): assert the networked transform last
// so the engine's own integration can't fight it (was causing flicker).
void apply_puppet_transform_post(void* /*update_object*/) {
    void* puppet = retained_player_object(1);
    if (puppet == nullptr || !g_puppet_net_apply) {
        g_puppet_aim_session_owner.store(nullptr, std::memory_order_release);
        reset_puppet_auto_aim_admission();
        if (puppet == nullptr) {
            g_puppet_fganim_data.store(nullptr, std::memory_order_release);
        }
        return;
    }
    void* const previous_aim_owner = g_puppet_aim_session_owner.exchange(
        puppet, std::memory_order_acq_rel);
    if (previous_aim_owner != puppet) {
        reset_puppet_auto_aim_admission();
    }
    void* fg = nullptr;
    if (readable_bytes(
            static_cast<std::byte*>(puppet) + kPlayerFgAnimDataOffset) >=
        sizeof(void*)) {
        fg = *reinterpret_cast<void**>(
            static_cast<std::byte*>(puppet) + kPlayerFgAnimDataOffset);
    }
    g_puppet_fganim_data.store(fg, std::memory_order_release);
    coop::StatePacket pkt{};
    void* resolved = nullptr;
    if (!latest_peer_state(pkt, resolved)) {
        if (!copy_last_peer_state_snapshot(pkt) || (pkt.flags & 1) == 0) {
            return;
        }
    }
    apply_peer_health_to_slot1(pkt, false);
    auto* world = reinterpret_cast<float*>(static_cast<std::byte*>(puppet) + kWorldPositionOffset);
    auto* localp = reinterpret_cast<float*>(static_cast<std::byte*>(puppet) + kPlayerLocalPosOffset);
    auto* quat = reinterpret_cast<float*>(static_cast<std::byte*>(puppet) + kPlayerQuatOffset);
    // Restore the last validated pre-collision policy from 25637e8: native
    // locomotion owns the root and the network only closes small moving drift.
    // Exact packet pinning made a 20-24 Hz receive stream visibly step.
    constexpr float kPosLerp = 0.35F;
    constexpr float kSnapDistSq = 4.0F * 4.0F;
    const float dx = pkt.pos[0] - world[0];
    const float dy = pkt.pos[1] - world[1];
    const float dz = pkt.pos[2] - world[2];
    const bool authoritative_teleport =
        g_state_net.pending_authoritative_teleport.exchange(
            false, std::memory_order_acq_rel);
    const bool too_far = authoritative_teleport ||
                         dx * dx + dy * dy + dz * dz > kSnapDistSq;
    if (authoritative_teleport) {
        std::ostringstream line;
        line << "PUPPET-RESPAWN-SNAP seq=" << pkt.sequence
             << " from=(" << world[0] << "," << world[1] << "," << world[2]
             << ") to=(" << pkt.pos[0] << "," << pkt.pos[1] << ","
             << pkt.pos[2] << ")";
        force_log_line(line.str().c_str());
    }
    // Facing is independent from position reconciliation. The old free-run branch
    // returned before this copy, leaving the remote Player free to spin from tiny
    // local correction vectors while its peer stood still.
    // Preserve the native locomotion turn and remove packet-step snapping. Exact
    // memcpy made every newly received quaternion visible as a hard angular step.
    const ULONGLONG peer_received =
        g_state_net.peer_state_received_ms.load(std::memory_order_acquire);
    const bool peer_fresh =
        peer_received != 0 && GetTickCount64() - peer_received <= 250;
    const bool peer_aiming =
        peer_fresh && (pkt.flags & 8) != 0 && peer_packet_aim_active(pkt);
    const bool controller_relay_for_peer =
        peer_aiming && puppet_aim_controller_relay_enabled_for_peer(pkt);
    const bool pose_relay_for_peer =
        peer_aiming && puppet_aim_pose_relay_enabled_for_peer(pkt);
    const bool puppet_aiming_now = peer_aiming;
    static bool puppet_was_aiming = false;
    static bool puppet_was_pose_relaying = false;
    float orientation_dot = 1.0F;
    // Peer-only aim relay: partner puppet reflects the OTHER copy's aim, never the
    // local player's camera on this screen.
    if (g_puppet_aim_reticle_relay && peer_aiming) {
        write_peer_aim_world_targets_from_pose_seed(puppet, pkt);
    }
    if (peer_aiming) {
        // Native aim world-basis + GunMove own ADS root yaw. POST packet-quat
        // blend runs after g_original_update and cancels camera turn (confirmed
        // runtime: rootYaw diverges, visual fixed). No root writes during ADS.
        if (g_puppet_aim_facing_from_camera) {
            apply_peer_aim_facing_to_player(puppet, pkt);
        }
        if (g_enable_puppet_ads_root_yaw_snap) {
            sync_puppet_root_yaw_from_peer_camera(puppet, pkt);
        }
        if (pose_relay_for_peer) {
            apply_peer_aim_ik_world_points(puppet, pkt);
            write_peer_aim_world_targets_from_pose_seed(puppet, pkt);
            force_puppet_ads_flag(puppet, true);
            if (void* const aim_ctrl = player_aim_controller_from_player(puppet);
                aim_ctrl != nullptr) {
                force_peer_puppet_aim_blend_state(aim_ctrl);
            }
        } else if (!controller_relay_for_peer) {
            // Before staged admission, clear any stale forced ADS bit. Once the
            // button/controller stage opens, leave this native output alone until
            // GunMove is stable; clearing it here would cancel the transition.
            force_puppet_ads_flag(puppet, false);
        }
    } else if (puppet_was_aiming) {
        force_puppet_ads_flag(puppet, false);
    } else if (pkt.move_magnitude < 0.15F) {
        orientation_dot = blend_network_orientation(quat, pkt.quat, 0.18F);
    }
    if (pose_relay_for_peer) {
        mirror_puppet_aim_add_to_fganim(puppet);
    } else if (puppet_was_pose_relaying) {
        clear_puppet_fganim_aim_add(puppet);
    }
    if (g_enable_aim_palette_probe) {
        log_puppet_aim_render_discriminator(puppet, pkt);
        log_puppet_fganim_split_discriminator(puppet, pkt);
        log_puppet_joint_palette_motion(puppet, pkt);
    }
    puppet_was_aiming = puppet_aiming_now;
    puppet_was_pose_relaying = pose_relay_for_peer;
    if (g_clone_freerun) {
        if (too_far) {
            std::memcpy(world, pkt.pos, sizeof(pkt.pos));
            std::memcpy(localp, pkt.pos, sizeof(pkt.pos));
        } else {
            // Native locomotion can keep integrating an old pre-respawn target
            // even after the authoritative snap. Reconcile stationary peers too;
            // otherwise free-run leaves every sub-four-metre displacement frozen.
            constexpr float kNudgeDeadband = 0.03F;
            constexpr float kNudgeFraction = 0.08F;
            // GunMove uses a slower authored gait than ordinary Run. The full
            // running nudge visibly translates the ADS body faster than its foot
            // cycle; retain convergence but cap that unanimated component lower.
            const float max_nudge_per_update =
                pose_relay_for_peer ? 0.0F : 0.05F;
            const float horizontal_sq = dx * dx + dz * dz;
            if (horizontal_sq > kNudgeDeadband * kNudgeDeadband) {
                const float horizontal = std::sqrt(horizontal_sq);
                float step = horizontal * kNudgeFraction;
                if (step > max_nudge_per_update) {
                    step = max_nudge_per_update;
                }
                if (step > horizontal) step = horizontal;
                const float nx = dx / horizontal * step;
                const float nz = dz / horizontal * step;
                world[0] += nx;
                world[2] += nz;
                localp[0] += nx;
                localp[2] += nz;
            }
        }
        return;
    }
    if (too_far) {
        std::memcpy(world, pkt.pos, sizeof(pkt.pos));
        std::memcpy(localp, pkt.pos, sizeof(pkt.pos));
    } else {
        for (int i = 0; i < 3; ++i) {
            world[i] += (pkt.pos[i] - world[i]) * kPosLerp;
            localp[i] = world[i];
        }
        world[3] = pkt.pos[3];
        localp[3] = pkt.pos[3];
    }
}

using PlayerDeathEntryFunction = std::int64_t(__fastcall*)(void*);
PlayerDeathEntryFunction g_original_player_death_entries[4]{};

std::int64_t guard_remote_player_death(void* player, int entry) {
    coop::StatePacket peer{};
    const bool remote_clone = player != nullptr && player == retained_player_object(1);
    const bool peer_alive = remote_clone && copy_last_peer_state_snapshot(peer) &&
                            (peer.flags & 2) != 0 && peer.health > 0;
    if (peer_alive) {
        apply_peer_health_to_slot1(peer, false);
        const ULONGLONG received =
            g_state_net.peer_state_received_ms.load(std::memory_order_acquire);
        static std::atomic<ULONGLONG> last_log{0};
        const ULONGLONG now = GetTickCount64();
        ULONGLONG previous = last_log.load(std::memory_order_relaxed);
        if (now - previous >= 1000 &&
            last_log.compare_exchange_strong(
                previous, now, std::memory_order_relaxed)) {
            std::ostringstream line;
            line << "REMOTE-DEATH blocked entry=+0x" << std::hex
                 << (0xBE8 + entry * 8) << std::dec << " peer_hp=" << peer.health
                 << " packet_age_ms=" << (received != 0 ? now - received : 0);
            log_line(line.str().c_str());
        }
        return 0;
    }
    auto original = g_original_player_death_entries[entry];
    return original != nullptr ? original(player) : 0;
}

std::int64_t __fastcall hooked_player_death_be8(void* player) {
    return guard_remote_player_death(player, 0);
}
std::int64_t __fastcall hooked_player_death_bf0(void* player) {
    return guard_remote_player_death(player, 1);
}
std::int64_t __fastcall hooked_player_death_bf8(void* player) {
    return guard_remote_player_death(player, 2);
}
std::int64_t __fastcall hooked_player_death_c00(void* player) {
    return guard_remote_player_death(player, 3);
}

// Diagnostic: find the Player's velocity field. While slot-0 Chloe runs, her
// world position (+0x240) moves each frame; that per-frame delta gives the
// ground-truth horizontal movement direction. Scan the object for a float
// triplet whose direction matches the movement and whose magnitude is in a
// plausible run-speed band, and log the offset(s). Run straight for ~1s and the
// real velocity offset will be the one that recurs across the log lines.
bool g_velprobe_enabled = false;

// How many bytes from `p` are safely readable (committed, non-guard, readable
// protection) in its containing region. 0 if `p` is not readable. Used to clamp
// scans so the background probe never reads off the end of an object into
// unmapped memory (which would crash the process).
// PERF: the original readable_bytes called VirtualQuery on EVERY pointer guard
// (280 call sites, many per frame). VirtualQuery takes the process-wide address-
// space lock; the game's own asset-streaming/allocator threads take the same lock
// constantly, so per-frame VirtualQuery from our game-thread hooks CONTENDED on
// that lock and STALLED the main thread (low CPU, low FPS, smooth without the mod).
// Fast path replaces the syscall with a lock-free SEH page probe: touch one byte
// per page (cheap cached reads, no kernel transition, no VAD lock) and report how
// far from p is readable, up to a cap that still satisfies the largest guard
// (frame_state needs 0x7100). Semantics preserved: 0 if p is unreadable, else the
// readable byte count from p. VK_NEXT (Page Down) flips back to the VirtualQuery
// implementation for a live A/B.
volatile bool g_readable_bytes_fast = true;
// LAG A/B (2026-07-13): batch-disabled while diagnosing a freeze that VK_END did
// not clear. Pose-seed snapshot is now gated (e305fec); re-enable the proven aim
// animation path. Keep diagnostic probes off — they are hot-path noise only.
constexpr bool g_enable_aim_animation_relays = true;

constexpr bool g_enable_aim_diagnostic_probes = false;
// Build es: bounded read-only discriminator from selected command 0x60006
// through later blend/plugin commands and the final FgAnimData+0x230 palette.
// Four samples per signature/screen, no native calls or game-memory writes.
constexpr bool g_enable_aim_case6_probe = true;


// ============================================================================
// =====  FIRE RELAY (native replay + button pulse)
// ============================================================================
std::size_t readable_bytes_vq(const void* p) {
    MEMORY_BASIC_INFORMATION mbi{};
    if (VirtualQuery(p, &mbi, sizeof(mbi)) == 0 || mbi.State != MEM_COMMIT) {
        return 0;
    }
    const DWORD prot = mbi.Protect & 0xFF;
    const bool readable =
        prot == PAGE_READONLY || prot == PAGE_READWRITE ||
        prot == PAGE_EXECUTE_READ || prot == PAGE_EXECUTE_READWRITE ||
        prot == PAGE_WRITECOPY || prot == PAGE_EXECUTE_WRITECOPY;
    if (!readable || (mbi.Protect & PAGE_GUARD) != 0) {
        return 0;
    }
    const auto end = reinterpret_cast<std::uintptr_t>(mbi.BaseAddress) + mbi.RegionSize;
    return end - reinterpret_cast<std::uintptr_t>(p);
}

std::size_t readable_bytes(const void* p) {
    if (p == nullptr) {
        return 0;
    }
    if (!g_readable_bytes_fast) {
        return readable_bytes_vq(p);
    }
    const std::uintptr_t addr = reinterpret_cast<std::uintptr_t>(p);
    // Cap the probe span so the largest existing guard (0x7100) is satisfiable while
    // bounding the work to ~11 one-byte reads worst case.
    constexpr std::uintptr_t kProbeSpan = 0xB000;
    volatile std::size_t confirmed = 0;
    __try {
        for (std::uintptr_t page = addr & ~std::uintptr_t{0xFFF};
             page < addr + kProbeSpan; page += 0x1000) {
            (void)*reinterpret_cast<const volatile std::uint8_t*>(page);
            const std::uintptr_t page_end = page + 0x1000;
            confirmed = page_end > addr ? page_end - addr : 0;
        }
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        // confirmed holds bytes up to the end of the last page that read cleanly.
    }
    return confirmed;
}

void* get_player_active_weapon(void* player) {
    if (player == nullptr || readable_bytes(player) < sizeof(void*)) {
        return nullptr;
    }
    auto** const vtable = *reinterpret_cast<void***>(player);
    if (vtable == nullptr) return nullptr;
    using GetActiveWeaponFunction = void*(__fastcall*)(void*);
    const auto get_weapon = reinterpret_cast<GetActiveWeaponFunction>(
        vtable[kPlayerActiveWeaponVtableOffset / sizeof(void*)]);
    if (get_weapon == nullptr) return nullptr;
    __try {
        return get_weapon(player);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return nullptr;
    }
}

void* resolve_fire_controller(void* player, std::ptrdiff_t preferred_offset) {
    if (player == nullptr) {
        return nullptr;
    }
    auto try_offset = [&](std::ptrdiff_t off) -> void* {
        if (off <= 0) {
            return nullptr;
        }
        auto* const controller = static_cast<std::byte*>(player) + off;
        if (readable_bytes(controller) <
            kPlayerFireControllerOwnerOffset + sizeof(void*)) {
            return nullptr;
        }
        void* const owner = *reinterpret_cast<void**>(
            controller + kPlayerFireControllerOwnerOffset);
        return owner == player ? static_cast<void*>(controller) : nullptr;
    };

    if (preferred_offset > 0) {
        if (void* const controller = try_offset(preferred_offset)) {
            return controller;
        }
    }

    static constexpr std::ptrdiff_t kKnownOffsets[] = {0x15cf30, 0x15adb0};
    for (const std::ptrdiff_t off : kKnownOffsets) {
        if (off == preferred_offset) {
            continue;
        }
        if (void* const controller = try_offset(off)) {
            return controller;
        }
    }

    if (g_player_fire_controller_offset > 0 &&
        g_player_fire_controller_offset != preferred_offset) {
        if (void* const controller = try_offset(g_player_fire_controller_offset)) {
            return controller;
        }
    }

    static ULONGLONG last_log = 0;
    const ULONGLONG now = GetTickCount64();
    if (now - last_log > 2000) {
        last_log = now;
        std::ostringstream line;
        line << "FIRE-RELAY no controller puppet=0x" << std::hex
             << reinterpret_cast<std::uintptr_t>(player)
             << " preferred=0x" << preferred_offset << std::dec;
        log_line(line.str().c_str());
    }
    return nullptr;
}

void track_puppet_for_fire_relay(void* puppet) {
    if (puppet == nullptr) {
        return;
    }
    if (puppet != g_fire_puppet_tracked) {
        g_fire_puppet_tracked = puppet;
        g_puppet_native_fire_allowed_after_ms = 0;
        // Fresh slot-1 spawns need GiveWeapon/SwitchToWeapon before native Fire
        // replay. 2s (was 5s: with the give-fail backoff on top the puppet showed
        // no weapons for ~10-15s after spawn; native fire has its own +1000ms
        // gate after gunOk anyway).
        g_fire_puppet_ready_after_ms = GetTickCount64() + 2000;
    }
}

bool puppet_weapon_sync_ready(void* puppet) {
    if (!world_stable() || !player_object_stable(puppet) ||
        !puppet_weapon_give_vtable_ready(puppet)) {
        return false;
    }
    track_puppet_for_fire_relay(puppet);
    return GetTickCount64() >= g_fire_puppet_ready_after_ms;
}

// DIAGNOSTIC: one force-logged line with every occupied weapon slot (art per
// slot 0..22). Distinguishes "M-30 placed in slot 1" from "slot 1 is an ALIAS
// of the same weapon also present at 16" - the ascending find_weapon_slot scan
// cannot tell those apart, which is exactly where the swap investigation stuck.
void dump_player_weapon_slots(const char* tag, void* player) {
    if (player == nullptr) return;
    std::ostringstream line;
    line << tag << " slots:";
    for (int slot = 0; slot <= 22; ++slot) {
        const std::uint32_t a =
            weapon_art_id_from_object(get_weapon_from_slot(player, slot));
        if (a != 0) {
            line << " s" << slot << "=0x" << std::hex << a << std::dec;
        }
    }
    force_log_line(line.str().c_str());
}

// ---------------- Weapon-pickup animation relay: receiver side ----------------
void* resolve_weapon_pickup_by_runtime_id(
    std::uint32_t id, std::uint32_t expected_art) {
    if (g_module == 0 || id == 0) {
        return nullptr;
    }
    using ResolveFn = std::int64_t*(__fastcall*)(std::uint64_t, std::uint32_t);
    const auto resolve = reinterpret_cast<ResolveFn>(
        g_module + kResolveGameObjectHandleByIdRva);
    __try {
        const std::uint64_t manager = *reinterpret_cast<const std::uint64_t*>(
            g_module + kGlobalManagerTableRva + 22 * 8);
        if (manager == 0) {
            return nullptr;
        }
        std::int64_t* const handle = resolve(manager, id);
        if (handle == nullptr || handle[0] == 0 ||
            static_cast<std::uint32_t>(handle[1]) != id) {
            return nullptr;
        }
        void* const pickup = *reinterpret_cast<void**>(handle[0] + 8);
        if (pickup == nullptr ||
            *reinterpret_cast<std::uintptr_t*>(pickup) !=
                g_module + kWeaponPickupVftableRva ||
            *reinterpret_cast<std::uint32_t*>(
                static_cast<std::byte*>(pickup) + kGameObjectRuntimeIdOffset) != id ||
            (expected_art != 0 &&
             *reinterpret_cast<std::uint32_t*>(
                 static_cast<std::byte*>(pickup) + 0x520) != expected_art)) {
            return nullptr;
        }
        return pickup;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return nullptr;
    }
}

bool seh_publish_puppet_pickup_action(void* dispatcher, void* pickup) {
    using PublishFn = std::int64_t(__fastcall*)(void*, void*);
    const auto publish = reinterpret_cast<PublishFn>(
        g_module + kPlayerRequestedInteractRva);
    __try {
        publish(dispatcher, pickup);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

// PICKUP GESTURE (2026-07-10): activate the weapon-pickup interact command in the
// puppet's per-screen +0x590 list via InputScreenBlock_ActivateCommand. This is the
// recipe found from Player_InteractDispatcher and bypasses the +0x518 button routing
// Gated by g_puppet_pickup_gesture (Numpad 9 manual) OR relay_armed until_ms from
// apply_peer_weapon_give. Called every puppet drive tick while armed.
volatile bool g_puppet_pickup_gesture = false;

bool seh_activate_puppet_command(void* block, std::uint32_t cmd_id) {
    __try {
        const auto activate = reinterpret_cast<char(__fastcall*)(void*, std::uint32_t)>(
            g_module + kInputScreenBlockActivateCommandRva);
        activate(block, cmd_id);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

bool seh_tick_puppet_interact_dispatcher(void* puppet) {
    if (puppet == nullptr || g_module == 0 ||
        readable_bytes(static_cast<std::byte*>(puppet) + 0x4014) == 0) {
        return false;
    }
    using BuildStateFn = void*(__fastcall*)(void*, std::int32_t, const void*);
    using DispatchFn = bool(__fastcall*)(void*, void*);
    const auto build_state = reinterpret_cast<BuildStateFn>(
        g_module + kPlayerBuildInteractDispatchStateRva);
    const auto dispatch = reinterpret_cast<DispatchFn>(
        g_module + kPlayerInteractDispatcherRva);
    const std::int32_t screen_index = *reinterpret_cast<const std::int32_t*>(
        static_cast<const std::byte*>(puppet) + 0x4010);
    if (screen_index < 0 || screen_index >= 6) {
        return false;
    }
    alignas(32) std::array<std::byte, 0x180> state{};
    void* const dispatcher = reinterpret_cast<void*>(
        g_module + kPlayerInteractDispatcherBaseRva +
        kPlayerInteractDispatcherStride * static_cast<std::size_t>(screen_index));
    __try {
        build_state(
            state.data(), screen_index,
            static_cast<const std::byte*>(puppet) + kReferenceTransformOffset);
        return dispatch(dispatcher, state.data());
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        force_log_line("PICKUP-GESTURE interact dispatcher raised an exception");
        return false;
    }
}

void* seh_find_nearby_weapon_pickup(void* dispatcher, std::uint32_t art) {
    if (dispatcher == nullptr || art == 0) {
        return nullptr;
    }
    __try {
        const auto* const bytes = static_cast<const std::byte*>(dispatcher);
        const std::uint32_t count = *reinterpret_cast<const std::uint32_t*>(bytes);
        if (count > 64) {
            return nullptr;
        }
        for (std::uint32_t i = 0; i < count; ++i) {
            const auto* const entry = bytes + 8 + 32 * i;
            const auto handle = *reinterpret_cast<const std::uintptr_t*>(entry);
            const std::uint32_t id =
                *reinterpret_cast<const std::uint32_t*>(entry + 8);
            if (handle == 0 || id == 0) {
                continue;
            }
            void* const object = *reinterpret_cast<void**>(handle + 8);
            if (object == nullptr ||
                *reinterpret_cast<const std::uint32_t*>(
                    static_cast<const std::byte*>(object) +
                    kGameObjectRuntimeIdOffset) != id ||
                *reinterpret_cast<const std::uintptr_t*>(object) !=
                    g_module + kWeaponPickupVftableRva ||
                !relay_weapon_art_matches(
                    *reinterpret_cast<const std::uint32_t*>(
                        static_cast<const std::byte*>(object) + 0x520),
                    art)) {
                continue;
            }
            return object;
        }
    } __except (EXCEPTION_EXECUTE_HANDLER) {
    }
    return nullptr;
}

struct PickupActionRequestResult {
    std::int64_t availability{-1};
    bool requested{false};
};

PickupActionRequestResult seh_request_puppet_pickup_action(
    void* puppet, void* pickup);

struct PuppetPickupRecipeResult {
    std::uint32_t cmd_id{0};
    bool resolved_cmd{false};
    bool activated{false};
    bool within_radius{false};
    std::int64_t availability{-1};
    bool dispatched{false};
    bool requested{false};
    bool published{false};
};

void* seh_get_player_interact_control(void* player) {
    if (player == nullptr) {
        return nullptr;
    }
    __try {
        auto** const vtable = *reinterpret_cast<void***>(player);
        if (vtable == nullptr) {
            return nullptr;
        }
        using GetControlFn = void*(__fastcall*)(void*);
        const auto get_control = reinterpret_cast<GetControlFn>(
            vtable[kPlayerGetInteractControlVtableOffset / sizeof(void*)]);
        return get_control != nullptr ? get_control(player) : nullptr;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return nullptr;
    }
}

bool seh_resolve_weapon_pickup_cmd_id(
    void* player, void* pickup, std::uint32_t* cmd_out) {
    if (player == nullptr || cmd_out == nullptr || g_module == 0) {
        return false;
    }
    __try {
        char ammo_pickup = 0;
        char has_swap_anim = 0;
        std::uint32_t cmd_id = 0;
        using ResolveFn = std::int64_t(__fastcall*)(
            void*, void*, char*, char*, int, std::uint32_t*);
        const auto resolve = reinterpret_cast<ResolveFn>(
            g_module + kPlayerResolveWeaponPickupInteractAnimRva);
        resolve(player, pickup, &ammo_pickup, &has_swap_anim, 0, &cmd_id);
        *cmd_out = cmd_id;
        return cmd_id != 0;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

bool seh_interact_within_radius(
    void* control, void* player, void* pickup, const void* pose_ref) {
    if (control == nullptr || player == nullptr || pickup == nullptr ||
        pose_ref == nullptr || g_module == 0) {
        return false;
    }
    __try {
        using RadiusFn = char(__fastcall*)(void*, void*, void*, const void*);
        const auto within = reinterpret_cast<RadiusFn>(
            g_module + kInteractWithinRadiusRva);
        return within(control, player, pickup, pose_ref) != 0;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

std::int64_t seh_query_interact_availability(
    void* control, void* player, const void* player_handle) {
    if (control == nullptr || player == nullptr || player_handle == nullptr ||
        g_module == 0) {
        return -1;
    }
    __try {
        using GetAvailabilityFn = std::int64_t(__fastcall*)(
            void*, void*, const void*, std::uint64_t);
        const auto get_availability = reinterpret_cast<GetAvailabilityFn>(
            g_module + kInteractControlGetAvailabilityRva);
        return get_availability(control, player, player_handle, 0);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return -1;
    }
}

PuppetPickupRecipeResult seh_run_puppet_pickup_recipe(
    void* puppet, void* pickup) {
    PuppetPickupRecipeResult result{};
    if (puppet == nullptr || g_module == 0 || !world_stable()) {
        return result;
    }
    if (readable_bytes(static_cast<std::byte*>(puppet) +
                       kPlayerJoypadIndexOffset) < sizeof(std::int32_t)) {
        return result;
    }
    const std::int32_t joypad = *reinterpret_cast<const std::int32_t*>(
        static_cast<const std::byte*>(puppet) + kPlayerJoypadIndexOffset);
    if (joypad < 0 || joypad >= 6) {
        return result;
    }
    void* fs = *reinterpret_cast<void**>(g_module + kFrameStateGlobalRva);
    if (fs == nullptr ||
        readable_bytes(fs) < kFrameStateScreenBlockBaseOffset +
                                 kFrameStateScreenBlockStride * 6) {
        return result;
    }
    void* const block = static_cast<std::byte*>(fs) +
                        kFrameStateScreenBlockBaseOffset +
                        kFrameStateScreenBlockStride *
                            static_cast<std::size_t>(joypad);

    result.resolved_cmd =
        seh_resolve_weapon_pickup_cmd_id(puppet, pickup, &result.cmd_id);
    if (!result.resolved_cmd) {
        const auto string_hash = reinterpret_cast<StringHashFunction>(
            g_module + kStringHashRva);
        static std::uint32_t swap_hash = 0;
        if (swap_hash == 0) {
            swap_hash = string_hash("weapon-pickup-swap", 18, 0);
        }
        result.cmd_id = swap_hash;
    }

    result.activated = seh_activate_puppet_command(block, result.cmd_id);
    if (!result.activated) {
        return result;
    }

    g_puppet_pickup_anim_suppress_until_ms.store(
        GetTickCount64() + 2500, std::memory_order_release);

    void* const control = seh_get_player_interact_control(puppet);
    if (pickup != nullptr && control != nullptr &&
        readable_bytes(static_cast<std::byte*>(puppet) +
                       kReferenceTransformOffset) >= 16) {
        result.within_radius = seh_interact_within_radius(
            control, puppet, pickup,
            static_cast<const std::byte*>(puppet) + kReferenceTransformOffset);
        struct alignas(16) PlayerHandle {
            std::uint64_t pointer;
            std::uint32_t id;
            std::uint32_t reserved;
        } player_handle{};
        player_handle.pointer = *reinterpret_cast<const std::uint64_t*>(
            static_cast<const std::byte*>(puppet) + 168);
        player_handle.id = *reinterpret_cast<const std::uint32_t*>(
            static_cast<const std::byte*>(puppet) + 188);
        result.availability = seh_query_interact_availability(
            control, puppet, &player_handle);
    }

    result.dispatched = seh_tick_puppet_interact_dispatcher(puppet);
    if (!result.dispatched && pickup != nullptr) {
        const std::int32_t screen_index =
            *reinterpret_cast<const std::int32_t*>(
                static_cast<const std::byte*>(puppet) + 0x4010);
        void* const dispatcher = screen_index >= 0 && screen_index < 6
            ? reinterpret_cast<void*>(
                  g_module + kPlayerInteractDispatcherBaseRva +
                  kPlayerInteractDispatcherStride *
                      static_cast<std::size_t>(screen_index))
            : nullptr;
        PickupActionRequestResult request_result =
            seh_request_puppet_pickup_action(puppet, pickup);
        result.requested = request_result.requested;
        result.availability = request_result.availability;
        if (request_result.requested && dispatcher != nullptr) {
            result.published =
                seh_publish_puppet_pickup_action(dispatcher, pickup);
        }
    }
    return result;
}

PickupActionRequestResult seh_request_puppet_pickup_action(
    void* puppet, void* pickup) {
    PickupActionRequestResult result{};
    if (puppet == nullptr || pickup == nullptr) {
        return result;
    }
    struct alignas(16) PlayerHandle {
        std::uint64_t pointer;
        std::uint32_t id;
        std::uint32_t reserved;
    } player_handle{};
    __try {
        auto** const vtable = *reinterpret_cast<void***>(pickup);
        using GetInteractControlFn = void*(__fastcall*)(void*);
        const auto get_control = reinterpret_cast<GetInteractControlFn>(
            vtable[kWeaponPickupGetInteractControlVtableOffset / sizeof(void*)]);
        void* const control = get_control(pickup);
        if (control == nullptr) {
            return result;
        }
        player_handle.pointer = *reinterpret_cast<const std::uint64_t*>(
            static_cast<const std::byte*>(puppet) + 168);
        player_handle.id = *reinterpret_cast<const std::uint32_t*>(
            static_cast<const std::byte*>(puppet) + 188);
        using GetAvailabilityFn = std::int64_t(__fastcall*)(
            void*, void*, const void*, std::uint64_t);
        const auto get_availability = reinterpret_cast<GetAvailabilityFn>(
            g_module + kInteractControlGetAvailabilityRva);
        result.availability = get_availability(
            control, puppet, &player_handle, 0);
        if (result.availability != 1) {
            return result;
        }

        auto** const control_vtable = *reinterpret_cast<void***>(control);
        using RequestInteractFn = std::int64_t(__fastcall*)(
            void*, void*, void*);
        const auto request_interact = reinterpret_cast<RequestInteractFn>(
            control_vtable[0x28 / sizeof(void*)]);
        request_interact(control, pickup, puppet);
        result.requested = true;
        return result;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        force_log_line("PICKUP-GESTURE RequestInteract raised an exception");
        return result;
    }
}

void apply_puppet_pickup_gesture(void* puppet) {
    const ULONGLONG until = g_puppet_pickup_gesture_until_ms.load(
        std::memory_order_acquire);
    const ULONGLONG now = GetTickCount64();
    const bool relay_armed = until > now;
    // apply_peer_weapon_give arms until_ms for ~1500ms after SLOT-MIRROR; Numpad 9
    // is manual override.
    if ((!g_puppet_pickup_gesture && !relay_armed) || puppet == nullptr ||
        g_module == 0 || !world_stable()) {
        return;
    }
    const std::uint32_t gesture_art =
        g_puppet_pickup_gesture_art.load(std::memory_order_acquire);
    if (gesture_art != 0 && relay_armed &&
        !puppet_has_weapon_art_id(puppet, gesture_art)) {
        return;
    }
    const std::int32_t screen_index =
        readable_bytes(static_cast<std::byte*>(puppet) + 0x4010) >=
                sizeof(std::int32_t)
            ? *reinterpret_cast<const std::int32_t*>(
                  static_cast<const std::byte*>(puppet) + 0x4010)
            : -1;
    void* const dispatcher = screen_index >= 0 && screen_index < 6
        ? reinterpret_cast<void*>(
              g_module + kPlayerInteractDispatcherBaseRva +
              kPlayerInteractDispatcherStride *
                  static_cast<std::size_t>(screen_index))
        : nullptr;
    const std::uint32_t art =
        g_puppet_pickup_gesture_art.load(std::memory_order_acquire);
    void* pickup = dispatcher != nullptr && art != 0
        ? seh_find_nearby_weapon_pickup(dispatcher, art)
        : nullptr;
    const PuppetPickupRecipeResult recipe =
        seh_run_puppet_pickup_recipe(puppet, pickup);
    if (recipe.dispatched || recipe.published) {
        g_puppet_pickup_action_started.store(true, std::memory_order_release);
    }
    static ULONGLONG last_log = 0;
    if (now - last_log > 400) {
        last_log = now;
        std::ostringstream l;
        l << "PICKUP-GESTURE cmd=0x" << std::hex << recipe.cmd_id << std::dec
          << " resolved=" << (recipe.resolved_cmd ? 1 : 0)
          << " ok=" << (recipe.activated ? 1 : 0)
          << " radius=" << (recipe.within_radius ? 1 : 0)
          << " dispatch=" << (recipe.dispatched ? 1 : 0)
          << " availability=" << recipe.availability
          << " requested=" << (recipe.requested ? 1 : 0)
          << " published=" << (recipe.published ? 1 : 0)
          << " pickup=" << (pickup != nullptr ? 1 : 0)
          << " started="
          << (g_puppet_pickup_action_started.load(std::memory_order_acquire)
                  ? 1
                  : 0)
          << " (held)";
        force_log_line(l.str().c_str());
    }
}

// CONTEXT-REPLAY publish (2026-07-12): author the player-requested-interact
// descriptor directly onto the puppet's actor state slot, bypassing the interact
// dispatcher (which never runs for the puppet). Balanced TLS ContextProcess scope:
// save -> set puppet -> publish(dispatcher, two-id surrogate) -> restore. The
// surrogate carries only the two dwords the publisher reads (class @+0x38, name
// @+0xD8). Returns true if the publish ran without faulting.
bool seh_context_replay_publish(void* puppet, void* dispatcher,
                                std::uint32_t class_id, std::uint32_t name_id) {
    if (puppet == nullptr || dispatcher == nullptr) return false;
    using GetCtxFn = void*(__fastcall*)();
    using SetCtxFn = void*(__fastcall*)(void*);
    using PublishFn = void*(__fastcall*)(void*, void*);
    const auto get_ctx =
        reinterpret_cast<GetCtxFn>(g_module + kThreadContextGetCurrentRva);
    const auto set_ctx =
        reinterpret_cast<SetCtxFn>(g_module + kThreadContextSetCurrentRva);
    const auto publish =
        reinterpret_cast<PublishFn>(g_module + kPublishRequestedInteractRva);
    alignas(16) std::uint8_t surrogate[0x100]{};
    *reinterpret_cast<std::uint32_t*>(surrogate + 0x38) = class_id;
    *reinterpret_cast<std::uint32_t*>(surrogate + 0xD8) = name_id;
    void* saved = nullptr;
    bool ran = false;
    __try {
        saved = get_ctx();
        set_ctx(puppet);
        publish(dispatcher, surrogate);
        ran = true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        ran = false;
    }
    // Restore context on every path (separate __try so a publish fault still restores).
    __try {
        set_ctx(saved);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
    }
    return ran;
}

// Consume only from the puppet's per-player update. Player_PublishRequestedInteract
// resolves its target actor from thread-local state, so calling it from the global
// drive tick could animate the local player instead.
bool seh_queue_puppet_pickup_controller_start(
    void* puppet, const std::uint8_t start_args[32]) {
    if (puppet == nullptr || start_args == nullptr ||
        g_original_player_pickup_start == nullptr ||
        readable_bytes(static_cast<std::byte*>(puppet) + 0x1EC0) <
            sizeof(void*)) {
        return false;
    }
    void* const controller = *reinterpret_cast<void**>(
        static_cast<std::byte*>(puppet) + 0x1EB8);
    if (controller == nullptr ||
        readable_bytes(static_cast<std::byte*>(controller) + 0x110) <
            sizeof(void*)) {
        return false;
    }
    __try {
        if (*reinterpret_cast<void**>(
                static_cast<std::byte*>(controller) + 0x108) != puppet) {
            return false;
        }
        return g_original_player_pickup_start(
                   controller, nullptr, start_args) != 0;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

void apply_peer_pickup_animation(void* puppet) {
    if (!g_pickup_relay) {
        g_pending_pickup_flag.store(false, std::memory_order_release);
        return;
    }
    if (!g_pending_pickup_flag.load(std::memory_order_acquire)) {
        return;
    }
    const std::uint32_t id = g_pending_pickup_id.load(std::memory_order_relaxed);
    const std::uint32_t art =
        g_pending_pickup_art.load(std::memory_order_relaxed);
    const std::uint32_t seq =
        g_pending_pickup_seq.load(std::memory_order_relaxed);
    const bool controller_start =
        g_pending_pickup_controller_start.load(std::memory_order_relaxed);
    if (g_module == 0 || puppet == nullptr || !world_stable() ||
        readable_bytes(static_cast<std::byte*>(puppet) + 0x4010) <
            sizeof(std::uint32_t)) {
        return;
    }
    if (!controller_start && art != 0 && !puppet_has_weapon_art_id(puppet, art)) {
        return;
    }

    if (controller_start) {
        alignas(16) std::uint8_t start_args[32]{};
        std::memcpy(start_args, g_pending_pickup_controller_start_args,
                    sizeof(start_args));
        const bool queued =
            seh_queue_puppet_pickup_controller_start(puppet, start_args);
        if (!queued) {
            static ULONGLONG last_queue_fail_log = 0;
            const ULONGLONG now = GetTickCount64();
            if (now - last_queue_fail_log > 500) {
                last_queue_fail_log = now;
                force_log_line("PICKUP-CONTROLLER-APPLY queued=0");
            }
            return;
        }
        g_pending_pickup_controller_start.store(false,
                                                 std::memory_order_relaxed);
        g_pending_pickup_flag.store(false, std::memory_order_release);
        g_last_applied_pickup_seq.store(seq, std::memory_order_relaxed);
        g_puppet_pickup_gesture_until_ms.store(0, std::memory_order_release);
        g_puppet_pickup_action_started.store(true, std::memory_order_release);
        force_log_line("PICKUP-CONTROLLER-APPLY queued=1");
        return;
    }

    const std::uint32_t player_index = *reinterpret_cast<const std::uint32_t*>(
        static_cast<const std::byte*>(puppet) + 0x4010);
    void* const dispatcher = player_index < 6
        ? reinterpret_cast<void*>(
              g_module + kPlayerInteractDispatcherBaseRva +
              kPlayerInteractDispatcherStride * player_index)
        : nullptr;
    // CONTEXT-REPLAY path (primary, 2026-07-12): publish directly with the two
    // relayed interactable ids, no mirrored WeaponPickup needed. Falls back to the
    // old resolve+recipe path when the ids are absent or the toggle is off.
    const std::uint32_t class_id =
        g_pending_pickup_class_id.load(std::memory_order_relaxed);
    const std::uint32_t name_id =
        g_pending_pickup_name_id.load(std::memory_order_relaxed);
    bool published = false;
    bool dispatched = false;
    if (g_pickup_context_replay && dispatcher != nullptr &&
        (class_id != 0 || name_id != 0)) {
        published = seh_context_replay_publish(puppet, dispatcher, class_id,
                                               name_id);
        force_log_line(published ? "PICKUP-CTXREPLAY published=1"
                                 : "PICKUP-CTXREPLAY published=0 (faulted)");
    } else {
        void* pickup = resolve_weapon_pickup_by_runtime_id(id, art);
        if (pickup == nullptr && dispatcher != nullptr && art != 0) {
            pickup = seh_find_nearby_weapon_pickup(dispatcher, art);
        }
        const PuppetPickupRecipeResult recipe =
            seh_run_puppet_pickup_recipe(puppet, pickup);
        published = recipe.published;
        dispatched = recipe.dispatched;
    }
    if (dispatched || published) {
        g_puppet_pickup_action_started.store(true, std::memory_order_release);
    }
    g_pending_pickup_flag.store(false, std::memory_order_release);
    g_last_applied_pickup_seq.store(seq, std::memory_order_relaxed);
    std::ostringstream line;
    line << "PICKUP-ANIM-APPLY id=0x" << std::hex << id
         << " art=0x" << art << " class=0x" << class_id << " name=0x" << name_id
         << std::dec << " seq=" << seq << " playerIndex=" << player_index
         << " ctxReplay=" << (g_pickup_context_replay ? 1 : 0)
         << " published=" << (published ? 1 : 0)
         << " dispatch=" << (dispatched ? 1 : 0);
    force_log_line(line.str().c_str());
}

bool puppet_weapon_sync_ready(void* puppet);
int find_weapon_slot_by_art_id(void* player, std::uint32_t art_id);

// REMOVE primitive: GetWeaponBySlot (vt+0xB0) then ProcessKillTree. Frees the
// manager slot so a relayed pickup can take the peer's slot class instead of
// spilling into the next free slot (M-30 vs pistol collision).
void seh_remove_weapon_in_slot(void* puppet, int slot) {
    if (puppet == nullptr || slot < 0) {
        return;
    }
    void* weapon = get_weapon_from_slot(puppet, slot);
    if (weapon == nullptr) {
        return;
    }
    __try {
        using KillFn = void(__fastcall*)(void*);
        const auto kill = reinterpret_cast<KillFn>(g_module + kProcessKillTreeRva);
        kill(weapon);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
    }
}

// Peer drew a whitelist long gun (Mazur) while the puppet still carries a
// relayed pickup long gun (M-30) in the same class slot — free it first.
void remove_relayed_long_gun_for_whitelist(void* puppet, std::uint32_t whitelist_art) {
    if (puppet == nullptr || whitelist_art != kCoopRifleArtId) {
        return;
    }
    for (const RelayedWeaponBlock& e : g_relayed_weapon_store) {
        if (e.art == 0 || e.art == kCoopRifleArtId || !is_long_gun_relay_art(e.art)) {
            continue;
        }
        const int slot = find_weapon_slot_by_art_id(puppet, e.art);
        if (slot >= 0) {
            seh_remove_weapon_in_slot(puppet, slot);
        }
    }
}

// The peer's slot index (0..22) holding `art`, from its latest raw snapshot
// (flag 0x40, capture order {0,1,16,17,2,3,20,22}); -1 if not found.
int peer_slot_of_art(std::uint32_t art) {
    if (art == 0) return -1;
    coop::StatePacket peer{};
    void* pp = nullptr;
    if (!latest_peer_state(peer, pp) || (peer.flags & 0x40) == 0) return -1;
    static const int slot_map[8] = {0, 1, 16, 17, 2, 3, 20, 22};
    for (int i = 0; i < 8; ++i) {
        std::uint32_t rid = 0;
        std::memcpy(&rid, peer.weapon_snapshot + i * sizeof(rid), sizeof(rid));
        if (rid == art) return slot_map[i];
    }
    return -1;
}

// Resolve the manager slot to free before a relayed pickup give.
int resolve_give_target_slot(std::uint32_t art, int packet_slot) {
    if (art == kCoopPistolArtId || art == kCoopScopedPistolArtId) {
        return packet_slot >= 0 ? packet_slot : 17;
    }
    if (is_long_gun_relay_art(art)) {
        // Net mode: long guns use extended slot 16 (sub_141094420). Runtime
        // find_weapon_slot_by_art_id often returns 1 after a bad give — never
        // trust pistol slots for long-gun pickup relay.
        if (packet_slot == 16 || packet_slot == 0) {
            return packet_slot == 0 ? 16 : packet_slot;
        }
        const int peer_slot = peer_slot_of_art(art);
        if (peer_slot == 16 || peer_slot == 0) {
            return peer_slot == 0 ? 16 : peer_slot;
        }
        return 16;
    }
    if (packet_slot >= 0) {
        return packet_slot;
    }
    const int peer_slot = peer_slot_of_art(art);
    if (peer_slot >= 0) {
        return peer_slot;
    }
    return 16;
}

struct PendingWorldWeaponLifecycle {
    bool consume_pending{false};
    bool drop_pending{false};
    bool wait_for_inventory{false};
    std::uint32_t sequence{0};
    std::uint32_t picked_art{0};
    std::uint32_t consumed_remote_id{0};
    std::uint32_t dropped_art{0};
    ULONGLONG armed_ms{0};
    std::uint8_t dropped_payload[
        coop::kDroppedPickupEventPayloadBytes]{};
};
PendingWorldWeaponLifecycle g_pending_world_weapon_lifecycle{};

void apply_pending_weapon_world_packet() {
    if (!g_pending_weapon_world_flag.exchange(
            false, std::memory_order_acq_rel)) {
        return;
    }
    coop::WeaponWorldPacket packet{};
    AcquireSRWLockShared(&g_pending_weapon_world_lock);
    packet = g_pending_weapon_world_packet;
    ReleaseSRWLockShared(&g_pending_weapon_world_lock);
    if (packet.version != coop::kWeaponWorldVersion ||
        packet.sequence == 0 || packet.picked_weapon_art_id == 0 ||
        packet.sequence == g_last_applied_weapon_world_seq.load(
                               std::memory_order_relaxed)) {
        return;
    }
    auto& pending = g_pending_world_weapon_lifecycle;
    pending = {};
    pending.sequence = packet.sequence;
    pending.picked_art = packet.picked_weapon_art_id;
    pending.consumed_remote_id = packet.consumed_pickup_stable_id;
    pending.dropped_art = packet.dropped_weapon_art_id;
    pending.armed_ms = GetTickCount64();
    pending.consume_pending =
        (packet.flags & coop::kWeaponGiveWorldConsume) != 0;
    pending.drop_pending =
        (packet.flags & coop::kWeaponGiveWorldDrop) != 0 &&
        packet.dropped_weapon_art_id != 0;
    if (pending.drop_pending) {
        std::memcpy(pending.dropped_payload,
                    packet.dropped_pickup_event_payload,
                    sizeof(pending.dropped_payload));
    }
    g_last_applied_weapon_world_seq.store(
        packet.sequence, std::memory_order_relaxed);
}

std::int64_t* seh_resolve_native_world_handle(std::uint32_t stable_id) {
    if (g_module == 0 || stable_id == 0) {
        return nullptr;
    }
    using ResolveFn = std::int64_t*(__fastcall*)(std::uint64_t, std::uint32_t);
    const auto resolve = reinterpret_cast<ResolveFn>(
        g_module + kResolveGameObjectHandleByIdRva);
    __try {
        const std::uint64_t manager = *reinterpret_cast<const std::uint64_t*>(
            g_module + kGlobalManagerTableRva + 22 * sizeof(void*));
        return manager != 0 ? resolve(manager, stable_id) : nullptr;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return nullptr;
    }
}

void* seh_resolve_weapon_pickup_by_stable_id(
    std::uint32_t stable_id, std::uint32_t expected_art) {
    std::int64_t* const handle =
        seh_resolve_native_world_handle(stable_id);
    if (handle == nullptr) {
        return nullptr;
    }
    __try {
        if (handle[0] == 0) {
            return nullptr;
        }
        void* const pickup = *reinterpret_cast<void**>(handle[0] + 8);
        if (pickup == nullptr ||
            *reinterpret_cast<const std::uintptr_t*>(pickup) !=
                g_module + kWeaponPickupVftableRva ||
            *reinterpret_cast<const std::uint32_t*>(
                static_cast<const std::byte*>(pickup) + 0xD8) != stable_id ||
            (expected_art != 0 && !relay_weapon_art_matches(
                 *reinterpret_cast<const std::uint32_t*>(
                     static_cast<const std::byte*>(pickup) + 0x520),
                 expected_art))) {
            return nullptr;
        }
        return pickup;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return nullptr;
    }
}

void* seh_resolve_process_weapon_by_stable_id(
    std::uint32_t stable_id, std::uint32_t expected_art) {
    std::int64_t* const handle = seh_resolve_native_world_handle(stable_id);
    if (handle == nullptr) return nullptr;
    __try {
        if (handle[0] == 0) return nullptr;
        void* const weapon = *reinterpret_cast<void**>(handle[0] + 8);
        if (weapon == nullptr || readable_bytes(weapon) < 0x864) return nullptr;
        const auto* bytes = static_cast<const std::byte*>(weapon);
        const std::uint32_t object_id =
            *reinterpret_cast<const std::uint32_t*>(bytes + 0xD8);
        const std::uint32_t art =
            *reinterpret_cast<const std::uint32_t*>(bytes + 0x860);
        if (object_id != stable_id || art == 0 ||
            (expected_art != 0 && !relay_weapon_art_matches(art, expected_art))) {
            return nullptr;
        }
        return weapon;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return nullptr;
    }
}

std::uint32_t resolve_local_consumed_pickup_id(
    std::uint32_t remote_id, std::uint32_t art) {
    if (seh_resolve_weapon_pickup_by_stable_id(remote_id, art) != nullptr) {
        return remote_id;
    }
    if (seh_resolve_process_weapon_by_stable_id(remote_id, art) != nullptr) {
        return remote_id;
    }
    // Independent campaign copies can assign different IDs to dynamically
    // dropped objects. The remote puppet occupies the same pickup point, so its
    // per-screen proximity set is the narrow fallback discriminator.
    for (int screen = 0; screen < 6; ++screen) {
        void* const dispatcher = reinterpret_cast<void*>(
            g_module + kPlayerInteractDispatcherBaseRva +
            kPlayerInteractDispatcherStride * static_cast<std::size_t>(screen));
        void* const pickup = seh_find_nearby_weapon_pickup(dispatcher, art);
        if (pickup != nullptr) {
            const std::uint32_t local_id = read_weapon_pickup_stable_id(
                reinterpret_cast<std::uint64_t>(pickup));
            if (local_id != 0) {
                return local_id;
            }
        }
        // Ordinary authored M30/Mazur objects are ProcessWeapon instances, not
        // WeaponPickup. Match the dispatcher's validated weak handle, stable id,
        // and the ProcessWeapon art at +0x860.
        __try {
            const auto* bytes = static_cast<const std::byte*>(dispatcher);
            const std::uint32_t count =
                *reinterpret_cast<const std::uint32_t*>(bytes);
            if (count > 64) continue;
            for (std::uint32_t i = 0; i < count; ++i) {
                const auto* entry = bytes + 8 + 32 * i;
                const std::uintptr_t weak =
                    *reinterpret_cast<const std::uintptr_t*>(entry);
                const std::uint32_t generation =
                    *reinterpret_cast<const std::uint32_t*>(entry + 8);
                if (weak == 0 || generation == 0) continue;
                void* const object = *reinterpret_cast<void**>(weak + 8);
                if (object == nullptr || readable_bytes(object) < 0x864) continue;
                const auto* object_bytes = static_cast<const std::byte*>(object);
                if (*reinterpret_cast<const std::uint32_t*>(
                        object_bytes + 0xBC) != generation) {
                    continue;
                }
                const std::uint32_t candidate_art =
                    *reinterpret_cast<const std::uint32_t*>(
                        object_bytes + 0x860);
                const std::uint32_t candidate_id =
                    *reinterpret_cast<const std::uint32_t*>(
                        object_bytes + 0xD8);
                if (candidate_id != 0 &&
                    relay_weapon_art_matches(candidate_art, art)) {
                    return candidate_id;
                }
            }
        } __except (EXCEPTION_EXECUTE_HANDLER) {
        }
    }
    return 0;
}

bool seh_apply_world_pickup_consume(std::uint32_t stable_id) {
    if (stable_id == 0 || g_module == 0) {
        return false;
    }
    alignas(16) std::uint8_t event[0x30]{};
    *reinterpret_cast<std::uint32_t*>(event + 0x18) = 1;
    *reinterpret_cast<std::uint32_t*>(event + 0x1C) = stable_id;
    *reinterpret_cast<float*>(event + 0x20) = 0.0F;
    using ApplyFn = void(__fastcall*)(void*);
    const auto apply = reinterpret_cast<ApplyFn>(
        g_module + kNetEventSyncWeaponPickupsApplyRva);
    __try {
        apply(event);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

bool seh_apply_world_dropped_pickup(
    const std::uint8_t payload[coop::kDroppedPickupEventPayloadBytes],
    std::uint32_t* applied_id) {
    if (payload == nullptr || g_module == 0) {
        return false;
    }
    alignas(16) std::uint8_t event[0x80]{};
    std::memcpy(event + 0x18, payload,
                coop::kDroppedPickupEventPayloadBytes);
    auto* const event_id = reinterpret_cast<std::uint32_t*>(event + 0x1C);
    if (*event_id == 0) {
        return false;
    }
    // By the time SLOT-MIRROR has killed the puppet's replaced weapon this ID is
    // normally free. If another local object still owns it, allocate the same
    // NetDroppedPickup hash family the stock sender uses instead of corrupting
    // that registry entry.
    if (seh_resolve_native_world_handle(*event_id) != nullptr) {
        using GenerateIdFn = std::uint32_t*(__fastcall*)(
            void*, std::uint32_t*, std::uint32_t);
        const auto generate = reinterpret_cast<GenerateIdFn>(
            g_module + kGenerateNetDroppedPickupIdRva);
        std::uint32_t local_id = 0;
        __try {
            generate(nullptr, &local_id, 0);
        } __except (EXCEPTION_EXECUTE_HANDLER) {
            local_id = 0;
        }
        if (local_id == 0) {
            return false;
        }
        *event_id = local_id;
    }
    using ApplyFn = void(__fastcall*)(void*);
    const auto apply = reinterpret_cast<ApplyFn>(
        g_module + kNetEventAddDroppedPickupApplyRva);
    __try {
        apply(event);
        if (applied_id != nullptr) {
            *applied_id = *event_id;
        }
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

void apply_pending_world_weapon_lifecycle(void* puppet) {
    apply_pending_weapon_world_packet();
    PendingWorldWeaponLifecycle& pending =
        g_pending_world_weapon_lifecycle;
    if ((!pending.consume_pending && !pending.drop_pending) ||
        !world_stable()) {
        return;
    }
    const ULONGLONG now = GetTickCount64();
    if (pending.consume_pending) {
        const std::uint32_t local_id = resolve_local_consumed_pickup_id(
            pending.consumed_remote_id, pending.picked_art);
        if (local_id != 0) {
            const bool applied = seh_apply_world_pickup_consume(local_id);
            std::ostringstream line;
            line << "WORLD-PICKUP-CONSUME seq=" << pending.sequence
                 << " remote_id=0x" << std::hex
                 << pending.consumed_remote_id << " local_id=0x" << local_id
                 << " art=0x" << pending.picked_art << std::dec
                 << " applied=" << (applied ? 1 : 0);
            force_log_line(line.str().c_str());
            pending.consume_pending = false;
        } else if (now - pending.armed_ms > 5000) {
            force_log_line(
                "WORLD-PICKUP-CONSUME expired without a matching local pickup");
            pending.consume_pending = false;
        }
    }
    if (pending.drop_pending) {
        const bool inventory_ready =
            puppet != nullptr &&
            puppet_has_weapon_art_id(puppet, pending.picked_art) &&
            !puppet_has_weapon_art_id(puppet, pending.dropped_art);
        if (!pending.wait_for_inventory || inventory_ready ||
            now - pending.armed_ms > 5000) {
            std::uint32_t applied_id = 0;
            const bool applied = seh_apply_world_dropped_pickup(
                pending.dropped_payload, &applied_id);
            std::ostringstream line;
            line << "WORLD-PICKUP-DROP seq=" << pending.sequence
                 << " art=0x" << std::hex << pending.dropped_art
                 << " id=0x" << applied_id << std::dec
                 << " inventory_ready=" << (inventory_ready ? 1 : 0)
                 << " applied=" << (applied ? 1 : 0);
            force_log_line(line.str().c_str());
            pending.drop_pending = false;
        }
    }
    if (!pending.consume_pending && !pending.drop_pending) {
        pending = {};
    }
}

// Runs on the game thread. The packet only publishes the real WeaponInfo block
// into the relay store. SLOT-MIRROR is the sole owner of remove+give after the
// peer raw-slot snapshot has been stable for one second. Immediate apply raced
// the older StatePacket and removed a just-given M-30 again in the next tick.
void apply_peer_weapon_give() {
    if (!g_pickup_relay) {
        g_pending_weapon_give_flag.store(false, std::memory_order_release);
        return;
    }
    if (!g_pending_weapon_give_flag.load(std::memory_order_acquire)) {
        return;
    }
    const std::uint32_t seq =
        g_pending_weapon_give_seq.load(std::memory_order_relaxed);
    const std::uint32_t art =
        g_pending_weapon_give_art.load(std::memory_order_relaxed);
    alignas(16) std::uint8_t info[coop::kWeaponInfoBytes];
    std::memcpy(info, g_pending_weapon_give_info, coop::kWeaponInfoBytes);
    const std::uint16_t world_flags = g_pending_weapon_give_world_flags;
    const std::uint32_t consumed_id = g_pending_weapon_give_consumed_id;
    const std::uint32_t dropped_art = g_pending_weapon_give_dropped_art;
    alignas(16) std::uint8_t dropped_payload[
        coop::kDroppedPickupEventPayloadBytes]{};
    std::memcpy(dropped_payload, g_pending_weapon_give_dropped_payload,
                sizeof(dropped_payload));
    relayed_weapon_store_put(art, info);
    if (art == kCoopType97ArtId) {
        force_log_line("TYPE97-INFO-NORMALIZE ammo=-1->1");
    }
    g_last_applied_weapon_give_seq.store(seq, std::memory_order_relaxed);
    g_pending_weapon_give_flag.store(false, std::memory_order_release);
    // COPW is the sole world-lifecycle owner. Legacy COPG packets normally
    // carry no world flags; do not let their inventory arrival erase a pending
    // consume/drop transaction received just before or after them.
    if (world_flags != 0) {
        PendingWorldWeaponLifecycle& world =
            g_pending_world_weapon_lifecycle;
        world = {};
        world.sequence = seq;
        world.picked_art = art;
        world.armed_ms = GetTickCount64();
        world.wait_for_inventory = true;
        if ((world_flags & coop::kWeaponGiveWorldConsume) != 0 &&
            consumed_id != 0) {
            world.consume_pending = true;
            world.consumed_remote_id = consumed_id;
        }
        if ((world_flags & coop::kWeaponGiveWorldDrop) != 0 &&
            dropped_art != 0) {
            world.drop_pending = true;
            world.dropped_art = dropped_art;
            std::memcpy(world.dropped_payload, dropped_payload,
                        sizeof(world.dropped_payload));
        }
    }
    std::ostringstream stored;
    stored << "GIVEWEAPON-RELAY-STORED art=0x" << std::hex << art << std::dec
           << " seq=" << seq << " wait=stable-slot-mirror";
    force_log_line(stored.str().c_str());
    queue_relay_pickup_gesture_after_mirror(art, seq);
    return;
}

void suppress_puppet_fire_buttons(ULONGLONG duration_ms) {
    g_suppress_puppet_fire_buttons_until_ms = GetTickCount64() + duration_ms;
    g_fire_button_hold_until_ms = 0;
    g_state_net.active_button_press_latch.fetch_and(
        ~kJoypadFireButtonMask, std::memory_order_release);
    g_state_net.pending_button_presses.fetch_and(
        ~kJoypadFireButtonMask, std::memory_order_release);
}

bool puppet_fire_buttons_suppressed() {
    return GetTickCount64() < g_suppress_puppet_fire_buttons_until_ms;
}

std::uint32_t puppet_active_weapon_art_id(void* puppet) {
    if (puppet == nullptr) {
        return 0;
    }
    const std::uint32_t hand_art = capture_hand_attached_weapon_art_id(puppet);
    if (hand_art != 0) {
        return hand_art;
    }
    return weapon_art_id_from_object(get_player_active_weapon(puppet));
}

bool puppet_can_fire_art(void* puppet, std::uint32_t art_id) {
    if (puppet == nullptr || art_id == 0 || !player_object_stable(puppet)) {
        return false;
    }
    if (GetTickCount64() < g_fire_puppet_ready_after_ms) {
        return false;
    }
    if (!puppet_has_weapon_art_id(puppet, art_id)) {
        return false;
    }
    const int slot = find_weapon_slot_by_art_id(puppet, art_id);
    if (slot < 0) {
        return false;
    }
    const std::uint8_t attached_slot = capture_weapon_selected_mode(puppet);
    if (attached_slot != slot) {
        return false;
    }
    return puppet_active_weapon_art_id(puppet) == art_id;
}

bool coop_fire_art_family_match(std::uint32_t a, std::uint32_t b) {
    if (a == b) {
        return true;
    }
    const bool a_pistol =
        a == kCoopPistolArtId || a == kCoopScopedPistolArtId;
    const bool b_pistol =
        b == kCoopPistolArtId || b == kCoopScopedPistolArtId;
    return a_pistol && b_pistol;
}

bool peer_state_has_rifle(const coop::StatePacket& peer) {
    if ((peer.flags & 0x80) == 0) {
        return false;
    }
    // Pistol slot in hands overrides a stale rifle art id on the wire.
    if (peer.weapon_selected_mode == 1) {
        return false;
    }
    return peer.held_weapon_art_id == kCoopRifleArtId;
}

std::uint32_t peer_effective_held_art(const coop::StatePacket& peer) {
    if ((peer.flags & 0x80) == 0 || peer.held_weapon_art_id == 0) {
        return 0;
    }
    // (2026-07-06) Removed the old mode==1 rifle->pistol remap: it patched the BLIND
    // capture (mode forced to 1 by the requested-slot heuristic while the stale art
    // said rifle). The draw-state capture is authoritative now, and mode==1 can be
    // an honest current slot holding the rifle - remapping would corrupt it.
    return peer.held_weapon_art_id;
}

// Strict gate: exact art match or pistol-family swap only — never rifle when peer
// holds a pistol.
bool coop_fire_packet_matches_peer_weapon(
    const coop::FirePacket& packet, const coop::StatePacket& peer) {
    const std::uint32_t peer_art = peer_effective_held_art(peer);
    if (peer_art == 0) {
        return packet.weapon_art_id != kCoopRifleArtId &&
               is_coop_relay_fire_art(packet.weapon_art_id);
    }
    if (packet.weapon_art_id == peer_art) {
        return true;
    }
    return coop_fire_art_family_match(packet.weapon_art_id, peer_art);
}

// Strict gate before native PlayerFireController::Fire replay — mode/active-art
// alone is insufficient when SwitchToWeapon failed (gun state 0, wrong slot obj).
bool puppet_fire_ready(void* puppet, std::uint32_t art_id) {
    if (!puppet_can_fire_art(puppet, art_id)) {
        return false;
    }
    void* const weapon = get_player_active_weapon(puppet);
    if (weapon == nullptr || readable_bytes(weapon) < 0x864) {
        return false;
    }
    const std::uint32_t active_art =
        *reinterpret_cast<const std::uint32_t*>(
            static_cast<const std::byte*>(weapon) + 0x860);
    if (active_art != art_id) {
        return false;
    }
    const int slot = find_weapon_slot_by_art_id(puppet, art_id);
    if (slot < 0) {
        return false;
    }
    if (get_weapon_from_slot(puppet, slot) != weapon) {
        return false;
    }
    const int attached_slot = capture_weapon_selected_mode(puppet);
    if (attached_slot == slot) {
        return resolve_fire_controller(puppet, -1) != nullptr;
    }
    const int gun = read_gun_state(puppet);
    if (gun == 0) {
        return false;
    }
    if (gun == 1) {
        return resolve_fire_controller(puppet, -1) != nullptr;
    }
    const ULONGLONG now = GetTickCount64();
    if (puppet != g_puppet_gun_ok_puppet || art_id != g_puppet_gun_ok_art ||
        now > g_puppet_gun_ok_until_ms) {
        return false;
    }
    return resolve_fire_controller(puppet, -1) != nullptr;
}

bool puppet_native_fire_relay_ready(void* puppet, std::uint32_t art_id) {
    if (!g_native_fire_relay || !is_coop_native_fire_art(art_id) ||
        puppet == nullptr || art_id == 0 || !g_state_net.enabled) {
        return false;
    }
    if (!player_object_stable(puppet) || !puppet_weapon_sync_ready(puppet)) {
        return false;
    }
    if (GetTickCount64() < g_puppet_native_fire_allowed_after_ms) {
        return false;
    }
    if (!puppet_has_weapon_art_id(puppet, art_id)) {
        return false;
    }
    if (resolve_fire_controller(puppet, -1) == nullptr) {
        return false;
    }
    void* weapon = get_player_active_weapon(puppet);
    if (weapon == nullptr) {
        const int slot = find_weapon_slot_by_art_id(puppet, art_id);
        if (slot >= 0) {
            weapon = get_weapon_from_slot(puppet, slot);
        }
    }
    return weapon != nullptr && readable_bytes(weapon) >= 0x864 &&
           coop_fire_art_family_match(weapon_art_id_from_object(weapon), art_id);
}

bool puppet_native_fire_allowed(void* puppet, std::uint32_t art_id) {
    if (!g_native_fire_relay || !is_coop_native_fire_art(art_id)) {
        return false;
    }
    const ULONGLONG now = GetTickCount64();
    if (now < g_puppet_native_fire_allowed_after_ms) {
        return false;
    }
    if (puppet != g_puppet_gun_ok_puppet ||
        !coop_fire_art_family_match(art_id, g_puppet_gun_ok_art) ||
        now > g_puppet_gun_ok_until_ms) {
        return false;
    }
    if (!puppet_can_fire_art(puppet, art_id) &&
        !coop_fire_art_family_match(art_id, puppet_active_weapon_art_id(puppet))) {
        return false;
    }
    const int slot = find_weapon_slot_by_art_id(puppet, art_id);
    if (slot < 0 || capture_weapon_selected_mode(puppet) != slot) {
        return false;
    }
    if (resolve_fire_controller(puppet, -1) == nullptr) {
        return false;
    }
    void* const weapon = get_player_active_weapon(puppet);
    if (weapon == nullptr || readable_bytes(weapon) < 0x864) {
        return false;
    }
    return coop_fire_art_family_match(
        puppet_active_weapon_art_id(puppet), art_id);
}

bool ensure_puppet_weapon_drawn(void* puppet, std::uint32_t art_id) {
    if (puppet == nullptr || art_id == 0 || !world_stable()) {
        return false;
    }
    if (GetTickCount64() < g_fire_puppet_ready_after_ms) {
        return false;
    }
    track_puppet_for_fire_relay(puppet);
    if (!puppet_has_weapon_art_id(puppet, art_id)) {
        if (!give_held_weapon_to_puppet(puppet, art_id)) {
            return false;
        }
    }
    const int slot = find_weapon_slot_by_art_id(puppet, art_id);
    if (slot < 0) {
        return false;
    }
    void* weapon = get_player_active_weapon(puppet);
    std::uint32_t active_art = 0;
    if (weapon != nullptr && readable_bytes(weapon) >= 0x864) {
        active_art = *reinterpret_cast<const std::uint32_t*>(
            static_cast<const std::byte*>(weapon) + 0x860);
    }
    const std::uint8_t attached_slot = capture_weapon_selected_mode(puppet);
    if (active_art == art_id && attached_slot == slot) {
        return true;
    }
    if (!safe_switch_to_weapon(puppet, static_cast<std::uint32_t>(slot), true)) {
        return false;
    }
    return capture_weapon_selected_mode(puppet) == slot;
}

void sanitize_fire_args(std::uint8_t* args) {
    if (args == nullptr) {
        return;
    }
    for (std::size_t off = 0x08; off + sizeof(std::uint64_t) <= coop::kFireArgsBytes;
         off += sizeof(std::uint64_t)) {
        std::uintptr_t value = 0;
        std::memcpy(&value, args + off, sizeof(value));
        if (plausible_ptr(value)) {
            std::memset(args + off, 0, sizeof(std::uint64_t));
        }
    }
}

// Sender FireArgs+0 is the world-space aim target, not a launch origin. Preserve
// it; the exact selected-record origin is relayed separately after native muzzle
// resolution. Only sanitize embedded pointers and overlay the peer aim quat.
void prepare_puppet_fire_args_from_sender(
    void* /*puppet*/, const std::uint8_t* sender_args, std::uint8_t* out_args) {
    if (sender_args == nullptr || out_args == nullptr) {
        return;
    }
    std::memcpy(out_args, sender_args, coop::kFireArgsBytes);
    sanitize_fire_args(out_args);
    std::uint8_t seed[32]{};
    if (copy_peer_pose_seed_32(seed) &&
        kFireArgsAimQuatOffset + 16 <= coop::kFireArgsBytes) {
        __try {
            std::memcpy(out_args + kFireArgsAimQuatOffset, seed + 16, 16);
        } __except (EXCEPTION_EXECUTE_HANDLER) {
        }
    }
}

bool read_process_weapon_ammo(
    const void* weapon, std::int16_t& magazine, std::int16_t& reserve) {
    if (weapon == nullptr ||
        readable_bytes(
            static_cast<const std::byte*>(weapon) +
            kProcessWeaponMagazineAmmoOffset) < 2 * sizeof(std::int16_t)) {
        return false;
    }
    __try {
        magazine = *reinterpret_cast<const std::int16_t*>(
            static_cast<const std::byte*>(weapon) +
            kProcessWeaponMagazineAmmoOffset);
        reserve = *reinterpret_cast<const std::int16_t*>(
            static_cast<const std::byte*>(weapon) +
            kProcessWeaponReserveAmmoOffset);
        return magazine >= 0 && reserve >= 0;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

bool apply_fire_packet_ammo_to_puppet(
    void* puppet, const coop::FirePacket& packet) {
    if ((packet.flags & coop::kFireFlagAmmoSnapshot) == 0 ||
        packet.magazine_before <= 0 || packet.reserve_before < 0 ||
        puppet == nullptr || puppet == retained_player_object(0)) {
        return false;
    }

    void* weapon = get_player_active_weapon(puppet);
    if (weapon == nullptr ||
        !coop_fire_art_family_match(
            weapon_art_id_from_object(weapon), packet.weapon_art_id)) {
        const int slot = find_weapon_slot_by_art_id(
            puppet, packet.weapon_art_id);
        weapon = slot >= 0 ? get_weapon_from_slot(puppet, slot) : nullptr;
    }
    if (weapon == nullptr ||
        !coop_fire_art_family_match(
            weapon_art_id_from_object(weapon), packet.weapon_art_id) ||
        readable_bytes(
            static_cast<std::byte*>(weapon) +
            kProcessWeaponMagazineAmmoOffset) <
            kProcessWeaponAmmoDirtyStateOffset -
                kProcessWeaponMagazineAmmoOffset + 1) {
        return false;
    }

    std::int16_t old_magazine = -1;
    std::int16_t old_reserve = -1;
    if (!read_process_weapon_ammo(weapon, old_magazine, old_reserve)) {
        return false;
    }
    __try {
        *reinterpret_cast<std::int16_t*>(
            static_cast<std::byte*>(weapon) +
            kProcessWeaponMagazineAmmoOffset) = packet.magazine_before;
        *reinterpret_cast<std::int16_t*>(
            static_cast<std::byte*>(weapon) +
            kProcessWeaponReserveAmmoOffset) = packet.reserve_before;
        *reinterpret_cast<std::uint8_t*>(
            static_cast<std::byte*>(weapon) +
            kProcessWeaponMagazineLoadedStateOffset) = 1;
        *reinterpret_cast<std::uint8_t*>(
            static_cast<std::byte*>(weapon) +
            kProcessWeaponAmmoDirtyStateOffset) = 0;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }

    char line[272]{};
    void* const local_player = retained_player_object(0);
    std::snprintf(
        line, sizeof(line),
        "FIRE-AMMO-APPLY seq=%u art=0x%08X target=0x%llX local0=0x%llX "
        "before=%d/%d sender=%d/%d",
        packet.sequence, packet.weapon_art_id,
        static_cast<unsigned long long>(
            reinterpret_cast<std::uintptr_t>(puppet)),
        static_cast<unsigned long long>(
            reinterpret_cast<std::uintptr_t>(local_player)),
        static_cast<int>(old_magazine), static_cast<int>(old_reserve),
        static_cast<int>(packet.magazine_before),
        static_cast<int>(packet.reserve_before));
    boot_log_line(line);
    return true;
}

void publish_fire_packet(const coop::FirePacket& packet) {
    const std::uint32_t head = g_fire_event_ring.head.load(std::memory_order_relaxed);
    g_fire_event_ring.packets[head % 16] = packet;
    g_fire_event_ring.head.store(head + 1, std::memory_order_release);
    std::ostringstream line;
    line << "FIRE-RELAY recv seq=" << packet.sequence
         << " art=0x" << std::hex << packet.weapon_art_id
         << " ctrlOff=0x" << packet.controller_offset << std::dec
         << " origin="
         << ((packet.flags & coop::kFireFlagFinalOrigin) != 0 ? 1 : 0)
         << " ammo=" << packet.magazine_before << '/'
         << packet.reserve_before;
    boot_log_line(line.str().c_str());
}

bool prepare_fire_packet(
    void* controller, void* fire_args, void* weapon, double scalar,
    coop::FirePacket& packet) {
    if (!g_state_net.enabled || !g_state_net.peer_set ||
        controller == nullptr || fire_args == nullptr || weapon == nullptr ||
        readable_bytes(fire_args) < coop::kFireArgsBytes ||
        readable_bytes(weapon) < 0x864) {
        return false;
    }
    void* const player = *reinterpret_cast<void**>(
        static_cast<std::byte*>(controller) + kPlayerFireControllerOwnerOffset);
    if (player != retained_player_object(0)) {
        return false;
    }
    packet = {};
    packet.sequence = ++g_state_net.fire_send_seq;
    packet.controller_offset = static_cast<std::uint32_t>(
        static_cast<std::byte*>(controller) - static_cast<std::byte*>(player));
    const std::uint32_t weapon_art = *reinterpret_cast<const std::uint32_t*>(
        static_cast<const std::byte*>(weapon) + 0x860);
    const std::uint32_t held_art = capture_held_weapon_art_id(player);
    packet.weapon_art_id =
        (held_art != 0 &&
         coop_fire_art_family_match(held_art, weapon_art))
            ? held_art
            : (held_art != 0 ? held_art : weapon_art);
    packet.scalar = scalar;
    std::memcpy(packet.fire_args, fire_args, coop::kFireArgsBytes);
    std::int16_t magazine = -1;
    std::int16_t reserve = -1;
    if (read_process_weapon_ammo(weapon, magazine, reserve) && magazine > 0) {
        packet.magazine_before = magazine;
        packet.reserve_before = reserve;
        packet.flags |= coop::kFireFlagAmmoSnapshot;
    }
    return true;
}

void send_prepared_fire_packet(const coop::FirePacket& packet) {
    if (!g_state_net.enabled || !g_state_net.peer_set) {
        return;
    }
    sendto(g_state_net.send_socket, reinterpret_cast<const char*>(&packet),
           sizeof(packet), 0,
           reinterpret_cast<const sockaddr*>(&g_state_net.peer_addr),
           sizeof(g_state_net.peer_addr));
    std::ostringstream line;
    line << "FIRE-RELAY send seq=" << packet.sequence
         << " art=0x" << std::hex << packet.weapon_art_id
         << " ctrlOff=0x" << packet.controller_offset
         << std::dec << " final="
         << ((packet.flags & coop::kFireFlagFinalDirection) != 0 ? 1 : 0)
         << " origin="
         << ((packet.flags & coop::kFireFlagFinalOrigin) != 0 ? 1 : 0)
         << " ammo=" << packet.magazine_before << '/'
         << packet.reserve_before
         << " roleB=" << std::dec << (g_net_role_b ? 1 : 0);
    boot_log_line(line.str().c_str());
}

std::size_t pending_local_fire_packet_count() {
    AcquireSRWLockShared(&g_pending_local_fire_packet_lock);
    const std::size_t count = g_pending_local_fire_packet_count;
    ReleaseSRWLockShared(&g_pending_local_fire_packet_lock);
    return count;
}

void enqueue_pending_local_fire_packet(const coop::FirePacket& packet) {
    PendingLocalFirePacket overflow{};
    bool send_overflow = false;
    AcquireSRWLockExclusive(&g_pending_local_fire_packet_lock);
    if (g_pending_local_fire_packet_count ==
        kPendingLocalFirePacketCapacity) {
        overflow = g_pending_local_fire_packets[0];
        for (std::size_t i = 1; i < g_pending_local_fire_packet_count; ++i) {
            g_pending_local_fire_packets[i - 1] =
                g_pending_local_fire_packets[i];
        }
        --g_pending_local_fire_packet_count;
        send_overflow = true;
    }
    PendingLocalFirePacket& pending =
        g_pending_local_fire_packets[g_pending_local_fire_packet_count++];
    pending.packet = packet;
    pending.queued_ms = GetTickCount64();
    ReleaseSRWLockExclusive(&g_pending_local_fire_packet_lock);

    if (send_overflow) {
        char line[160]{};
        std::snprintf(
            line, sizeof(line),
            "FIRE-PENDING-FALLBACK seq=%u reason=overflow",
            overflow.packet.sequence);
        boot_log_line(line);
        send_prepared_fire_packet(overflow.packet);
    }
}

bool take_pending_local_fire_packet(
    coop::FirePacket& packet, ULONGLONG& age_ms) {
    PendingLocalFirePacket pending{};
    bool found = false;
    AcquireSRWLockExclusive(&g_pending_local_fire_packet_lock);
    if (g_pending_local_fire_packet_count != 0) {
        pending = g_pending_local_fire_packets[0];
        for (std::size_t i = 1; i < g_pending_local_fire_packet_count; ++i) {
            g_pending_local_fire_packets[i - 1] =
                g_pending_local_fire_packets[i];
        }
        --g_pending_local_fire_packet_count;
        found = true;
    }
    ReleaseSRWLockExclusive(&g_pending_local_fire_packet_lock);
    if (!found) {
        return false;
    }
    packet = pending.packet;
    age_ms = GetTickCount64() - pending.queued_ms;
    return true;
}

void flush_stale_pending_local_fire_packets() {
    std::array<PendingLocalFirePacket, kPendingLocalFirePacketCapacity> stale{};
    std::size_t stale_count = 0;
    const ULONGLONG now = GetTickCount64();
    AcquireSRWLockExclusive(&g_pending_local_fire_packet_lock);
    while (g_pending_local_fire_packet_count != 0 &&
           now - g_pending_local_fire_packets[0].queued_ms >=
               kPendingLocalFirePacketTimeoutMs) {
        stale[stale_count++] = g_pending_local_fire_packets[0];
        for (std::size_t i = 1; i < g_pending_local_fire_packet_count; ++i) {
            g_pending_local_fire_packets[i - 1] =
                g_pending_local_fire_packets[i];
        }
        --g_pending_local_fire_packet_count;
    }
    ReleaseSRWLockExclusive(&g_pending_local_fire_packet_lock);

    for (std::size_t i = 0; i < stale_count; ++i) {
        char line[192]{};
        std::snprintf(
            line, sizeof(line),
            "FIRE-PENDING-FALLBACK seq=%u age=%llu reason=timeout",
            stale[i].packet.sequence,
            static_cast<unsigned long long>(now - stale[i].queued_ms));
        boot_log_line(line);
        send_prepared_fire_packet(stale[i].packet);
    }
}

bool launch_record_owned_by_runtime_object(
    const void* launch_record, const void* runtime_object) {
    if (launch_record == nullptr || runtime_object == nullptr) {
        return false;
    }
    std::uint64_t record_handle_pointer = 0;
    std::uint32_t record_handle_id = 0;
    std::uint64_t object_handle_pointer = 0;
    std::uint32_t object_handle_id = 0;
    const auto* const record = static_cast<const std::byte*>(launch_record);
    const auto* const object = static_cast<const std::byte*>(runtime_object);
    if (!seh_read_qword(
            record + kProjectileLaunchRecordOwnerHandleOffset,
            record_handle_pointer) ||
        !seh_read_dword(
            record + kProjectileLaunchRecordOwnerHandleOffset + sizeof(void*),
            record_handle_id) ||
        !seh_read_qword(
            object + kRuntimeObjectHandlePointerOffset,
            object_handle_pointer) ||
        !seh_read_dword(
            object + kRuntimeObjectHandleIdOffset,
            object_handle_id)) {
        return false;
    }
    return (record_handle_pointer != 0 || record_handle_id != 0) &&
        record_handle_pointer == object_handle_pointer &&
        record_handle_id == object_handle_id;
}

void publish_applied_fire_direction_observation(
    const PeerFireDirectionCapture& capture, const void* launch_record) {
    AcquireSRWLockExclusive(&g_applied_fire_direction_observation_lock);
    g_applied_fire_direction_observation.capture = capture;
    g_applied_fire_direction_observation.applied_ms = GetTickCount64();
    g_applied_fire_direction_observation.launch_record =
        reinterpret_cast<std::uintptr_t>(launch_record);
    ReleaseSRWLockExclusive(&g_applied_fire_direction_observation_lock);
}

bool snapshot_applied_fire_direction_observation(
    AppliedFireDirectionObservation& observation) {
    AcquireSRWLockShared(&g_applied_fire_direction_observation_lock);
    observation = g_applied_fire_direction_observation;
    ReleaseSRWLockShared(&g_applied_fire_direction_observation_lock);
    return observation.capture.sequence != 0 && observation.applied_ms != 0 &&
        GetTickCount64() - observation.applied_ms <= 1000;
}

bool selected_launch_record_from_spawn_info(
    void* spawn_info, void*& launch_record) {
    launch_record = nullptr;
    std::uint64_t record_address = 0;
    if (spawn_info == nullptr ||
        !seh_read_qword(
            static_cast<std::byte*>(spawn_info) +
                kSpawnInfoLaunchRecordPointerOffset,
            record_address) ||
        record_address == 0) {
        return false;
    }
    launch_record = reinterpret_cast<void*>(record_address);
    return readable_bytes(launch_record) >=
        kProjectileLaunchRecordOriginMirrorOffset + sizeof(float) * 4;
}

std::int64_t __fastcall hooked_process_weapon_spawn_projectile(
    void* process_weapon, void* spawn_info, void* out_process) {
    if (g_original_process_weapon_spawn_projectile == nullptr) {
        return 0;
    }

    void* launch_record = nullptr;
    if (selected_launch_record_from_spawn_info(spawn_info, launch_record)) {
        void* const player0 = retained_player_object(0);
        void* const player1 = retained_player_object(1);
        const bool owner0 =
            launch_record_owned_by_runtime_object(launch_record, player0);
        const bool owner1 =
            launch_record_owned_by_runtime_object(launch_record, player1);
        const unsigned owner_class = owner0 ? 1U : (owner1 ? 2U : 0U);
        static std::atomic<unsigned> logged_owner_bits{0};
        const unsigned log_bit = 1U << owner_class;
        if ((logged_owner_bits.fetch_or(log_bit, std::memory_order_acq_rel) &
             log_bit) == 0) {
            char line[320]{};
            std::snprintf(
                line, sizeof(line),
                "FIRE-SELECTED-RECORD-HIT roleB=%u pending=%u owner0=%u "
                "owner1=%u peerQ=%llu record=0x%llX tid=%lu",
                g_net_role_b ? 1U : 0U,
                pending_local_fire_packet_count() != 0 ? 1U : 0U,
                owner0 ? 1U : 0U, owner1 ? 1U : 0U,
                static_cast<unsigned long long>(peer_fire_direction_count()),
                static_cast<unsigned long long>(
                    reinterpret_cast<std::uintptr_t>(launch_record)),
                static_cast<unsigned long>(GetCurrentThreadId()));
            boot_log_line(line);
        }

        if (!g_net_role_b && owner0 && !g_dll_inert && g_state_net.enabled) {
            coop::FirePacket packet{};
            ULONGLONG age_ms = 0;
            if (take_pending_local_fire_packet(packet, age_ms)) {
                PeerFireDirectionCapture capture{};
                std::memcpy(
                    capture.final_direction,
                    static_cast<std::byte*>(launch_record) +
                        kProjectileLaunchRecordDirectionOffset,
                    sizeof(capture.final_direction));
                std::memcpy(
                    capture.final_origin,
                    static_cast<std::byte*>(launch_record) +
                        kProjectileLaunchRecordOriginOffset,
                    sizeof(capture.final_origin));
                capture.has_final_origin = true;
                if (finite_fire_direction_capture(capture)) {
                    std::memcpy(
                        packet.final_direction, capture.final_direction,
                        sizeof(packet.final_direction));
                    packet.flags |= coop::kFireFlagFinalDirection;
                    if (finite_fire_origin_capture(capture)) {
                        std::memcpy(
                            packet.final_origin, capture.final_origin,
                            sizeof(packet.final_origin));
                        packet.flags |= coop::kFireFlagFinalOrigin;
                    }
                    char line[320]{};
                    std::snprintf(
                        line, sizeof(line),
                        "FIRE-SELECTED-LAUNCH-CAPTURE seq=%u age=%llu "
                        "record=0x%llX dir=(%.4f,%.4f,%.4f) "
                        "origin=(%.3f,%.3f,%.3f)",
                        packet.sequence,
                        static_cast<unsigned long long>(age_ms),
                        static_cast<unsigned long long>(
                            reinterpret_cast<std::uintptr_t>(launch_record)),
                        capture.final_direction[0], capture.final_direction[1],
                        capture.final_direction[2], capture.final_origin[0],
                        capture.final_origin[1], capture.final_origin[2]);
                    boot_log_line(line);
                }
                send_prepared_fire_packet(packet);
            }
        } else if (g_net_role_b && owner1 && !g_dll_inert &&
                   g_state_net.enabled) {
            const std::uint32_t receiver_art =
                puppet_active_weapon_art_id(player1);
            PeerFireDirectionCapture capture{};
            if (take_peer_fire_direction(receiver_art, capture) &&
                finite_fire_direction_capture(capture)) {
                float before[4]{};
                std::memcpy(
                    before,
                    static_cast<std::byte*>(launch_record) +
                        kProjectileLaunchRecordDirectionOffset,
                    sizeof(before));
                std::memcpy(
                    static_cast<std::byte*>(launch_record) +
                        kProjectileLaunchRecordDirectionOffset,
                    capture.final_direction, sizeof(capture.final_direction));
                std::memcpy(
                    static_cast<std::byte*>(launch_record) +
                        kProjectileLaunchRecordDirectionMirrorOffset,
                    capture.final_direction, sizeof(capture.final_direction));
                float origin_before[4]{};
                const bool apply_origin =
                    finite_fire_origin_capture(capture);
                if (apply_origin) {
                    std::memcpy(
                        origin_before,
                        static_cast<std::byte*>(launch_record) +
                            kProjectileLaunchRecordOriginOffset,
                        sizeof(origin_before));
                    std::memcpy(
                        static_cast<std::byte*>(launch_record) +
                            kProjectileLaunchRecordOriginOffset,
                        capture.final_origin, sizeof(capture.final_origin));
                    std::memcpy(
                        static_cast<std::byte*>(launch_record) +
                            kProjectileLaunchRecordOriginMirrorOffset,
                        capture.final_origin, sizeof(capture.final_origin));
                }
                publish_applied_fire_direction_observation(
                    capture, launch_record);
                char line[512]{};
                std::snprintf(
                    line, sizeof(line),
                    "FIRE-SELECTED-LAUNCH-APPLY seq=%u record=0x%llX "
                    "dirBefore=(%.4f,%.4f,%.4f) dirAfter=(%.4f,%.4f,%.4f) "
                    "originApply=%u originBefore=(%.3f,%.3f,%.3f) "
                    "originAfter=(%.3f,%.3f,%.3f)",
                    capture.sequence,
                    static_cast<unsigned long long>(
                        reinterpret_cast<std::uintptr_t>(launch_record)),
                    before[0], before[1], before[2],
                    capture.final_direction[0], capture.final_direction[1],
                    capture.final_direction[2], apply_origin ? 1U : 0U,
                    origin_before[0], origin_before[1], origin_before[2],
                    capture.final_origin[0], capture.final_origin[1],
                    capture.final_origin[2]);
                boot_log_line(line);
            }
        }
    }
    return g_original_process_weapon_spawn_projectile(
        process_weapon, spawn_info, out_process);
}

bool seh_projectile_probe_ray(
    void* projectile, float* start, float* end) {
    if (projectile == nullptr || start == nullptr || end == nullptr ||
        g_bound_transform_get_translation_ws == nullptr) {
        return false;
    }
    __try {
        auto* const bytes = static_cast<std::byte*>(projectile);
        g_bound_transform_get_translation_ws(
            bytes + kProjectileBulletInstantStartBoundOffset, start);
        g_bound_transform_get_translation_ws(
            bytes + kProjectileBulletInstantEndpointBoundOffset, end);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

char __fastcall hooked_projectile_bullet_instant_probe_kick(void* projectile) {
    if (g_original_projectile_bullet_instant_probe_kick == nullptr) {
        return 0;
    }
    AppliedFireDirectionObservation observation{};
    void* const puppet = retained_player_object(1);
    const auto* const instance_owner_handle = projectile != nullptr
        ? static_cast<std::byte*>(projectile) +
              kProjectileBulletInstantOwnerHandleOffset
        : nullptr;
    const bool relevant = g_net_role_b && projectile != nullptr &&
        puppet != nullptr &&
        launch_record_owned_by_runtime_object(instance_owner_handle, puppet) &&
        snapshot_applied_fire_direction_observation(observation);
    if (relevant) {
        float start[4]{};
        float end[4]{};
        if (seh_projectile_probe_ray(projectile, start, end)) {
            const float dx = end[0] - start[0];
            const float dy = end[1] - start[1];
            const float dz = end[2] - start[2];
            const float length = std::sqrt(dx * dx + dy * dy + dz * dz);
            const float expected_length = std::sqrt(
                observation.capture.final_direction[0] *
                    observation.capture.final_direction[0] +
                observation.capture.final_direction[1] *
                    observation.capture.final_direction[1] +
                observation.capture.final_direction[2] *
                    observation.capture.final_direction[2]);
            const float dot = length > 0.0001F && expected_length > 0.0001F
                ? (dx * observation.capture.final_direction[0] +
                   dy * observation.capture.final_direction[1] +
                   dz * observation.capture.final_direction[2]) /
                      (length * expected_length)
                : -2.0F;
            const float origin_dx =
                start[0] - observation.capture.final_origin[0];
            const float origin_dy =
                start[1] - observation.capture.final_origin[1];
            const float origin_dz =
                start[2] - observation.capture.final_origin[2];
            const float origin_error =
                finite_fire_origin_capture(observation.capture)
                    ? std::sqrt(origin_dx * origin_dx +
                                origin_dy * origin_dy +
                                origin_dz * origin_dz)
                    : -1.0F;
            static std::atomic<unsigned> logged_probe_count{0};
            if (logged_probe_count.fetch_add(1, std::memory_order_acq_rel) < 16) {
                char line[512]{};
                std::snprintf(
                    line, sizeof(line),
                    "FIRE-PROBE-RAY seq=%u instance=0x%llX record=0x%llX "
                    "age=%llu dot=%.5f originError=%.5f "
                    "ray=(%.4f,%.4f,%.4f) "
                    "start=(%.3f,%.3f,%.3f) end=(%.3f,%.3f,%.3f)",
                    observation.capture.sequence,
                    static_cast<unsigned long long>(
                        reinterpret_cast<std::uintptr_t>(projectile)),
                    static_cast<unsigned long long>(observation.launch_record),
                    static_cast<unsigned long long>(
                        GetTickCount64() - observation.applied_ms),
                    dot, origin_error,
                    dx / (length > 0.0001F ? length : 1.0F),
                    dy / (length > 0.0001F ? length : 1.0F),
                    dz / (length > 0.0001F ? length : 1.0F),
                    start[0], start[1], start[2], end[0], end[1], end[2]);
                boot_log_line(line);
            }
        }
    }
    return g_original_projectile_bullet_instant_probe_kick(projectile);
}

// SEH-isolated replay of PlayerFireController::Fire (no C++ unwinding objects).
bool safe_replay_player_fire(
    void* controller,
    void* fire_args,
    void* weapon,
    double scalar
) {
    if (g_original_player_fire == nullptr) {
        return false;
    }
    __try {
        g_original_player_fire(controller, fire_args, weapon, scalar);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

void apply_queued_fire_events(void* puppet) {
    if (puppet == nullptr || !player_object_stable(puppet) ||
        !puppet_weapon_sync_ready(puppet)) {
        return;
    }
    track_puppet_for_fire_relay(puppet);

    static ULONGLONG last_not_ready = 0;
    static std::uint32_t last_skip_seq = 0;
    static int skip_streak = 0;

    if (g_fire_event_ring.tail == g_fire_event_ring.head.load(
            std::memory_order_acquire)) {
        return;
    }

    const coop::FirePacket packet =
        g_fire_event_ring.packets[g_fire_event_ring.tail % 16];

    if (!is_coop_relay_fire_art(packet.weapon_art_id) &&
        !puppet_has_weapon_art_id(puppet, packet.weapon_art_id)) {
        std::ostringstream line;
        line << "FIRE-RELAY drop: unknown art=0x" << std::hex
             << packet.weapon_art_id << " seq=" << std::dec << packet.sequence;
        log_line(line.str().c_str());
        ++g_fire_event_ring.tail;
        return;
    }

    coop::StatePacket peer{};
    copy_peer_state_snapshot(peer);
    const ULONGLONG relay_now = GetTickCount64();
    if (peer_packet_aim_active(peer)) {
        g_peer_aim_recent_until_ms = relay_now + 500;
    }

    if (packet.weapon_art_id == kCoopRifleArtId && !peer_state_has_rifle(peer)) {
        std::ostringstream line;
        line << "FIRE-RELAY drop: rifle art but peer holds pistol seq="
             << packet.sequence << " peerArt=0x" << std::hex
             << peer.held_weapon_art_id << std::dec;
        log_line(line.str().c_str());
        ++g_fire_event_ring.tail;
        skip_streak = 0;
        last_skip_seq = 0;
        return;
    }

    if (!coop_fire_packet_matches_peer_weapon(packet, peer)) {
        std::ostringstream line;
        line << "FIRE-RELAY drop: art mismatch queued=0x" << std::hex
             << packet.weapon_art_id << " peer=0x" << peer.held_weapon_art_id
             << " seq=" << std::dec << packet.sequence;
        log_line(line.str().c_str());
        ++g_fire_event_ring.tail;
        skip_streak = 0;
        last_skip_seq = 0;
        return;
    }

    // The FirePacket snapshot is captured before the sender's native shot
    // consumes ammo. Mirror it only into the retained puppet's matching live
    // ProcessWeapon; the receiver-local player (retained slot 0) is never touched.
    bool ammo_applied = apply_fire_packet_ammo_to_puppet(puppet, packet);

    const bool peer_has_pistol =
        (peer.flags & 0x80) != 0 &&
        (peer.held_weapon_art_id == kCoopPistolArtId ||
         peer.held_weapon_art_id == kCoopScopedPistolArtId);
    const bool packet_is_rifle = packet.weapon_art_id == kCoopRifleArtId;

    if (!puppet_can_fire_art(puppet, packet.weapon_art_id)) {
        const int local_gun = read_gun_state(puppet);
        if (local_gun >= 0 && capture_weapon_selected_mode(puppet) == 0 &&
            puppet_active_weapon_art_id(puppet) == packet.weapon_art_id &&
            peer.gun_state == 1) {
            safe_request_gun_state(puppet, 1);
        }
    }

    const bool fire_ready = puppet_can_fire_art(puppet, packet.weapon_art_id);
    if (!fire_ready) {
        if (packet.sequence == last_skip_seq) {
            ++skip_streak;
        } else {
            last_skip_seq = packet.sequence;
            skip_streak = 1;
        }
        const ULONGLONG now = GetTickCount64();
        if (now - last_not_ready > 2000) {
            last_not_ready = now;
            std::ostringstream line;
            line << "FIRE-RELAY skip: puppet not ready seq=" << packet.sequence
                 << " art=0x" << std::hex << packet.weapon_art_id
                 << " active=0x" << puppet_active_weapon_art_id(puppet)
                 << " mode=" << std::dec
                 << static_cast<unsigned>(capture_weapon_selected_mode(puppet));
            log_line(line.str().c_str());
        }
        if (skip_streak >= 120) {
            std::ostringstream line;
            line << "FIRE-RELAY drop: stale seq=" << packet.sequence
                 << " art=0x" << std::hex << packet.weapon_art_id << std::dec;
            log_line(line.str().c_str());
            ++g_fire_event_ring.tail;
            skip_streak = 0;
            last_skip_seq = 0;
            return;
        }
        // Fall through to button fallback for all weapons when puppet not ready.
    } else {
        skip_streak = 0;
        last_skip_seq = 0;
    }

    if (fire_ready && peer.gun_state == 1 &&
        (puppet_can_fire_art(puppet, packet.weapon_art_id) ||
         coop_fire_art_family_match(packet.weapon_art_id,
                                    puppet_active_weapon_art_id(puppet)))) {
        const int hands = read_weapon_in_hands_slot(puppet);
        if (hands > 0) {
            g_puppet_gun_ok_puppet = puppet;
            g_puppet_gun_ok_art = puppet_active_weapon_art_id(puppet);
            g_puppet_gun_ok_until_ms = GetTickCount64() + 5000;
        }
    }

    // Pose-only may still use the one-shot button fallback below. Native
    // PlayerFireController::Fire replay stays behind full puppet ADS (F8) because
    // the unaimed native replay previously crashed one tick later.
    if (g_native_fire_relay && g_puppet_relay_aim_press &&
        g_original_player_fire != nullptr &&
        is_coop_native_fire_art(packet.weapon_art_id) &&
        puppet_native_fire_relay_ready(puppet, packet.weapon_art_id)) {
        static void* last_native_puppet = nullptr;
        static ULONGLONG last_native_fire_ms = 0;
        const ULONGLONG now = GetTickCount64();
        const bool rate_ok =
            puppet != last_native_puppet || now - last_native_fire_ms >= 100;
        if (rate_ok) {
            const std::ptrdiff_t preferred_offset =
                packet.controller_offset > 0
                    ? static_cast<std::ptrdiff_t>(packet.controller_offset)
                    : -1;
            void* const controller =
                resolve_fire_controller(puppet, preferred_offset);
            void* weapon = get_player_active_weapon(puppet);
            if (weapon == nullptr) {
                const int slot = find_weapon_slot_by_art_id(
                    puppet, packet.weapon_art_id);
                if (slot >= 0) {
                    weapon = get_weapon_from_slot(puppet, slot);
                }
            }
            const std::uint32_t weapon_art =
                weapon != nullptr && readable_bytes(weapon) >= 0x864
                    ? weapon_art_id_from_object(weapon)
                    : 0;
            if (controller != nullptr && weapon != nullptr &&
                readable_bytes(controller) >= 0x110 &&
                readable_bytes(weapon) >= 0x864 &&
                player_object_stable(puppet) &&
                coop_fire_art_family_match(weapon_art, packet.weapon_art_id)) {
                suppress_puppet_fire_buttons(400);
                alignas(16) std::uint8_t args[coop::kFireArgsBytes]{};
                prepare_puppet_fire_args_from_sender(
                    puppet, packet.fire_args, args);
                g_puppet_aim_ray_override = true;
                g_pose_seed_fire_only_override = true;
                const bool fired = safe_replay_player_fire(
                    controller, args, weapon, packet.scalar);
                g_pose_seed_fire_only_override = false;
                g_puppet_aim_ray_override = false;
                if (fired) {
                    last_native_puppet = puppet;
                    last_native_fire_ms = now;
                    std::int16_t post_magazine = -1;
                    std::int16_t post_reserve = -1;
                    (void)read_process_weapon_ammo(
                        weapon, post_magazine, post_reserve);
                    std::ostringstream line;
                    line << "FIRE-RELAY native seq=" << packet.sequence
                         << " art=0x" << std::hex << packet.weapon_art_id
                         << " hands=" << std::dec
                         << read_weapon_in_hands_slot(puppet)
                         << " ammoPost=" << post_magazine << '/'
                         << post_reserve;
                    boot_log_line(line.str().c_str());
                    ++g_fire_event_ring.tail;
                    return;
                }
                g_suppress_puppet_fire_buttons_until_ms = 0;
                std::ostringstream fail;
                fail << "FIRE-RELAY native-fail seq=" << packet.sequence
                     << " art=0x" << std::hex << packet.weapon_art_id
                     << std::dec;
                log_line(fail.str().c_str());
            }
        }
    } else if (g_native_fire_relay && g_puppet_relay_aim_press &&
               is_coop_native_fire_art(packet.weapon_art_id)) {
        static ULONGLONG last_native_skip_log = 0;
        const ULONGLONG now = GetTickCount64();
        if (now - last_native_skip_log > 2000) {
            last_native_skip_log = now;
            const int gun = read_gun_state(puppet);
            std::ostringstream line;
            line << "FIRE-RELAY native-skip: not fire-ready gun=" << gun
                 << " active=0x" << std::hex
                 << puppet_active_weapon_art_id(puppet)
                 << " mode=" << std::dec
                 << static_cast<unsigned>(capture_weapon_selected_mode(puppet));
            log_line(line.str().c_str());
        }
    }

    // Arm inventory/draw before button pulse — never rifle arm when peer holds pistol.
    if (!peer_has_pistol || !packet_is_rifle) {
        if (!puppet_has_weapon_art_id(puppet, packet.weapon_art_id)) {
            safe_give_weapon_art_to_puppet(puppet, packet.weapon_art_id);
        }
        if (!puppet_can_fire_art(puppet, packet.weapon_art_id)) {
            int arm_slot = find_weapon_slot_by_art_id(puppet, packet.weapon_art_id);
            if (arm_slot < 0 && peer.weapon_selected_mode > 0) {
                arm_slot = static_cast<int>(peer.weapon_selected_mode);
            }
            if (arm_slot > 0 &&
                puppet_weapon_switch_allowed(packet.weapon_art_id, arm_slot)) {
                safe_switch_to_weapon(
                    puppet, static_cast<std::uint32_t>(arm_slot), true);
            }
        }
    }

    if (!ammo_applied) {
        (void)apply_fire_packet_ammo_to_puppet(puppet, packet);
    }

    // Button fallback keeps the receiver-local owner/weapon state. The sender's
    // selected SpawnInfo launch direction and origin are queued until the
    // receiver's selected record is known at ProcessWeapon::SpawnProjectile.
    if ((packet.flags & coop::kFireFlagFinalDirection) != 0) {
        PeerFireDirectionCapture direction_capture{};
        std::memcpy(
            direction_capture.final_direction, packet.final_direction,
            sizeof(direction_capture.final_direction));
        if ((packet.flags & coop::kFireFlagFinalOrigin) != 0) {
            std::memcpy(
                direction_capture.final_origin, packet.final_origin,
                sizeof(direction_capture.final_origin));
            direction_capture.has_final_origin = true;
        }
        direction_capture.weapon_art_id = packet.weapon_art_id;
        direction_capture.sequence = packet.sequence;
        direction_capture.armed_ms = GetTickCount64();
        if (finite_fire_direction_capture(direction_capture)) {
            enqueue_peer_fire_direction(direction_capture);
            static std::atomic<bool> first_arm_logged{false};
            if (!first_arm_logged.exchange(true, std::memory_order_acq_rel)) {
                char line[128]{};
                std::snprintf(
                    line, sizeof(line),
                    "FIRE-FINAL-LAUNCH-ARM seq=%u art=0x%08X origin=%u",
                    direction_capture.sequence,
                    direction_capture.weapon_art_id,
                    finite_fire_origin_capture(direction_capture) ? 1U : 0U);
                boot_log_line(line);
            }
        }
    }
    constexpr std::uint64_t kFireOnlyMask = kJoypadFireButtonMask;
    const std::uint64_t fire_pulse = kFireOnlyMask;
    g_state_net.pending_button_presses.fetch_or(fire_pulse, std::memory_order_release);
    g_state_net.active_button_press_latch.fetch_or(fire_pulse, std::memory_order_release);
    g_fire_button_hold_until_ms = GetTickCount64() + 150;
    std::ostringstream line;
    line << "FIRE-RELAY button seq=" << packet.sequence
         << " art=0x" << std::hex << packet.weapon_art_id
         << " pulse=0x" << fire_pulse << std::dec;
    force_log_line(line.str().c_str());
    ++g_fire_event_ring.tail;
}

void __fastcall hooked_player_fire(
    void* controller,
    void* fire_args,
    void* weapon,
    double scalar
) {
    static std::atomic<unsigned> captured{0};
    const unsigned index = captured.fetch_add(1, std::memory_order_relaxed);
    if (index < 16 && controller != nullptr && fire_args != nullptr &&
        weapon != nullptr && readable_bytes(controller) >= 0x110 &&
        readable_bytes(fire_args) >= 0x100 && readable_bytes(weapon) >= 0x220) {
        void* const player = *reinterpret_cast<void**>(
            static_cast<std::byte*>(controller) + 0x108);
        const std::uint32_t weapon_word_218 = *reinterpret_cast<const std::uint32_t*>(
            static_cast<const std::byte*>(weapon) + 0x218);
        std::uint64_t scalar_bits = 0;
        std::memcpy(&scalar_bits, &scalar, sizeof(scalar_bits));
        const auto* words = reinterpret_cast<const std::uint32_t*>(fire_args);
        std::ostringstream line;
        line << "PLAYER-FIRE #" << index << std::hex
             << " controller=0x" << reinterpret_cast<std::uintptr_t>(controller)
             << " player=0x" << reinterpret_cast<std::uintptr_t>(player)
             << " weapon=0x" << reinterpret_cast<std::uintptr_t>(weapon)
             << " weaponWord218=0x" << weapon_word_218
             << " args=0x" << reinterpret_cast<std::uintptr_t>(fire_args)
             << " scalarBits=0x" << scalar_bits
             << " raw=";
        for (std::size_t i = 0; i < 0x100 / sizeof(std::uint32_t); ++i) {
            line << words[i];
            if (i + 1 != 0x100 / sizeof(std::uint32_t)) line << ',';
        }
        log_line(line.str().c_str());
    }
    void* const player = (controller != nullptr &&
                          readable_bytes(controller) >=
                              kPlayerFireControllerOwnerOffset + sizeof(void*))
        ? *reinterpret_cast<void**>(
              static_cast<std::byte*>(controller) + kPlayerFireControllerOwnerOffset)
        : nullptr;
    bool local_fire_packet_prepared = false;
    if (!g_net_role_b && player == retained_player_object(0)) {
        if (g_player_fire_controller_offset < 0) {
            g_player_fire_controller_offset =
                static_cast<std::byte*>(controller) - static_cast<std::byte*>(player);
            std::ostringstream line;
            line << "FIRE-RELAY learned controller offset=0x" << std::hex
                 << g_player_fire_controller_offset << std::dec;
            log_line(line.str().c_str());
        }
        coop::FirePacket local_fire_packet{};
        local_fire_packet_prepared = prepare_fire_packet(
            controller, fire_args, weapon, scalar,
            local_fire_packet);
        if (local_fire_packet_prepared) {
            enqueue_pending_local_fire_packet(local_fire_packet);
        }
        static std::atomic<bool> first_packet_prep_logged{false};
        if (!first_packet_prep_logged.exchange(true, std::memory_order_acq_rel)) {
            char line[256]{};
            std::snprintf(
                line, sizeof(line),
                "FIRE-PACKET-PREP ok=%u tid=%lu enabled=%u peer=%u "
                "ctrl=%u args=%u weapon=%u owner0=%u",
                local_fire_packet_prepared ? 1U : 0U,
                static_cast<unsigned long>(GetCurrentThreadId()),
                g_state_net.enabled ? 1U : 0U,
                g_state_net.peer_set ? 1U : 0U,
                controller != nullptr ? 1U : 0U,
                fire_args != nullptr ? 1U : 0U,
                weapon != nullptr ? 1U : 0U,
                player == retained_player_object(0) ? 1U : 0U);
            boot_log_line(line);
        }
    }
    const bool puppet_fire =
        g_puppet_relay_pose_seed && g_state_net.enabled &&
        player == retained_player_object(1);
    if (puppet_fire) {
        g_puppet_aim_ray_override = true;
        g_pose_seed_fire_only_override = true;
        prepare_puppet_fire_args_from_sender(player, nullptr, nullptr);
        apply_peer_quat_to_fire_args(fire_args);
        apply_peer_pose_seed_to_player_aim_fields(player);
    }
    g_original_player_fire(controller, fire_args, weapon, scalar);
    if (puppet_fire) {
        g_puppet_aim_ray_override = false;
        g_pose_seed_fire_only_override = false;
    }
}

void log_player_fire_gate(
    const char* gate,
    void* controller,
    bool result
) {
    if (controller == nullptr || readable_bytes(controller) < 0x1EA) {
        return;
    }
    const auto* const bytes = static_cast<const std::byte*>(controller);
    const unsigned hold = static_cast<unsigned>(
        *reinterpret_cast<const std::uint8_t*>(bytes + 0x1E8));
    const unsigned press = static_cast<unsigned>(
        *reinterpret_cast<const std::uint8_t*>(bytes + 0x1E9));
    if (hold == 0 && press == 0) {
        return;
    }
    void* const player = *reinterpret_cast<void* const*>(bytes + 0x108);
    void* weapon = get_player_active_weapon(player);
    std::uint32_t art = 0;
    if (weapon != nullptr && readable_bytes(weapon) >= 0x864) {
        art = *reinterpret_cast<const std::uint32_t*>(
            static_cast<const std::byte*>(weapon) + 0x860);
    }
    int state_120 = -999;
    int current_slot = -999;
    int requested_slot = -999;
    int switch_state = -999;
    if (player != nullptr && readable_bytes(player) >= 0x1D90) {
        void* const weapon_controller = *reinterpret_cast<void* const*>(
            static_cast<const std::byte*>(player) + 0x1D88);
        if (weapon_controller != nullptr &&
            readable_bytes(weapon_controller) >= 0x138) {
            const auto* const wc = static_cast<const std::byte*>(weapon_controller);
            state_120 = *reinterpret_cast<const int*>(wc + 0x120);
            current_slot = static_cast<int>(
                *reinterpret_cast<const std::uint8_t*>(wc + 0x12C));
            requested_slot = *reinterpret_cast<const int*>(wc + 0x130);
            switch_state = *reinterpret_cast<const int*>(wc + 0x134);
        }
    }
    std::ostringstream line;
    line << "FIRE-GATE " << gate
         << " result=" << (result ? 1 : 0)
         << " hold=" << hold << " press=" << press
         << " player=0x" << std::hex
         << reinterpret_cast<std::uintptr_t>(player)
         << " weapon=0x" << reinterpret_cast<std::uintptr_t>(weapon)
         << " art=0x" << art << std::dec
         << " state120=" << state_120
         << " current=" << current_slot
         << " requested=" << requested_slot
         << " switchState=" << switch_state
         << " attached="
         << static_cast<unsigned>(capture_weapon_selected_mode(player));
    log_line(line.str().c_str());
}

char __fastcall hooked_player_try_start_fire(void* controller) {
    if (controller != nullptr && readable_bytes(controller) >= 0x110) {
        void* const player = *reinterpret_cast<void* const*>(
            static_cast<const std::byte*>(controller) + 0x108);
        if (player == retained_player_object(1) &&
            puppet_fire_buttons_suppressed()) {
            return 0;
        }
    }
    const char result = g_original_player_try_start_fire(controller);
    if (controller != nullptr && readable_bytes(controller) >= 0x110) {
        void* const player = *reinterpret_cast<void* const*>(
            static_cast<const std::byte*>(controller) + 0x108);
        if (player == retained_player_object(1)) {
            g_state_net.active_button_press_latch.fetch_and(
                ~kJoypadFireButtonMask, std::memory_order_release);
            void* const frame_state =
                *reinterpret_cast<void**>(g_module + 0x3FE1088);
            if (frame_state != nullptr) {
                auto* const joypad3 = static_cast<std::byte*>(frame_state) +
                                      0xDB0 + 0xBF0 * 3;
                if (readable_bytes(joypad3) >= 0xD8) {
                    *reinterpret_cast<std::uint64_t*>(joypad3 + 0xD0) &=
                        ~kJoypadFireButtonMask;
                }
            }
        }
    }
    return result;
}

char __fastcall hooked_player_check_shot_readiness(
    void* controller,
    void* context,
    double time_value
) {
    if (controller != nullptr && readable_bytes(controller) >= 0x110) {
        void* const player = *reinterpret_cast<void* const*>(
            static_cast<const std::byte*>(controller) + 0x108);
        if (player == retained_player_object(1) &&
            puppet_fire_buttons_suppressed()) {
            return 0;
        }
    }
    const char result =
        g_original_player_check_shot_readiness(controller, context, time_value);
    return result;
}


// ============================================================================
// =====  PUPPET DRIVE: SLOT-1 INPUT FEED & PER-SLOT APPLY
// ============================================================================
void probe_velocity_field() {
    static float prev[3]{};
    static bool have_prev = false;
    static ULONGLONG last_log = 0;
    static std::array<float, 32> prev_block0{};
    static bool have_prev_block0 = false;
    void* p = retained_player_object(0);
    if (p == nullptr || readable_bytes(p) < 0xC10) {
        return;
    }
    auto* base = static_cast<std::byte*>(p);
    const auto* pos = reinterpret_cast<const float*>(base + kWorldPositionOffset);
    const float cur[3]{pos[0], pos[1], pos[2]};
    if (!have_prev) {
        std::memcpy(prev, cur, sizeof(prev));
        have_prev = true;
        return;
    }
    const float dx = cur[0] - prev[0];
    const float dz = cur[2] - prev[2];
    std::memcpy(prev, cur, sizeof(prev));
    const float dlen = std::sqrt(dx * dx + dz * dz);
    if (dlen < 0.01F) {
        return;  // not moving this frame
    }
    const ULONGLONG now = GetTickCount64();
    if (now - last_log < 150) {
        return;
    }
    last_log = now;
    const float ndx = dx / dlen;
    const float ndz = dz / dlen;

    // Expected camera-relative stick for this world movement direction:
    // dir = forward*sf + right*sr  =>  sf = dir.forward, sr = dir.right.
    float fx = 0, fz = 1, rx = 1, rz = 0;
    const bool have_cam = get_camera_axes(fx, fz, rx, rz);
    const float sf = ndx * fx + ndz * fz;
    const float sr = ndx * rx + ndz * rz;

    std::ostringstream line;
    line << "velprobe wdir=" << ndx << "," << ndz;
    if (have_cam) {
        line << " stick(sr,sf)=" << sr << "," << sf;
    }
    // Scan a memory object [obj, obj+span) for: W = world-direction vectors
    // matching movement dir (mag 0.3..25), and S = camera-relative stick pairs
    // matching (sr,sf). Labels the section.
    auto scan = [&](const char* label, std::byte* obj, std::size_t span) {
        if (obj == nullptr) {
            return;
        }
        // Clamp the scan to what is actually readable so we never overrun the
        // object into unmapped memory (the background thread has no game-side
        // lifetime guarantees).
        const std::size_t avail = readable_bytes(obj);
        if (avail < 0x20) {
            return;
        }
        if (span > avail - 0x10) {
            span = avail - 0x10;
        }
        line << " " << label << "/W:";
        for (std::size_t off = 0x10; off <= span; off += 4) {
            const auto* v = reinterpret_cast<const float*>(obj + off);
            const float vh = std::sqrt(v[0] * v[0] + v[2] * v[2]);
            if (vh < 0.3F || vh > 25.0F) {
                continue;
            }
            const float dot = (v[0] * ndx + v[2] * ndz) / vh;
            if (dot > 0.97F) {
                line << " +0x" << std::hex << off << std::dec
                     << "(" << v[0] << "," << v[1] << "," << v[2] << ",m" << vh << ")";
            }
        }
        if (have_cam) {
            line << " " << label << "/S:";
            for (std::size_t off = 0x10; off <= span; off += 4) {
                const auto* v = reinterpret_cast<const float*>(obj + off);
                const float a = v[0];
                const float b = v[1];
                const float m = std::sqrt(a * a + b * b);
                if (m < 0.3F || m > 1.3F) {
                    continue;
                }
                const float tol = 0.10F;
                const bool match =
                    (std::abs(a - sr) < tol && std::abs(b - sf) < tol) ||
                    (std::abs(a - sf) < tol && std::abs(b - sr) < tol) ||
                    (std::abs(a + sr) < tol && std::abs(b + sf) < tol) ||
                    (std::abs(a + sf) < tol && std::abs(b + sr) < tol);
                if (match) {
                    line << " +0x" << std::hex << off << std::dec
                         << "(" << a << "," << b << ")";
                }
            }
        }
    };

    scan("P", base, 0xC00);
    // Locomotion controller object pointed to by player+0x15B8 — the likely
    // home of the per-player move intent / desired-move we can inject.
    void* controller = *reinterpret_cast<void**>(base + kLocomotionControllerOffset);
    scan("C", static_cast<std::byte*>(controller), 0x1200);
    // PlayerSnapshot (player+0xb0) — the player's movement/control state object;
    // the control writes the move intent here from input. Scan for the intent.
    void* psnap = *reinterpret_cast<void**>(base + 0xB0);
    scan("PS", static_cast<std::byte*>(psnap), 0x800);
    // Slot-0 input block (0x1466E4220) — find the move-stick field to feed slot 1.
    scan("B0", reinterpret_cast<std::byte*>(g_module + 0x66E4220), 0x300);

    // Also diff the first 0x80 bytes of block[0] across real player movement.
    // The breakpoints on +0/+4 and +0x10/+0x14 stayed silent, so this tells us
    // which offsets actually change on the live keyboard/controller path.
    auto* block0 = reinterpret_cast<float*>(g_module + 0x66E4220);
    if (readable_bytes(block0) >= prev_block0.size() * sizeof(float)) {
        if (!have_prev_block0) {
            std::memcpy(prev_block0.data(), block0, prev_block0.size() * sizeof(float));
            have_prev_block0 = true;
        } else {
            line << " B0diff:";
            int shown = 0;
            for (std::size_t i = 0; i < prev_block0.size() && shown < 16; ++i) {
                const float curv = block0[i];
                const float oldv = prev_block0[i];
                if (std::abs(curv - oldv) > 0.02f) {
                    line << " +0x" << std::hex << (i * sizeof(float)) << std::dec
                         << "(" << oldv << "->" << curv << ")";
                    ++shown;
                }
            }
            std::memcpy(prev_block0.data(), block0, prev_block0.size() * sizeof(float));
        }
    }
    log_line(line.str().c_str());
}

void log_player_slot_positions() {
    static ULONGLONG last_log = 0;
    const ULONGLONG now = GetTickCount64();
    if (now - last_log < 1000) {
        return;
    }
    void* p0 = retained_player_object(0);
    void* p1 = retained_player_object(1);
    if (p0 == nullptr && p1 == nullptr) {
        return;
    }
    last_log = now;
    std::ostringstream line;
    line << "player slots";
    auto add_slot = [&](int slot, void* obj) {
        line << " s" << slot << "=0x" << std::hex << reinterpret_cast<std::uintptr_t>(obj);
        if (obj == nullptr || readable_bytes(obj) < kPlayerVelocityMirrorOffset + 0x10) {
            line << std::dec;
            return;
        }
        auto* base = static_cast<std::byte*>(obj);
        const auto vtable = *reinterpret_cast<std::uintptr_t*>(obj);
        const auto* pos = reinterpret_cast<const float*>(base + kWorldPositionOffset);
        const auto* vel = reinterpret_cast<const float*>(base + kPlayerVelocityOffset);
        line << " vt=0x" << (vtable > g_module ? vtable - g_module : 0)
             << std::dec
             << " pos=(" << pos[0] << "," << pos[1] << "," << pos[2] << ")"
             << " vel=(" << vel[0] << "," << vel[1] << "," << vel[2] << ")";
    };
    add_slot(0, p0);
    add_slot(1, p1);
    log_line(line.str().c_str());
}

// Experimental slot-1 drive path. Runtime showed that clean block[1] feed and
// the FrameState+0x6FC8 branch structs are not cleanly isolated from Chloe, so
// this stays diagnostic only. block[i] = 0x1466E4220 + i*0x530.
volatile bool g_drive_slot1 = false;
volatile bool g_manual_slot1_apply = false;

// Legacy synthetic "input active" gate (0x500) OR-ed into the clone's held button
// mask on movement. It is NOT needed for locomotion (the stick at branch1+0x14..
// drives it; PlayerMoveStick 0x140F03500 ignores bits 0x100/0x400), and once the
// clone became armed its continuous press edge fired the throw/grenade command
// while the peer was just running. Default OFF. F7 toggles at runtime for A/B: if
// the clone ever stops moving with this OFF, flip it back on.
volatile bool g_feed_legacy_move_gate = false;

// Which retained slot the drive feeds (1 = freshly spawned clone; after a
// camera slot-swap the clone becomes slot 0, so we drive slot 0 to test whether
// being "local-player-0" gives it the main-camera movement basis = straight).
volatile int g_drive_slot_index = 1;
// The clone object captured before any swap, so we log ITS position across swaps.
void* g_autotest_clone_obj = nullptr;

// Live-tunable move mapping: rotate the (fx,-fy) move vector by g_move_rot and
// optionally swap axes, so the user can dial in the clone's camera convention in
// game (NUMPAD7/9 = -/+15deg, NUMPAD8 = axis swap) without rebuilds.
volatile float g_move_rot = -1.5707963F;  // radians; measured slot-1 basis correction.
                                        // NUMPAD7/9 retunes live if needed.
volatile bool g_move_swap = false;
volatile float g_desired_world_x = 0.0F;
volatile float g_desired_world_z = 0.0F;
volatile bool g_have_desired_world = false;

void sync_puppet_aim_camera_from_peer(const coop::StatePacket& peer) {
    if (!g_puppet_relay_pose_seed || !g_state_net.enabled || g_module == 0) {
        return;
    }
    const bool peer_aiming = peer_packet_aim_active(peer);
    if (!peer_aiming) {
        return;
    }
    float quat[4]{};
    if (!copy_peer_aim_orientation_quat(quat)) {
        return;
    }
    auto* const cache_base = reinterpret_cast<std::uint8_t*>(
        g_module + kPerScreenCameraTransformCacheRva);
    auto* const screen1_entry =
        cache_base + kPerScreenCameraCacheStride * kSlot1ScreenIndex;
    if (readable_bytes(screen1_entry) >=
        kCameraOutMatrixOffset + 12 * sizeof(float)) {
        __try {
            write_camera_matrix_rotation_from_quat(screen1_entry, quat);
        } __except (EXCEPTION_EXECUTE_HANDLER) {
        }
    }
    const auto get_camera_manager =
        reinterpret_cast<GetCameraManagerFunction>(
            g_module + kGetCameraManagerRva);
    void* const mgr = get_camera_manager(kSlot1ScreenIndex);
    if (mgr != nullptr &&
        readable_bytes(static_cast<std::byte*>(mgr) + 0xB0) >= sizeof(void*)) {
        void* const blk = *reinterpret_cast<void**>(
            static_cast<std::byte*>(mgr) + 0xB0);
        if (blk != nullptr &&
            readable_bytes(static_cast<std::byte*>(blk) + 0x60) >= 32) {
            __try {
                std::uint8_t seed[32]{};
                if (copy_peer_pose_seed_32(seed)) {
                    std::memcpy(static_cast<std::byte*>(blk) + 0x60, seed, 32);
                } else {
                    std::memcpy(static_cast<std::byte*>(blk) + 0x70, quat, 16);
                }
            } __except (EXCEPTION_EXECUTE_HANDLER) {
            }
        }
        if (readable_bytes(static_cast<std::byte*>(mgr) + kCameraRotationOffset) >=
            16) {
            __try {
                std::memcpy(
                    static_cast<std::byte*>(mgr) + kCameraRotationOffset, quat,
                    16);
            } __except (EXCEPTION_EXECUTE_HANDLER) {
            }
        }
    }
}

void scrub_puppet_scoped_ads_flag(void* puppet) {
    if (puppet == nullptr ||
        readable_bytes(static_cast<std::byte*>(puppet) + kPlayerAdsActiveOffset) <
            sizeof(std::uint32_t)) {
        return;
    }
    __try {
        *reinterpret_cast<std::uint32_t*>(
            static_cast<std::byte*>(puppet) + kPlayerAdsActiveOffset) = 0;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
    }
}

bool seh_clear_draw_control_child_flags(
    void* draw_control, std::uint32_t mask) {
    using ClearChildFlagsFn = void(__fastcall*)(void*, std::uint32_t);
    __try {
        reinterpret_cast<ClearChildFlagsFn>(
            g_module + kDrawControlClearChildFlagsByMaskRva)(
                draw_control, mask);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

void* draw_control_from_renderable_object(void* object) {
    if (object == nullptr ||
        readable_bytes(static_cast<std::byte*>(object) + 0x1B0) < 1) {
        return nullptr;
    }
    auto* const bytes = static_cast<std::byte*>(object);
    void* const draw_control = *reinterpret_cast<void**>(bytes + 0x198);
    void* const fg_anim = *reinterpret_cast<void**>(bytes + 0x1A8);
    if (draw_control == nullptr || fg_anim == nullptr ||
        readable_bytes(draw_control) < 0x20 ||
        *reinterpret_cast<void**>(draw_control) != fg_anim) {
        return nullptr;
    }
    return draw_control;
}

bool seh_show_draw_control_mesh(void* draw_control, std::uint32_t mesh_index) {
    using ShowMeshFn = std::int64_t(__fastcall*)(void*, std::uint32_t);
    __try {
        reinterpret_cast<ShowMeshFn>(
            g_module + kDrawControlShowMeshRva)(draw_control, mesh_index);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

bool seh_hide_draw_control_mesh(void* draw_control, std::uint32_t mesh_index) {
    using HideMeshFn = std::int64_t(__fastcall*)(void*, std::uint32_t);
    __try {
        reinterpret_cast<HideMeshFn>(
            g_module + kDrawControlHideMeshRva)(draw_control, mesh_index);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

unsigned restore_hidden_draw_control_meshes(void* draw_control) {
    if (draw_control == nullptr || readable_bytes(draw_control) < 0x20) {
        return 0;
    }
    auto* const dc = static_cast<std::byte*>(draw_control);
    auto* const meshes = *reinterpret_cast<std::byte**>(dc + 0x8);
    const std::uint32_t mesh_count =
        *reinterpret_cast<const std::uint32_t*>(dc + 0x14);
    constexpr std::size_t kDrawControlMeshStride = 0x250;
    constexpr std::size_t kMeshVisibleByteOffset = 0x243;
    if (meshes == nullptr || mesh_count == 0 || mesh_count > 128 ||
        readable_bytes(meshes) < kDrawControlMeshStride) {
        return 0;
    }

    unsigned restored = 0;
    for (std::uint32_t mesh_index = 0; mesh_index < mesh_count; ++mesh_index) {
        auto* const mesh = meshes + kDrawControlMeshStride * mesh_index;
        if (readable_bytes(mesh) < kDrawControlMeshStride) {
            break;
        }
        if (*reinterpret_cast<const std::uint8_t*>(
                mesh + kMeshVisibleByteOffset) == 0xFF) {
            continue;
        }
        if (!seh_show_draw_control_mesh(draw_control, mesh_index)) {
            break;
        }
        ++restored;
    }
    return restored;
}

void keep_puppet_scoped_mesh_visible(
    void* puppet, const coop::StatePacket& peer) {
    if (puppet == nullptr || !puppet_aim_press_relay_enabled_for_peer(peer) ||
        !peer_packet_aim_active(peer) ||
        readable_bytes(static_cast<std::byte*>(puppet) + 0x1B0) < 1) {
        return;
    }

    void* const player_draw = draw_control_from_renderable_object(puppet);
    if (player_draw == nullptr) {
        return;
    }

    constexpr std::uint32_t kExcludedFromMainView = 0x40;
    if (!seh_clear_draw_control_child_flags(player_draw, kExcludedFromMainView)) {
        return;
    }

    unsigned restored_player_meshes = 0;
    unsigned restored_weapon_meshes = 0;
    unsigned restored_weapon_controls = 0;
    if (peer_holds_scoped_rifle(peer)) {
        // Scoped ADS separately hides Player meshes (including hair) and the held
        // weapon renderable. Restore only validated DrawControls while ADS is live.
        restored_player_meshes = restore_hidden_draw_control_meshes(player_draw);
        std::array<void*, 3> weapon_candidates{
            get_player_active_weapon(puppet), nullptr, nullptr};
        const int in_hands_slot = read_weapon_in_hands_slot(puppet);
        const int attached_slot = capture_hand_attached_slot_int(puppet);
        if (in_hands_slot >= 0) {
            weapon_candidates[1] = get_weapon_from_slot(puppet, in_hands_slot);
        }
        if (attached_slot >= 0) {
            weapon_candidates[2] = get_weapon_from_slot(puppet, attached_slot);
        }
        for (std::size_t i = 0; i < weapon_candidates.size(); ++i) {
            void* const weapon = weapon_candidates[i];
            if (weapon == nullptr) {
                continue;
            }
            bool duplicate = false;
            for (std::size_t previous = 0; previous < i; ++previous) {
                duplicate = duplicate || weapon_candidates[previous] == weapon;
            }
            if (duplicate) {
                continue;
            }
            void* const weapon_draw =
                draw_control_from_renderable_object(weapon);
            if (weapon_draw == nullptr ||
                !seh_clear_draw_control_child_flags(
                    weapon_draw, kExcludedFromMainView)) {
                continue;
            }
            ++restored_weapon_controls;
            restored_weapon_meshes +=
                restore_hidden_draw_control_meshes(weapon_draw);
        }
    }

    static ULONGLONG last_log = 0;
    const ULONGLONG now = GetTickCount64();
    if (now - last_log > 500) {
        last_log = now;
        std::ostringstream line;
        line << "PUPPET-ADS-VISIBILITY playerMeshes="
             << restored_player_meshes
             << " weaponMeshes=" << restored_weapon_meshes
             << " weaponControls=" << restored_weapon_controls;
        force_log_line(line.str().c_str());
    }
}

bool peer_holds_scoped_rifle(const coop::StatePacket& peer) {
    const std::uint32_t art = peer_effective_held_art(peer);
    return is_long_gun_relay_art(art);
}

using PlayerMainViewVisibilityUpdateFunction = char(__fastcall*)(void*);
PlayerMainViewVisibilityUpdateFunction
    g_original_player_main_view_visibility_update = nullptr;

bool player_is_remote_screen_slot(const void* player) {
    if (player == nullptr ||
        readable_bytes(static_cast<const std::byte*>(player) + 0x4014) <
            sizeof(std::uint32_t)) {
        return false;
    }
    return *reinterpret_cast<const std::uint32_t*>(
               static_cast<const std::byte*>(player) + 0x4010) ==
           kSlot1ScreenIndex;
}

bool seh_force_remote_player_main_view_visible(
    void* player, std::uint8_t* previous_request) {
    __try {
        auto* const current = reinterpret_cast<std::uint8_t*>(
            static_cast<std::byte*>(player) + 0x1618);
        *previous_request = current[1];
        const bool suppressed = current[0] == 0;
        current[0] = 1;
        return suppressed;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

char __fastcall hooked_player_main_view_visibility_update(void* player) {
    bool suppressed_remote_hide = false;
    std::uint8_t previous_request = 0;
    if (player_is_remote_screen_slot(player) &&
        readable_bytes(static_cast<std::byte*>(player) + 0x161A) >= 1) {
        // Identify by authored screen index, not retained pointer. During a
        // location rebuild this function can run on the new Player before the
        // retained-slot table points at it; the old pointer gate missed that hide
        // and both copies subsequently saw a bald remote Chloe.
        suppressed_remote_hide = seh_force_remote_player_main_view_visible(
            player, &previous_request);
    }

    const char result = g_original_player_main_view_visibility_update != nullptr
        ? g_original_player_main_view_visibility_update(player)
        : 0;
    if (suppressed_remote_hide) {
        static ULONGLONG last_log = 0;
        const ULONGLONG now = GetTickCount64();
        if (now - last_log > 500) {
            last_log = now;
            std::ostringstream line;
            line << "PUPPET-MAIN-VIEW-HIDE suppressed previous="
                 << static_cast<unsigned>(previous_request);
            force_log_line(line.str().c_str());
        }
    }
    return result;
}

bool install_player_main_view_visibility_relay() {
    constexpr std::array<std::uint8_t, 15> expected{
        0x48, 0x89, 0x5C, 0x24, 0x10,
        0x48, 0x89, 0x74, 0x24, 0x18,
        0x48, 0x89, 0x7C, 0x24, 0x20,
    };
    g_original_player_main_view_visibility_update =
        reinterpret_cast<PlayerMainViewVisibilityUpdateFunction>(
            install_fire_gate_detour(
                kPlayerMainViewVisibilityUpdateRva,
                expected.data(), expected.size(),
                reinterpret_cast<void*>(
                    &hooked_player_main_view_visibility_update),
                "Player main-view visibility relay"));
    boot_log_line(g_original_player_main_view_visibility_update != nullptr
                      ? "Player main-view visibility relay installed"
                      : "Player main-view visibility relay SKIPPED");
    return g_original_player_main_view_visibility_update != nullptr;
}

void sync_screen1_camera_rotation_to_screen0() {
    const auto get_camera_manager =
        reinterpret_cast<GetCameraManagerFunction>(
            g_module + kGetCameraManagerRva
        );
    void* const cam0 = get_camera_manager(0);
    void* const cam1 = get_camera_manager(1);
    if (cam0 == nullptr || cam1 == nullptr) {
        return;
    }
    auto* c0 = static_cast<std::byte*>(cam0);
    auto* c1 = static_cast<std::byte*>(cam1);
    if (readable_bytes(c0 + kCameraRotationOffset) < 0x60 ||
        readable_bytes(c1 + kCameraRotationOffset) < 0x60) {
        return;
    }
    std::memcpy(c1 + kCameraRotationOffset, c0 + kCameraRotationOffset, 16);
    std::memcpy(c1 + 0x200, c0 + 0x200, 16);
}

