using DrawControlSyncParentVisibilityFunction =
    char(__fastcall*)(void*, void*);
DrawControlSyncParentVisibilityFunction
    g_original_draw_control_sync_parent_visibility = nullptr;

struct AttachmentDrawSnapshot {
    std::uint32_t flags = 0;
    std::uint32_t mesh_count = 0;
    std::uint32_t readable_meshes = 0;
    std::uint32_t primary_gate_meshes = 0;
    std::uint32_t secondary_gate_meshes = 0;
    std::uint32_t instances = 0;
    std::uint32_t active_instances = 0;
    std::uint32_t main_view_excluded_instances = 0;
    std::uint32_t category_suppressed_instances = 0;
    std::uint8_t own_gate = 0;
    std::uint8_t inherited_gate = 0;
    std::array<std::uint32_t, 32> mesh_ids{};
};

bool seh_capture_attachment_draw_snapshot(
    void* draw_control, AttachmentDrawSnapshot& out) {
    __try {
        if (draw_control == nullptr || readable_bytes(draw_control) < 0x20) {
            return false;
        }
        auto* const draw = static_cast<std::byte*>(draw_control);
        out.flags = *reinterpret_cast<const std::uint32_t*>(draw + 0x18);
        out.own_gate = *reinterpret_cast<const std::uint8_t*>(draw + 0x1C);
        out.inherited_gate =
            *reinterpret_cast<const std::uint8_t*>(draw + 0x1D);
        auto* const meshes = *reinterpret_cast<std::byte**>(draw + 0x8);
        out.mesh_count =
            *reinterpret_cast<const std::uint32_t*>(draw + 0x14);
        if (meshes == nullptr || out.mesh_count > 128) {
            return true;
        }

        constexpr std::size_t kMeshStride = 0x250;
        const std::uint32_t inspected_meshes =
            std::min<std::uint32_t>(out.mesh_count, 32);
        for (std::uint32_t mesh_index = 0;
             mesh_index < inspected_meshes; ++mesh_index) {
            auto* const mesh = meshes + kMeshStride * mesh_index;
            if (readable_bytes(mesh) < kMeshStride) {
                break;
            }
            ++out.readable_meshes;
            out.mesh_ids[mesh_index] =
                *reinterpret_cast<const std::uint32_t*>(mesh + 0x18);
            out.primary_gate_meshes +=
                *reinterpret_cast<const std::uint8_t*>(mesh + 0x243) != 0;
            out.secondary_gate_meshes +=
                *reinterpret_cast<const std::uint8_t*>(mesh + 0x245) != 0;

            const std::uint32_t entry_count = std::min<std::uint32_t>(
                *reinterpret_cast<const std::uint8_t*>(mesh + 0x242), 16);
            for (std::uint32_t entry_index = 0;
                 entry_index < entry_count; ++entry_index) {
                auto* const entry = mesh + 0x20 * entry_index;
                if (readable_bytes(entry) < 0x18) {
                    break;
                }
                void* const instance = *reinterpret_cast<void**>(entry);
                void* const retained = *reinterpret_cast<void**>(entry + 0x10);
                if (instance == nullptr || retained == nullptr ||
                    readable_bytes(instance) < 0x1A5) {
                    continue;
                }
                auto* const instance_bytes = static_cast<std::byte*>(instance);
                const std::uint32_t instance_flags =
                    *reinterpret_cast<const std::uint32_t*>(
                        instance_bytes + 0x18);
                ++out.instances;
                out.active_instances +=
                    *reinterpret_cast<const std::uint8_t*>(
                        instance_bytes + 0x1A0) != 0;
                out.main_view_excluded_instances +=
                    (instance_flags & 0x40u) != 0;
                out.category_suppressed_instances +=
                    (*reinterpret_cast<const std::uint8_t*>(
                         instance_bytes + 0x1A4) &
                     8u) != 0;
            }
        }
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

std::uint64_t attachment_draw_snapshot_signature(
    const AttachmentDrawSnapshot& snapshot, std::uint32_t look_id,
    std::uint32_t state_id) {
    std::uint64_t signature = 1469598103934665603ULL;
    const auto mix = [&signature](std::uint64_t value) {
        signature ^= value;
        signature *= 1099511628211ULL;
    };
    mix(look_id);
    mix(state_id);
    mix(snapshot.flags);
    mix(snapshot.mesh_count);
    mix(snapshot.readable_meshes);
    mix(snapshot.primary_gate_meshes);
    mix(snapshot.secondary_gate_meshes);
    mix(snapshot.instances);
    mix(snapshot.active_instances);
    mix(snapshot.main_view_excluded_instances);
    mix(snapshot.category_suppressed_instances);
    mix(snapshot.own_gate);
    mix(snapshot.inherited_gate);
    for (std::uint32_t mesh_index = 0;
         mesh_index < snapshot.readable_meshes; ++mesh_index) {
        mix(snapshot.mesh_ids[mesh_index]);
    }
    return signature;
}

struct PlayerLookSnapshot {
    std::uint32_t look_id = 0;
    std::uint32_t state_id = 0;
    std::uint32_t appearance_id = 0;
    std::uint32_t hat_id_1 = 0;
    std::uint32_t hat_id_2 = 0;
    std::uint32_t tracked_processes = 0;
    std::uint32_t tracked_meshes = 0;
    std::array<std::uint32_t, 16> tracked_mesh_ids{};
};

bool seh_capture_player_look_snapshot(
    void* player, PlayerLookSnapshot& out) {
    __try {
        if (player == nullptr || readable_bytes(player) < 0x1898) {
            return false;
        }
        auto* const bytes = static_cast<std::byte*>(player);
        out.look_id = *reinterpret_cast<const std::uint32_t*>(bytes + 0x170);
        out.state_id = *reinterpret_cast<const std::uint32_t*>(bytes + 0x190);
        out.appearance_id =
            *reinterpret_cast<const std::uint32_t*>(bytes + 0x15A4);
        out.hat_id_1 =
            *reinterpret_cast<const std::uint32_t*>(bytes + 0x15AC);
        out.hat_id_2 =
            *reinterpret_cast<const std::uint32_t*>(bytes + 0x15B0);

        constexpr std::size_t kHatProcessSlotsOffset = 0x1758;
        constexpr std::size_t kHatProcessSlotStride = 0x10;
        constexpr std::size_t kHatMeshSlotsOffset = 0x1858;
        for (std::size_t index = 0; index < 16; ++index) {
            out.tracked_processes +=
                *reinterpret_cast<void* const*>(
                    bytes + kHatProcessSlotsOffset +
                    index * kHatProcessSlotStride) != nullptr;
            const std::uint32_t mesh_id =
                *reinterpret_cast<const std::uint32_t*>(
                    bytes + kHatMeshSlotsOffset +
                    index * sizeof(std::uint32_t));
            out.tracked_mesh_ids[index] = mesh_id;
            out.tracked_meshes += mesh_id != 0;
        }
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

std::uint64_t player_draw_snapshot_signature(
    const AttachmentDrawSnapshot& draw,
    const PlayerLookSnapshot& look) {
    std::uint64_t signature = attachment_draw_snapshot_signature(
        draw, look.look_id, look.state_id);
    const auto mix = [&signature](std::uint64_t value) {
        signature ^= value;
        signature *= 1099511628211ULL;
    };
    mix(look.appearance_id);
    mix(look.hat_id_1);
    mix(look.hat_id_2);
    mix(look.tracked_processes);
    mix(look.tracked_meshes);
    for (const std::uint32_t mesh_id : look.tracked_mesh_ids) {
        mix(mesh_id);
    }
    return signature;
}

constexpr std::array<std::uint32_t, 5> kLegacyNadineParentMeshIds{
    0x6E18DCD5u, 0x4A7DF04Fu, 0xA674E571u, 0x5EAAF523u,
    0xC450A073u};

bool legacy_nadine_parent_draw_matches(
    void* parent_draw, std::byte** meshes_out = nullptr) {
    if (parent_draw == nullptr || readable_bytes(parent_draw) < 0x20) {
        return false;
    }
    auto* const draw = static_cast<std::byte*>(parent_draw);
    auto* const meshes = *reinterpret_cast<std::byte**>(draw + 0x8);
    const std::uint32_t mesh_count =
        *reinterpret_cast<const std::uint32_t*>(draw + 0x14);
    constexpr std::size_t kMeshStride = 0x250;
    constexpr std::size_t kMeshIdOffset = 0x18;
    if (mesh_count != kLegacyNadineParentMeshIds.size() || meshes == nullptr ||
        readable_bytes(meshes) <
            kMeshStride * kLegacyNadineParentMeshIds.size()) {
        return false;
    }
    for (std::size_t i = 0; i < kLegacyNadineParentMeshIds.size(); ++i) {
        if (*reinterpret_cast<const std::uint32_t*>(
                meshes + kMeshStride * i + kMeshIdOffset) !=
            kLegacyNadineParentMeshIds[i]) {
            return false;
        }
    }
    if (meshes_out != nullptr) {
        *meshes_out = meshes;
    }
    return true;
}

void apply_legacy_nadine_parent_mesh_probe(void* parent_draw) {
    // Stable across every logged rebuild of the only renderable Nadine Player
    // look. Requiring the full ordered signature prevents this diagnostic from
    // touching Chloe, ProcessWeapon, hair/cloth attachables or another look.
    std::byte* meshes = nullptr;
    constexpr std::size_t kMeshStride = 0x250;
    constexpr std::size_t kVisibleOffset = 0x243;
    if (!legacy_nadine_parent_draw_matches(parent_draw, &meshes)) {
        return;
    }

    if (process_owns_foreground_window() &&
        (GetAsyncKeyState(VK_F11) & 1) != 0) {
        int next = g_nadine_parent_mesh_probe_index.load(
            std::memory_order_relaxed) + 1;
        if (next >= static_cast<int>(kLegacyNadineParentMeshIds.size())) {
            next = -1;
        }
        g_nadine_parent_mesh_probe_index.store(next, std::memory_order_release);
    }

    const int selected = g_nadine_parent_mesh_probe_index.load(
        std::memory_order_acquire);
    static void* last_draw = nullptr;
    static int last_selected = -1;
    const bool changed = parent_draw != last_draw || selected != last_selected;
    if (changed && parent_draw == last_draw && last_selected >= 0 &&
        last_selected < static_cast<int>(kLegacyNadineParentMeshIds.size())) {
        seh_show_draw_control_mesh(
            parent_draw, static_cast<std::uint32_t>(last_selected));
    }

    bool applied = true;
    if (selected >= 0 &&
        selected < static_cast<int>(kLegacyNadineParentMeshIds.size())) {
        auto* const mesh = meshes != nullptr
            ? meshes + kMeshStride * static_cast<std::size_t>(selected)
            : nullptr;
        if (mesh == nullptr || readable_bytes(mesh) < kMeshStride) {
            applied = false;
        } else if (*reinterpret_cast<const std::uint8_t*>(
                       mesh + kVisibleOffset) != 0) {
            applied = seh_hide_draw_control_mesh(
                parent_draw, static_cast<std::uint32_t>(selected));
        }
    }

    if (changed) {
        std::ostringstream line;
        line << "NADINE-MESH-PROBE index=" << selected;
        if (selected >= 0 &&
            selected < static_cast<int>(kLegacyNadineParentMeshIds.size())) {
            line << " id=0x" << std::hex
                 << kLegacyNadineParentMeshIds[
                        static_cast<std::size_t>(selected)]
                 << std::dec << " hidden=" << (applied ? 1 : 0);
        } else {
            line << " baseline-restored=1";
        }
        force_log_line(line.str().c_str());
    }
    last_draw = parent_draw;
    last_selected = selected;
}

void census_legacy_nadine_attachable(
    void* parent_draw, void* child_draw, void* attachable) {
    if (!legacy_nadine_parent_draw_matches(parent_draw)) {
        return;
    }

    AttachmentDrawSnapshot child{};
    const std::size_t child_readable =
        child_draw != nullptr ? readable_bytes(child_draw) : 0;
    const bool child_snapshot_ok =
        seh_capture_attachment_draw_snapshot(child_draw, child);
    const std::size_t attachable_readable =
        attachable != nullptr ? readable_bytes(attachable) : 0;
    auto* const bytes = static_cast<const std::byte*>(attachable);
    const std::uintptr_t vtable = attachable_readable >= sizeof(std::uintptr_t)
        ? *reinterpret_cast<const std::uintptr_t*>(bytes)
        : 0;
    const std::uintptr_t vtable_rva =
        g_module != 0 && vtable >= g_module ? vtable - g_module : vtable;
    const std::uint32_t type_id = attachable_readable >= 0x3C
        ? *reinterpret_cast<const std::uint32_t*>(bytes + 0x38)
        : 0;
    const void* const parent_handle = attachable_readable >= 0x4EC
        ? *reinterpret_cast<void* const*>(bytes + 0x4E0)
        : nullptr;
    const std::uint32_t parent_id = attachable_readable >= 0x4EC
        ? *reinterpret_cast<const std::uint32_t*>(bytes + 0x4E8)
        : 0;
    const void* resolved_parent = nullptr;
    std::uint32_t resolved_parent_id = 0;
    if (parent_handle != nullptr && readable_bytes(parent_handle) >= 0x10) {
        resolved_parent = *reinterpret_cast<void* const*>(
            static_cast<const std::byte*>(parent_handle) + 0x8);
        if (resolved_parent != nullptr &&
            readable_bytes(static_cast<const std::byte*>(resolved_parent) + 0xC0) >=
                1) {
            resolved_parent_id = *reinterpret_cast<const std::uint32_t*>(
                static_cast<const std::byte*>(resolved_parent) + 0xBC);
        }
    }
    std::uint32_t art_candidate = 0;
    if (attachable_readable >= 0x864) {
        art_candidate = *reinterpret_cast<const std::uint32_t*>(bytes + 0x860);
    }

    std::uint64_t signature = 1469598103934665603ULL;
    auto mix = [&signature](std::uint64_t value) {
        signature ^= value;
        signature *= 1099511628211ULL;
    };
    mix(vtable_rva);
    mix(type_id);
    mix(parent_id);
    mix(art_candidate);
    mix(child_snapshot_ok ? 1 : 0);
    mix(child.mesh_count);
    for (std::uint32_t i = 0; i < child.readable_meshes; ++i) {
        mix(child.mesh_ids[i]);
    }
    if (signature == 0) {
        signature = 1;
    }

    if (vtable_rva == kProcessWeaponVtableRva && art_candidate != 0) {
        void* anim_data = nullptr;
        if (child_draw != nullptr && readable_bytes(child_draw) >= sizeof(void*)) {
            anim_data = *reinterpret_cast<void**>(child_draw);
        }
        publish_nadine_weapon_candidate(
            attachable, parent_draw, anim_data, nullptr, art_candidate,
            child.readable_meshes != 0 ? child.mesh_ids[0] : 0);
    }

    static std::array<std::atomic<std::uint64_t>, 32> seen{};
    std::atomic<std::uint64_t>* claimed = nullptr;
    for (auto& slot : seen) {
        std::uint64_t current = slot.load(std::memory_order_relaxed);
        if (current == signature) {
            return;
        }
        if (current == 0 && slot.compare_exchange_strong(
                                current, signature,
                                std::memory_order_relaxed)) {
            claimed = &slot;
            break;
        }
    }
    if (claimed == nullptr) {
        return;
    }

    std::ostringstream line;
    line << "NADINE-ATTACHABLE-HIT object=0x" << std::hex
         << reinterpret_cast<std::uintptr_t>(attachable)
         << " vtableRva=0x" << vtable_rva
         << " type=0x" << type_id
         << " childDraw=0x" << reinterpret_cast<std::uintptr_t>(child_draw)
         << " parentHandle=0x" << reinterpret_cast<std::uintptr_t>(parent_handle)
         << "/0x" << parent_id
         << " resolvedParent=0x"
         << reinterpret_cast<std::uintptr_t>(resolved_parent)
         << "/0x" << resolved_parent_id
         << " artCandidate=0x" << art_candidate << std::dec
         << " attachReadable=" << attachable_readable
         << " childReadable=" << child_readable
         << " snapshot=" << (child_snapshot_ok ? 1 : 0)
         << " meshes=" << child.readable_meshes << "/" << child.mesh_count
         << " drawIds=";
    for (std::uint32_t i = 0; i < child.readable_meshes; ++i) {
        line << "0x" << std::hex << child.mesh_ids[i] << ",";
    }
    // Production keeps force_log_line() compiled out. This census is already
    // bounded to 32 semantic signatures, so use the persistent writer directly
    // without enabling the high-volume legacy diagnostics.
    write_log_line(line.str().c_str());
}

void enforce_local_nadine_inactive_rifle_late_visibility(
    void* child_draw, void* attachable) {
    const std::uintptr_t target =
        g_local_nadine_inactive_rifle_weapon.load(
            std::memory_order_acquire);
    if (target == 0 ||
        reinterpret_cast<std::uintptr_t>(attachable) != target ||
        attachable == nullptr || child_draw == nullptr ||
        weapon_art_id_from_object(attachable) != kCoopRifleArtId ||
        readable_bytes(static_cast<std::byte*>(attachable) + 0x1A0) < 1 ||
        *reinterpret_cast<void**>(
            static_cast<std::byte*>(attachable) + 0x198) != child_draw ||
        readable_bytes(child_draw) < 0x20) {
        return;
    }

    auto* const draw = static_cast<std::byte*>(child_draw);
    auto* const meshes = *reinterpret_cast<std::byte**>(draw + 0x8);
    const std::uint32_t mesh_count =
        *reinterpret_cast<const std::uint32_t*>(draw + 0x14);
    constexpr std::size_t kMeshStride = 0x250;
    constexpr std::size_t kVisibleOffset = 0x243;
    if (meshes == nullptr || mesh_count == 0 || mesh_count > 64 ||
        readable_bytes(meshes) < kMeshStride) {
        return;
    }

    std::uint64_t changed_mask = 0;
    for (std::uint32_t mesh_index = 0; mesh_index < mesh_count; ++mesh_index) {
        auto* const mesh = meshes + kMeshStride * mesh_index;
        if (readable_bytes(mesh) < kMeshStride) {
            break;
        }
        if (*reinterpret_cast<const std::uint8_t*>(
                mesh + kVisibleOffset) != 0 &&
            seh_hide_draw_control_mesh(child_draw, mesh_index) &&
            *reinterpret_cast<const std::uint8_t*>(
                mesh + kVisibleOffset) == 0) {
            changed_mask |= 1ULL << mesh_index;
        }
    }
    if (changed_mask == 0) {
        return;
    }

    const std::uint64_t generation =
        g_local_nadine_inactive_rifle_generation.load(
            std::memory_order_acquire);
    static std::atomic<std::uint64_t> logged_generation{0};
    std::uint64_t previous = logged_generation.load(
        std::memory_order_relaxed);
    if (previous == generation ||
        !logged_generation.compare_exchange_strong(
            previous, generation, std::memory_order_relaxed)) {
        return;
    }

    std::ostringstream line;
    line << "NADINE-LOCAL-RIFLE-VIS owner=0 weapon=0x" << std::hex
         << target << " draw=0x"
         << reinterpret_cast<std::uintptr_t>(child_draw)
         << " action=late-hide changed=0x" << changed_mask << std::dec
         << " generation=" << generation
         << " meshes=" << mesh_count;
    write_log_line(line.str().c_str());
}

char __fastcall hooked_nd_attachable_sync_parent_visibility_callsite(
    void* child_draw, void* parent_draw, void* attachable) {
    char result = g_original_draw_control_sync_parent_visibility != nullptr
        ? g_original_draw_control_sync_parent_visibility(child_draw, parent_draw)
        : 0;

    if constexpr (kEnableNadineParentMeshProbe) {
        apply_legacy_nadine_parent_mesh_probe(parent_draw);
    }
    if constexpr (kEnableRejectedNadineWeaponRuntimeProbes) {
        census_legacy_nadine_attachable(parent_draw, child_draw, attachable);
        enforce_local_nadine_inactive_rifle_late_visibility(
            child_draw, attachable);
    }

    void* const puppet = retained_player_object(1);
    if (!g_state_net.enabled || puppet == nullptr ||
        !player_is_remote_screen_slot(puppet) ||
        readable_bytes(static_cast<std::byte*>(puppet) + 0x198) <
            sizeof(void*) ||
        child_draw == nullptr || parent_draw == nullptr ||
        readable_bytes(static_cast<std::byte*>(child_draw) + 0x18) < 6 ||
        readable_bytes(static_cast<std::byte*>(parent_draw) + 0x18) < 6) {
        return result;
    }
    void* const puppet_draw = *reinterpret_cast<void**>(
        static_cast<std::byte*>(puppet) + 0x198);
    if (parent_draw != puppet_draw) {
        return result;
    }

    if constexpr (!kEnableLegacyRuntimeDiagnostics) {
        // Cloth repair only needs a recent proof that this puppet still owns a
        // ProcessCharCloth child. Avoid the old full DrawControl/mesh/instance
        // snapshot on this per-attachable render callsite.
        if (attachable != nullptr && readable_bytes(attachable) >= 0x8C1 &&
            *reinterpret_cast<const std::uintptr_t*>(attachable) ==
                g_module + kProcessCharClothVtableRva) {
            g_remote_cloth_player.store(
                reinterpret_cast<std::uintptr_t>(puppet),
                std::memory_order_relaxed);
            g_remote_cloth_parent_draw.store(
                reinterpret_cast<std::uintptr_t>(parent_draw),
                std::memory_order_relaxed);
            g_remote_cloth_seen_ms.store(
                GetTickCount64(), std::memory_order_release);
        }
        return result;
    }

    // 0x141ED63F7 is inside NdAttachableObject_PostJointUpdate_Async and keeps
    // the current attachable in RBX. The tiny relay passes it here as R8. A
    // ProcessCharCloth owns the rendered hair in its child DrawControl, so this
    // separates an absent cloth process from an intact-but-hidden child.
    if (attachable != nullptr && readable_bytes(attachable) >= 0x8C1 &&
        *reinterpret_cast<const std::uintptr_t*>(attachable) ==
            g_module + kProcessCharClothVtableRva) {
        AttachmentDrawSnapshot cloth_draw{};
        if (seh_capture_attachment_draw_snapshot(child_draw, cloth_draw)) {
            auto* const bytes = static_cast<const std::byte*>(attachable);
            const std::uint32_t type_hash =
                *reinterpret_cast<const std::uint32_t*>(bytes + 0x38);
            const void* const parent_handle =
                *reinterpret_cast<void* const*>(bytes + 0x4E0);
            const std::uint32_t parent_id =
                *reinterpret_cast<const std::uint32_t*>(bytes + 0x4E8);
            const void* resolved_parent = nullptr;
            std::uint32_t resolved_parent_id = 0;
            if (parent_handle != nullptr && readable_bytes(parent_handle) >= 0x10) {
                resolved_parent = *reinterpret_cast<void* const*>(
                    static_cast<const std::byte*>(parent_handle) + 0x8);
                if (resolved_parent != nullptr && readable_bytes(
                        static_cast<const std::byte*>(resolved_parent) + 0xC0) >= 1) {
                    resolved_parent_id = *reinterpret_cast<const std::uint32_t*>(
                        static_cast<const std::byte*>(resolved_parent) + 0xBC);
                }
            }
            const void* const cloth_body =
                *reinterpret_cast<void* const*>(bytes + 0x238);
            const std::uint8_t initialized =
                *reinterpret_cast<const std::uint8_t*>(bytes + 0x870);

            std::uint64_t signature = attachment_draw_snapshot_signature(
                cloth_draw, type_hash, parent_id);
            signature ^= reinterpret_cast<std::uintptr_t>(attachable);
            signature *= 1099511628211ULL;
            signature ^= reinterpret_cast<std::uintptr_t>(parent_draw);
            signature *= 1099511628211ULL;
            signature ^= reinterpret_cast<std::uintptr_t>(cloth_body);
            signature *= 1099511628211ULL;
            signature ^= reinterpret_cast<std::uintptr_t>(resolved_parent);
            signature *= 1099511628211ULL;
            signature ^= initialized;

            struct ClothLogSlot {
                std::atomic<std::uintptr_t> object{0};
                std::atomic<std::uint64_t> signature{0};
            };
            static std::array<ClothLogSlot, 128> cloth_log_slots{};
            ClothLogSlot* log_slot = nullptr;
            const std::uintptr_t object_value =
                reinterpret_cast<std::uintptr_t>(attachable);
            for (auto& candidate : cloth_log_slots) {
                std::uintptr_t current =
                    candidate.object.load(std::memory_order_relaxed);
                if (current == object_value) {
                    log_slot = &candidate;
                    break;
                }
                if (current == 0 && candidate.object.compare_exchange_strong(
                        current, object_value, std::memory_order_relaxed)) {
                    log_slot = &candidate;
                    break;
                }
            }
            if (log_slot == nullptr) {
                log_slot = &cloth_log_slots[(object_value >> 4) %
                                            cloth_log_slots.size()];
                log_slot->object.store(object_value, std::memory_order_relaxed);
            }
            if (log_slot->signature.exchange(
                    signature, std::memory_order_relaxed) != signature) {
                std::ostringstream cloth_line;
                cloth_line << "CHAR-CLOTH object=0x" << std::hex
                           << reinterpret_cast<std::uintptr_t>(attachable)
                           << " type=0x" << type_hash
                           << " parentHandle=0x"
                           << reinterpret_cast<std::uintptr_t>(parent_handle)
                           << "/0x" << parent_id
                           << " resolvedParent=0x"
                           << reinterpret_cast<std::uintptr_t>(resolved_parent)
                           << "/0x" << resolved_parent_id
                           << " currentPuppet="
                           << (resolved_parent == puppet ? 1 : 0)
                           << " clothBody=0x"
                           << reinterpret_cast<std::uintptr_t>(cloth_body)
                           << " parentDraw=0x"
                           << reinterpret_cast<std::uintptr_t>(parent_draw)
                           << " childDraw=0x"
                           << reinterpret_cast<std::uintptr_t>(child_draw)
                           << " flags=0x" << cloth_draw.flags << std::dec
                           << " initialized="
                           << static_cast<unsigned>(initialized)
                           << " gate="
                           << static_cast<unsigned>(cloth_draw.own_gate) << "/"
                           << static_cast<unsigned>(cloth_draw.inherited_gate)
                           << " meshes=" << cloth_draw.readable_meshes << "/"
                           << cloth_draw.mesh_count
                           << " instances=" << cloth_draw.instances
                           << " active=" << cloth_draw.active_instances
                           << " mainViewExcluded="
                           << cloth_draw.main_view_excluded_instances
                           << " categorySuppressed="
                           << cloth_draw.category_suppressed_instances
                           << " drawIds=";
                for (std::uint32_t mesh_index = 0;
                     mesh_index < cloth_draw.readable_meshes; ++mesh_index) {
                    cloth_line << "0x" << std::hex
                               << cloth_draw.mesh_ids[mesh_index] << ",";
                }
                force_log_line(cloth_line.str().c_str());
            }
            g_remote_cloth_player.store(
                reinterpret_cast<std::uintptr_t>(puppet),
                std::memory_order_relaxed);
            g_remote_cloth_parent_draw.store(
                reinterpret_cast<std::uintptr_t>(parent_draw),
                std::memory_order_relaxed);
            g_remote_cloth_seen_ms.store(
                GetTickCount64(), std::memory_order_release);
        }
    }

    static std::atomic<std::uintptr_t> last_parent_draw{0};
    static std::atomic<ULONGLONG> last_sample_ms{0};
    const std::uintptr_t parent_value =
        reinterpret_cast<std::uintptr_t>(parent_draw);
    const bool parent_changed =
        last_parent_draw.exchange(parent_value, std::memory_order_relaxed) !=
        parent_value;
    const ULONGLONG now = GetTickCount64();
    if (!parent_changed) {
        ULONGLONG previous = last_sample_ms.load(std::memory_order_relaxed);
        if (now - previous < 250 ||
            !last_sample_ms.compare_exchange_strong(
                previous, now, std::memory_order_relaxed)) {
            return result;
        }
    } else {
        last_sample_ms.store(now, std::memory_order_relaxed);
    }

    AttachmentDrawSnapshot snapshot{};
    PlayerLookSnapshot look{};
    if (!seh_capture_attachment_draw_snapshot(parent_draw, snapshot) ||
        !seh_capture_player_look_snapshot(puppet, look)) {
        return result;
    }
    const std::uint64_t signature =
        player_draw_snapshot_signature(snapshot, look);
    static std::atomic<std::uint64_t> last_signature{0};
    if (!parent_changed &&
        last_signature.exchange(signature, std::memory_order_relaxed) ==
            signature) {
        return result;
    }
    last_signature.store(signature, std::memory_order_relaxed);

    std::ostringstream line;
    line << "PLAYER-DRAW parent=0x" << std::hex << parent_value
         << " look=0x" << look.look_id << " state=0x" << look.state_id
         << " appearance=0x" << look.appearance_id
         << " hats=0x" << look.hat_id_1 << "/0x" << look.hat_id_2
         << " flags=0x" << snapshot.flags << std::dec
         << " tracked=" << look.tracked_processes << "/"
         << look.tracked_meshes
         << " gate=" << static_cast<unsigned>(snapshot.own_gate) << "/"
         << static_cast<unsigned>(snapshot.inherited_gate)
         << " meshes=" << snapshot.readable_meshes << "/"
         << snapshot.mesh_count
         << " meshGate=" << snapshot.primary_gate_meshes << "/"
         << snapshot.secondary_gate_meshes
         << " instances=" << snapshot.instances
         << " active=" << snapshot.active_instances
         << " mainViewExcluded="
         << snapshot.main_view_excluded_instances
         << " categorySuppressed="
         << snapshot.category_suppressed_instances
         << " trackedIds=";
    for (const std::uint32_t mesh_id : look.tracked_mesh_ids) {
        if (mesh_id != 0) {
            line << "0x" << std::hex << mesh_id << ",";
        }
    }
    line << " drawIds=";
    for (std::uint32_t mesh_index = 0;
         mesh_index < snapshot.readable_meshes; ++mesh_index) {
        line << "0x" << std::hex << snapshot.mesh_ids[mesh_index] << ",";
    }
    force_log_line(line.str().c_str());
    return result;
}

bool install_nd_attachable_parent_visibility_relay() {
    auto* const call_site = reinterpret_cast<std::uint8_t*>(
        g_module + kNdAttachableSyncParentVisibilityCallsiteRva);
    if (call_site[0] != 0xE8) {
        boot_log_line("NdAttachable parent visibility relay SKIPPED (not E8)");
        return false;
    }
    std::int32_t displacement = 0;
    std::memcpy(&displacement, call_site + 1, sizeof(displacement));
    const std::uintptr_t target =
        reinterpret_cast<std::uintptr_t>(call_site + 5) +
        static_cast<std::intptr_t>(displacement);
    const std::uintptr_t expected =
        g_module + kDrawControlSyncParentVisibilityRva;
    if (target != expected) {
        boot_log_line("NdAttachable parent visibility relay SKIPPED (target)");
        return false;
    }
    g_original_draw_control_sync_parent_visibility =
        reinterpret_cast<DrawControlSyncParentVisibilityFunction>(expected);

    constexpr std::size_t kRelaySize = 17;
    auto* const relay = static_cast<std::uint8_t*>(
        allocate_executable_near(call_site, kRelaySize));
    if (relay == nullptr) {
        boot_log_line("NdAttachable parent visibility relay SKIPPED (relay)");
        return false;
    }
    // mov r8, rbx; jmp qword ptr [rip+0]. The original E8 return address stays
    // on the stack, so the hook returns directly to 0x141ED63FC.
    relay[0] = 0x49;
    relay[1] = 0x89;
    relay[2] = 0xD8;
    relay[3] = 0xFF;
    relay[4] = 0x25;
    *reinterpret_cast<std::uint32_t*>(relay + 5) = 0;
    *reinterpret_cast<std::uintptr_t*>(relay + 9) =
        reinterpret_cast<std::uintptr_t>(
            &hooked_nd_attachable_sync_parent_visibility_callsite);
    FlushInstructionCache(GetCurrentProcess(), relay, kRelaySize);

    const std::int64_t new_displacement =
        reinterpret_cast<std::intptr_t>(relay) -
        reinterpret_cast<std::intptr_t>(call_site + 5);
    if (new_displacement < INT32_MIN || new_displacement > INT32_MAX) {
        VirtualFree(relay, 0, MEM_RELEASE);
        boot_log_line("NdAttachable parent visibility relay SKIPPED (range)");
        return false;
    }
    DWORD old_protection = 0;
    if (!VirtualProtect(
            call_site, 5, PAGE_EXECUTE_READWRITE, &old_protection)) {
        VirtualFree(relay, 0, MEM_RELEASE);
        boot_log_line("NdAttachable parent visibility relay SKIPPED (protect)");
        return false;
    }
    *reinterpret_cast<std::int32_t*>(call_site + 1) =
        static_cast<std::int32_t>(new_displacement);
    FlushInstructionCache(GetCurrentProcess(), call_site, 5);
    DWORD ignored = 0;
    VirtualProtect(call_site, 5, old_protection, &ignored);
    boot_log_line("NdAttachable parent visibility callsite relay installed");
    return true;
}

